import { prisma } from '../config/database';
import { runRaffleDraw } from './raffle';

let intervalId: NodeJS.Timeout | null = null;

/**
 * Periodically checks for active raffles whose countdown timers have elapsed.
 * - If tickets were sold (>0): Executes automated cryptographic random winner draw.
 * - If 0 tickets were sold (Option C): Marks status as EXPIRED for Admin re-scheduling / extension.
 */
export const checkExpiredRaffles = async () => {
  try {
    const now = new Date();

    const expiredRaffles = await prisma.raffle.findMany({
      where: {
        status: { in: ['ACTIVE', 'SCHEDULED'] },
        raffleDate: { lte: now },
      },
      select: {
        id: true,
        ticketsSold: true,
        raffleDate: true,
        item: { select: { name: true } },
      },
    });

    if (expiredRaffles.length === 0) return;

    console.log(
      `[CronService] Found ${expiredRaffles.length} raffle(s) with elapsed countdown timers.`,
    );

    for (const raffle of expiredRaffles) {
      if (raffle.ticketsSold > 0) {
        console.log(
          `[CronService] Auto-drawing winner for expired raffle "${raffle.item.name}" (${raffle.id}) with ${raffle.ticketsSold} ticket(s) sold...`,
        );
        try {
          const result = await runRaffleDraw(raffle.id);
          console.log(
            `[CronService] Winner drawn for "${raffle.item.name}": ${result.winnerName} (${result.winnerUserNumber})`,
          );
        } catch (drawErr) {
          console.error(`[CronService] Error drawing winner for raffle ${raffle.id}:`, drawErr);
        }
      } else {
        // Option C: 0 tickets sold -> Mark as EXPIRED for Admin alert & re-scheduling
        console.log(
          `[CronService] Raffle "${raffle.item.name}" (${raffle.id}) timer elapsed with 0 tickets sold. Marking as EXPIRED (Option C).`,
        );
        await prisma.raffle.update({
          where: { id: raffle.id },
          data: { status: 'EXPIRED' as any },
        });
      }
    }
  } catch (error) {
    console.error('[CronService] Error running expired raffles check:', error);
  }
};

/**
 * Starts the background polling timer service (runs every 15 seconds).
 */
export const startCronService = () => {
  if (intervalId) return;

  console.log(
    '⏱  [CronService] Starting automated raffle expiration & auto-draw background worker (15s interval)...',
  );

  // Run immediately on start
  checkExpiredRaffles();

  // Schedule every 15 seconds
  intervalId = setInterval(() => {
    checkExpiredRaffles();
  }, 15000);
};

/**
 * Stops the background polling service gracefully.
 */
export const stopCronService = () => {
  if (intervalId) {
    clearInterval(intervalId);
    intervalId = null;
    console.log('[CronService] Background worker stopped.');
  }
};

import { env } from '../config/environment';

interface EmailOptions {
  to: string;
  subject: string;
  htmlContent: string;
}

const sendEmail = async (options: EmailOptions): Promise<boolean> => {
  if (!env.BREVO_API_KEY || env.BREVO_API_KEY.includes('your_') || env.BREVO_API_KEY === '') {
    console.warn('[Email] BREVO_API_KEY not configured. Mocking email send in development.');
    console.log(`[Email Mock] To: ${options.to} | Subject: ${options.subject}`);
    return true;
  }

  try {
    const response = await fetch('https://api.brevo.com/v3/smtp/email', {
      method: 'POST',
      headers: {
        accept: 'application/json',
        'api-key': env.BREVO_API_KEY,
        'content-type': 'application/json',
      },
      body: JSON.stringify({
        sender: {
          name: env.BREVO_SENDER_NAME || 'myRaffle',
          email: env.BREVO_SENDER_EMAIL || 'noreply@myraffle.com',
        },
        to: [{ email: options.to }],
        subject: options.subject,
        htmlContent: options.htmlContent,
      }),
    });

    if (!response.ok) {
      const errorData: any = await response.json().catch(() => ({}));
      console.warn(
        '[Email] Brevo API response error (mocking success for dev):',
        errorData?.message || errorData,
      );
      console.log(`[Email Dev Fallback] Content intended for ${options.to}:`, options.subject);
      return true; // Fallback to true in dev so authentication flow completes
    }

    console.log(`[Email] Sent successfully to ${options.to}`);
    return true;
  } catch (error) {
    console.error('[Email] Failed to send:', error);
    return true; // Return true in dev so process isn't blocked
  }
};

