            {/* Formatting Group */}
            <div className="flex items-center gap-0.5 border-r border-gray-300 pr-2">
              <button
                type="button"
                onClick={() => format('bold')}
                className="p-2 hover:bg-gray-200 rounded-lg text-gray-700 transition"
                title="Bold (Ctrl+B)"
              >
                <Bold size={16} />
              </button>
              <button
