type TransactionType =
  | 'DEPOSIT'
  | 'WITHDRAWAL'
  | 'TICKET_PURCHASE'
  | 'TASK_REWARD'
  | 'RAFFLE_WIN'
  | 'REFUND';

const TYPE_OPTIONS = [
  { value: 'all', label: 'All Types' },
  { value: 'DEPOSIT', label: 'Deposits' },
  { value: 'TICKET_PURCHASE', label: 'Ticket Purchases' },
  { value: 'TASK_REWARD', label: 'Task Rewards' },
  { value: 'RAFFLE_WIN', label: 'Raffle Wins' },
  { value: 'REFUND', label: 'Refunds' },
];

export default function AdminTransactionsPage() {
  const [searchTerm, setSearchTerm] = useState('');
  const [typeFilter, setTypeFilter] = useState('all');
  const [statusFilter, setStatusFilter] = useState('all');
  const [page, setPage] = useState(1);

  const { data, isLoading, error, refetch } = useAdminTransactions({
    page,
    limit: 20,
    type: typeFilter !== 'all' ? typeFilter : undefined,
    status: statusFilter !== 'all' ? statusFilter : undefined,
    search: searchTerm || undefined,
  });

  const transactions = data?.transactions ?? [];
  const pagination = data?.pagination;

  // Working CSV export function
  const handleExportCSV = () => {
    if (!transactions.length) return;
    const headers = ['Reference', 'User', 'User ID', 'Type', 'Amount (NGN)', 'Status', 'Date'];
    const rows = transactions.map((tx) => [
      `"${tx.reference || tx.id}"`,
      `"${tx.user?.name || 'Unknown'}"`,
      `"${tx.user?.userNumber || ''}"`,
      `"${tx.type}"`,
      tx.amount,
      `"${tx.status}"`,
      `"${new Date(tx.createdAt).toLocaleString()}"`,
    ]);
    const csvContent = [headers.join(','), ...rows.map((e) => e.join(','))].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute(
      'download',
      `transactions_export_${new Date().toISOString().split('T')[0]}.csv`,
    );
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const getTypeBadge = (type: string) => {
    const configs: Record<string, { label: string; style: string }> = {
      DEPOSIT: { label: 'Deposit', style: 'bg-emerald-50 text-emerald-700 border-emerald-200' },
      WITHDRAWAL: { label: 'Withdrawal', style: 'bg-blue-50 text-blue-700 border-blue-200' },
      TICKET_PURCHASE: {
        label: 'Purchase',
        style: 'bg-purple-50 text-purple-700 border-purple-200',
      },
      TASK_REWARD: { label: 'Task Reward', style: 'bg-amber-50 text-amber-700 border-amber-200' },
      RAFFLE_WIN: { label: 'Raffle Win', style: 'bg-orange-50 text-orange-700 border-orange-200' },
      REFUND: { label: 'Refund', style: 'bg-gray-100 text-gray-700 border-gray-200' },
    };
    const conf = configs[type] || {
      label: type,
      style: 'bg-gray-100 text-gray-700 border-gray-200',
    };
    return (
