export default function AdminWinsPage() {
  const [filterStatus, setFilterStatus] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [page, setPage] = useState(1);
  const { data, isLoading, refetch } = useAdminWins({ page, deliveryStatus: filterStatus });
  const updateDelivery = useUpdateDeliveryStatus();

  const [selectedWinForConversion, setSelectedWinForConversion] = useState<any>(null);
  const [conversionAmount, setConversionAmount] = useState<number>(0);
  const [conversionNote, setConversionNote] = useState('');
  const [isConverting, setIsConverting] = useState(false);
  const [copiedField, setCopiedField] = useState<string | null>(null);

  const wins = data?.wins ?? [];
  const pagination = data?.pagination ?? null;

  const copyToClipboard = (text: string, label: string) => {
    if (!text) return;
    navigator.clipboard.writeText(text);
    setCopiedField(label);
    toast.success(`Copied ${label}`);
    setTimeout(() => setCopiedField(null), 2000);
  };

  const handleStatusChange = async (raffleId: string, newStatus: string) => {
    try {
      await updateDelivery.mutateAsync({ raffleId, deliveryStatus: newStatus });
      toast.success(`Delivery status updated to ${newStatus}`);
    } catch (err: any) {
      toast.error(err.message || 'Failed to update delivery status');
    }
  };

  const handleOpenConversionModal = (win: any) => {
    setSelectedWinForConversion(win);
    setConversionAmount(win.item?.value || 0);
    setConversionNote(
      `Unclaimed/Unavailable physical prize converted to non-withdrawable store credits for ${win.item?.name}.`,
    );
  };

  const handleConfirmConversion = async () => {
    if (!selectedWinForConversion) return;
    setIsConverting(true);
    try {
      const res = (await api.post(
        `/api/admin/wins/${selectedWinForConversion.id}/convert-to-wallet`,
        {
          amount: conversionAmount,
          note: conversionNote,
        },
      )) as any;

      if (res.success) {
        toast.success(res.message || 'Prize successfully converted to store credits!');
        setSelectedWinForConversion(null);
        refetch();
      } else {
        toast.error(res.message || 'Failed to convert prize');
      }
    } catch (err: any) {
      toast.error(err.message || 'Error converting prize to store credit');
    } finally {
      setIsConverting(false);
    }
  };

  // Filter by search query (winner name, email, item name)
  const filteredWins = wins.filter((w: any) => {
    if (!searchQuery.trim()) return true;
    const q = searchQuery.toLowerCase();
    return (
      w.item?.name?.toLowerCase().includes(q) ||
      w.winner?.name?.toLowerCase().includes(q) ||
      w.winner?.email?.toLowerCase().includes(q) ||
      w.winner?.userNumber?.toLowerCase().includes(q)
    );
  });

  // KPI Metrics calculation
  const totalWinsCount = wins.length;
  const pendingCount = wins.filter(
    (w: any) => w.deliveryStatus === 'PENDING' || w.deliveryStatus === 'PROCESSING',
  ).length;
  const deliveredCount = wins.filter((w: any) => w.deliveryStatus === 'DELIVERED').length;
  const convertedCount = wins.filter((w: any) => w.deliveryStatus === 'CONVERTED_TO_WALLET').length;

  return (
    <div className="space-y-6 pb-20 md:pb-0">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl sm:text-3xl font-bold text-slate-900 flex items-center gap-2.5">
            <div className="p-2 bg-amber-50 text-amber-600 rounded-xl">
              <Trophy size={24} />
            </div>
            Wins & Claims Management
          </h1>
          <p className="text-sm text-slate-500 mt-1">
            Track raffle prize claims, manage winner delivery fulfillment, and handle store credit
            conversions.
          </p>
        </div>
      </div>

      {/* KPI Summary Cards */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4">
        <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3">
          <div className="p-3 bg-amber-50 text-amber-600 rounded-xl shrink-0">
            <Trophy size={22} />
          </div>
          <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
              Total Winners
            </p>
            <p className="text-xl sm:text-2xl font-bold text-slate-900 mt-0.5">{totalWinsCount}</p>
          </div>
        </div>

        <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3">
          <div className="p-3 bg-blue-50 text-blue-600 rounded-xl shrink-0">
            <Clock size={22} />
          </div>
          <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
              Pending Delivery
            </p>
            <p className="text-xl sm:text-2xl font-bold text-blue-600 mt-0.5">{pendingCount}</p>
          </div>
        </div>

        <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3">
          <div className="p-3 bg-emerald-50 text-emerald-600 rounded-xl shrink-0">
            <CheckCircle size={22} />
          </div>
          <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
              Delivered
            </p>
            <p className="text-xl sm:text-2xl font-bold text-emerald-600 mt-0.5">
              {deliveredCount}
            </p>
          </div>
        </div>

        <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3">
          <div className="p-3 bg-purple-50 text-purple-600 rounded-xl shrink-0">
            <Wallet size={22} />
          </div>
          <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
              Converted Credits
            </p>
            <p className="text-xl sm:text-2xl font-bold text-purple-600 mt-0.5">{convertedCount}</p>
          </div>
        </div>
      </div>

      {/* Filter Toolbar */}
      <div className="bg-white p-4 rounded-2xl border border-slate-200/80 shadow-xs flex flex-col sm:flex-row gap-3">
        <div className="relative flex-1">
          <Search size={18} className="absolute left-3.5 top-3 text-slate-400" />
          <input
            type="text"
            placeholder="Search winner name, email, or item..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:outline-none focus:border-red-500 transition"
          />
        </div>

        <div className="flex items-center gap-2">
          <Filter size={18} className="text-slate-400 shrink-0" />
          <select
            value={filterStatus}
            onChange={(e) => {
              setFilterStatus(e.target.value);
              setPage(1);
            }}
            className="w-full sm:w-auto px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm font-semibold text-slate-700 focus:outline-none focus:border-red-500"
          >
            <option value="all">All Delivery Statuses</option>
            {DELIVERY_STATUSES.map((s) => (
              <option key={s.value} value={s.value}>
                {s.label}
              </option>
            ))}
          </select>
        </div>
      </div>

      {/* Loading */}
      {isLoading && (
        <div className="space-y-4">
          {[1, 2, 3].map((i) => (
            <div
              key={i}
              className="bg-white rounded-2xl p-6 border border-slate-100 shadow-xs animate-pulse space-y-4"
            >
              <div className="h-5 w-1/3 bg-slate-200 rounded" />
              <div className="h-4 w-2/3 bg-slate-200 rounded" />
              <div className="h-8 w-1/4 bg-slate-200 rounded" />
            </div>
          ))}
        </div>
      )}

      {/* Wins List */}
      {!isLoading && (
        <div className="space-y-4">
          {filteredWins.map((win: any) => {
            const currentStatus =
              DELIVERY_STATUSES.find((s) => s.value === win.deliveryStatus) || DELIVERY_STATUSES[0];
            const StatusIcon = currentStatus.icon;
            const imageUrl = win.item?.imageUrl?.startsWith('/uploads')
              ? `${process.env.NEXT_PUBLIC_API_URL || 'http://localhost:5000'}${win.item.imageUrl}`
              : win.item?.imageUrl;

            const winnerAddress = [win.winner?.address, win.winner?.city, win.winner?.state]
              .filter(Boolean)
              .join(', ');

            return (
              <div
                key={win.id}
                className="bg-white rounded-2xl border border-slate-200/80 p-5 shadow-xs hover:shadow-md transition space-y-4"
              >
                <div className="flex flex-col md:flex-row gap-5">
                  {/* Item Image */}
                  <div className="w-20 h-20 sm:w-24 sm:h-24 bg-slate-100 rounded-xl overflow-hidden shrink-0 border border-slate-100 flex items-center justify-center">
                    {imageUrl ? (
                      <img
                        src={imageUrl}
                        alt={win.item?.name}
                        className="w-full h-full object-cover"
                      />
                    ) : (
                      <span className="text-3xl">🏆</span>
                    )}
                  </div>

                  {/* Info & Winner Address */}
                  <div className="flex-1 min-w-0 space-y-3">
                    <div className="flex flex-wrap items-start justify-between gap-2">
                      <div>
                        <h3 className="font-bold text-slate-900 text-base sm:text-lg flex items-center gap-2">
                          {win.item?.name}
                          <span className="text-xs bg-red-50 text-red-600 px-2 py-0.5 rounded-full font-bold border border-red-100">
                            ₦{win.item?.value?.toLocaleString()}
                          </span>
                        </h3>
                      </div>
                      <span
                        className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold border ${currentStatus.color}`}
                      >
                        <StatusIcon size={14} />
                        {currentStatus.label}
                      </span>
                    </div>

                    {/* Winner Details Box */}
                    <div className="p-3.5 bg-slate-50 rounded-xl border border-slate-200/60 text-xs space-y-2">
                      <div className="flex items-center justify-between">
                        <p className="font-bold text-slate-800 text-sm">
                          Winner: <span className="text-red-600">{win.winner?.name}</span>{' '}
                          <span className="font-mono text-slate-400 text-[11px]">
                            ({win.winner?.userNumber})
                          </span>
                        </p>
                      </div>

                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 text-slate-600 pt-1">
                        {win.winner?.email && (
                          <div className="flex items-center justify-between bg-white px-2.5 py-1.5 rounded-lg border border-slate-200/60">
                            <span className="flex items-center gap-1.5 truncate">
                              <Mail size={13} className="text-slate-400 shrink-0" />
                              <span className="truncate">{win.winner.email}</span>
                            </span>
                            <button
                              onClick={() => copyToClipboard(win.winner.email, 'Email')}
                              className="text-slate-400 hover:text-slate-700 p-1"
                              title="Copy email"
                            >
                              {copiedField === 'Email' ? (
                                <Check size={13} className="text-emerald-600" />
                              ) : (
                                <Copy size={13} />
                              )}
                            </button>
                          </div>
                        )}

                        {win.winner?.phone && (
                          <div className="flex items-center justify-between bg-white px-2.5 py-1.5 rounded-lg border border-slate-200/60">
                            <span className="flex items-center gap-1.5 truncate">
                              <Phone size={13} className="text-slate-400 shrink-0" />
                              <span>{win.winner.phone}</span>
                            </span>
                            <button
                              onClick={() => copyToClipboard(win.winner.phone, 'Phone')}
                              className="text-slate-400 hover:text-slate-700 p-1"
                              title="Copy phone"
                            >
                              {copiedField === 'Phone' ? (
                                <Check size={13} className="text-emerald-600" />
                              ) : (
                                <Copy size={13} />
                              )}
                            </button>
                          </div>
                        )}
                      </div>

                      {winnerAddress ? (
                        <div className="pt-1 flex items-start gap-1.5 font-medium text-slate-700">
                          <MapPin size={14} className="text-red-500 shrink-0 mt-0.5" />
                          <span>
                            <strong>Shipping Address:</strong> {winnerAddress}
                          </span>
                        </div>
                      ) : (
                        <div className="pt-1 flex items-center gap-1.5 italic text-slate-400">
                          <MapPin size={13} className="text-slate-300" />
                          <span>Delivery address not yet set in winner profile</span>
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Action Box */}
                  <div className="flex flex-col gap-2.5 justify-center md:items-end shrink-0 pt-3 md:pt-0 border-t md:border-t-0 border-slate-100">
                    <label className="text-[11px] font-bold text-slate-400 uppercase tracking-wider">
                      Update Delivery Status
                    </label>
                    <select
                      value={win.deliveryStatus}
                      onChange={(e) => handleStatusChange(win.id, e.target.value)}
                      disabled={
                        updateDelivery.isPending || win.deliveryStatus === 'CONVERTED_TO_WALLET'
                      }
                      className="text-xs px-3.5 py-2.5 border border-slate-200 rounded-xl focus:outline-none focus:border-red-500 bg-white font-bold text-slate-700 disabled:opacity-50 shadow-xs"
                    >
                      {DELIVERY_STATUSES.map((s) => (
                        <option key={s.value} value={s.value}>
                          {s.label}
                        </option>
                      ))}
                    </select>

                    {win.deliveryStatus !== 'CONVERTED_TO_WALLET' && (
                      <button
                        onClick={() => handleOpenConversionModal(win)}
                        className="inline-flex items-center justify-center gap-1.5 px-3.5 py-2 bg-purple-50 hover:bg-purple-100 text-purple-700 border border-purple-200/80 rounded-xl text-xs font-bold transition shadow-xs"
                      >
                        <Wallet size={14} />
                        Convert Prize to Store Credits
                      </button>
                    )}
                  </div>
                </div>

                {/* Delivery Note */}
                {win.deliveryNote && (
                  <div className="pt-3 border-t border-slate-100 text-xs text-slate-500">
                    <strong className="text-slate-700">Delivery Note:</strong> {win.deliveryNote}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}

      {/* Conversion Modal */}
      {selectedWinForConversion && (
        <div className="fixed inset-0 z-[1001] bg-black/60 backdrop-blur-sm flex items-end sm:items-center justify-center p-0 sm:p-4">
          <div className="bg-white rounded-t-3xl sm:rounded-2xl max-w-md w-full p-6 pb-20 sm:pb-6 shadow-2xl space-y-4 animate-in slide-in-from-bottom sm:zoom-in-95 duration-200">
            {/* Mobile Sheet Bar */}
            <div className="w-12 h-1.5 bg-slate-200 rounded-full mx-auto sm:hidden mb-1" />

            <div className="flex items-center gap-3 text-purple-700">
              <div className="p-3 bg-purple-100 rounded-xl shrink-0">
                <Wallet size={24} />
              </div>
              <div>
                <h3 className="font-bold text-lg text-slate-900">Convert Prize to Store Credits</h3>
                <p className="text-xs text-slate-500">
                  Credit winner&apos;s non-withdrawable wallet balance
                </p>
              </div>
            </div>

            <div className="p-3.5 bg-purple-50 rounded-xl border border-purple-100 text-xs space-y-1.5 text-purple-900 font-medium">
              <p>
                Winner: <strong>{selectedWinForConversion.winner?.name}</strong>
              </p>
              <p>
                Prize Item: <strong>{selectedWinForConversion.item?.name}</strong>
              </p>
              <p>
                Item Market Value:{' '}
                <strong>₦{selectedWinForConversion.item?.value?.toLocaleString()}</strong>
              </p>
              <div className="text-[11px] text-purple-700 bg-purple-100/70 p-2.5 rounded-lg mt-2 font-normal leading-relaxed">
                💡 Credited funds are non-withdrawable cash and can only be used by the winner to
                purchase raffle tickets on the platform.
              </div>
            </div>

            <div className="space-y-3">
              <div>
                <label className="block text-xs font-bold text-slate-700 uppercase mb-1">
                  Credit Amount (₦)
                </label>
                <input
                  type="number"
                  value={conversionAmount}
                  onChange={(e) => setConversionAmount(Number(e.target.value))}
                  className="w-full px-3.5 py-2.5 border border-slate-200 rounded-xl text-sm focus:outline-none focus:border-purple-600 font-bold"
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 uppercase mb-1">
                  Admin Note / Reason
                </label>
                <textarea
                  value={conversionNote}
                  onChange={(e) => setConversionNote(e.target.value)}
                  rows={3}
                  className="w-full px-3.5 py-2.5 border border-slate-200 rounded-xl text-xs focus:outline-none focus:border-purple-600 resize-none"
                />
              </div>
            </div>

            <div className="flex items-center justify-end gap-2 pt-2">
              <button
                onClick={() => setSelectedWinForConversion(null)}
                className="px-4 py-2.5 text-xs font-bold text-slate-600 hover:bg-slate-100 rounded-xl transition"
              >
                Cancel
              </button>
              <button
                onClick={handleConfirmConversion}
                disabled={isConverting}
                className="px-5 py-2.5 text-xs font-bold text-white bg-purple-700 hover:bg-purple-800 rounded-xl shadow-md transition disabled:opacity-50"
              >
                {isConverting ? 'Converting...' : 'Confirm & Credit Wallet'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Empty State */}
      {!isLoading && filteredWins.length === 0 && (
        <div className="bg-white rounded-2xl border border-slate-200/80 p-12 text-center">
          <Trophy size={48} className="mx-auto text-slate-300 mb-3" />
          <h3 className="text-lg font-bold text-slate-700">No win records found</h3>
          <p className="text-sm text-slate-500 mt-1">
            Completed raffles with winning claims will appear here.
          </p>
        </div>
      )}

      {/* Pagination */}
      {pagination && pagination.totalPages > 1 && (
        <div className="flex justify-center items-center gap-2 pt-4">
          <button
            disabled={page <= 1}
            onClick={() => setPage((p) => p - 1)}
            className="px-4 py-2 text-xs font-bold bg-white border border-slate-200 rounded-xl disabled:opacity-50 hover:bg-slate-50 transition"
          >
            Previous
          </button>
          <span className="px-4 py-2 text-xs text-slate-600 font-semibold">
            Page {page} of {pagination.totalPages}
          </span>
          <button
            disabled={page >= pagination.totalPages}
            onClick={() => setPage((p) => p + 1)}
            className="px-4 py-2 text-xs font-bold bg-white border border-slate-200 rounded-xl disabled:opacity-50 hover:bg-slate-50 transition"
          >
            Next
          </button>
        </div>
      )}
    </div>
  );
}

'use client';

import { api } from '@/lib/api';
import { useAdminWins, useUpdateDeliveryStatus } from '@/lib/hooks/useAdmin';
import {
  ArrowUpRight,
  Check,
  CheckCircle,
  Clock,
  Copy,
  Filter,
  Mail,
  MapPin,
  Package,
  Phone,
  Search,
  Trophy,
  Truck,
  Wallet,
} from 'lucide-react';
import { useState } from 'react';
import toast from 'react-hot-toast';

const DELIVERY_STATUSES = [
  {
    value: 'PENDING',
    label: 'Pending',
    icon: Clock,
    color: 'bg-amber-50 text-amber-700 border-amber-200',
  },
  {
    value: 'PROCESSING',
    label: 'Processing',
    icon: Package,
    color: 'bg-blue-50 text-blue-700 border-blue-200',
  },
  {
    value: 'SHIPPED',
    label: 'Shipped',
    icon: Truck,
    color: 'bg-indigo-50 text-indigo-700 border-indigo-200',
  },
  {
    value: 'DELIVERED',
    label: 'Delivered',
    icon: CheckCircle,
    color: 'bg-emerald-50 text-emerald-700 border-emerald-200',
  },
  {
    value: 'CONVERTED_TO_WALLET',
    label: 'Converted to Credits',
    icon: Wallet,
    color: 'bg-purple-50 text-purple-700 border-purple-200',
  },
];

export default function AdminWinsPage() {
  const [filterStatus, setFilterStatus] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [page, setPage] = useState(1);
  const { data, isLoading, refetch } = useAdminWins({ page, deliveryStatus: filterStatus });
  const updateDelivery = useUpdateDeliveryStatus();

  const [selectedWinForConversion, setSelectedWinForConversion] = useState<any>(null);
  const [conversionAmount, setConversionAmount] = useState<number>(0);
  const [conversionNote, setConversionNote] = useState('');
  const [isConverting, setIsConverting] = useState(false);
  const [copiedField, setCopiedField] = useState<string | null>(null);

  const wins = data?.wins ?? [];
  const pagination = data?.pagination ?? null;

  const copyToClipboard = (text: string, label: string) => {
    if (!text) return;
    navigator.clipboard.writeText(text);
    setCopiedField(label);
    toast.success(`Copied ${label}`);
    setTimeout(() => setCopiedField(null), 2000);
  };

  const handleStatusChange = async (raffleId: string, newStatus: string) => {
    try {
      await updateDelivery.mutateAsync({ raffleId, deliveryStatus: newStatus });
      toast.success(`Delivery status updated to ${newStatus}`);
    } catch (err: any) {
      toast.error(err.message || 'Failed to update delivery status');
    }
  };

  const handleOpenConversionModal = (win: any) => {
    setSelectedWinForConversion(win);
    setConversionAmount(win.item?.value || 0);
    setConversionNote(
      `Unclaimed/Unavailable physical prize converted to non-withdrawable store credits for ${win.item?.name}.`,
    );
  };

  const handleConfirmConversion = async () => {
    if (!selectedWinForConversion) return;
    setIsConverting(true);
    try {
      const res = (await api.post(
        `/api/admin/wins/${selectedWinForConversion.id}/convert-to-wallet`,
        {
          amount: conversionAmount,
          note: conversionNote,
        },
      )) as any;

      if (res.success) {
        toast.success(res.message || 'Prize successfully converted to store credits!');
        setSelectedWinForConversion(null);
        refetch();
      } else {
        toast.error(res.message || 'Failed to convert prize');
      }
    } catch (err: any) {
      toast.error(err.message || 'Error converting prize to store credit');
    } finally {
      setIsConverting(false);
    }
  };

  // Filter by search query (winner name, email, item name)
  const filteredWins = wins.filter((w: any) => {
    if (!searchQuery.trim()) return true;
    const q = searchQuery.toLowerCase();
    return (
      w.item?.name?.toLowerCase().includes(q) ||
      w.winner?.name?.toLowerCase().includes(q) ||
      w.winner?.email?.toLowerCase().includes(q) ||
      w.winner?.userNumber?.toLowerCase().includes(q)
    );
  });

  // KPI Metrics calculation
  const totalWinsCount = wins.length;
  const pendingCount = wins.filter(
    (w: any) => w.deliveryStatus === 'PENDING' || w.deliveryStatus === 'PROCESSING',
  ).length;
  const deliveredCount = wins.filter((w: any) => w.deliveryStatus === 'DELIVERED').length;
  const convertedCount = wins.filter((w: any) => w.deliveryStatus === 'CONVERTED_TO_WALLET').length;

  return (
    <div className="space-y-6 pb-20 md:pb-0">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl sm:text-3xl font-bold text-slate-900 flex items-center gap-2.5">
            <div className="p-2 bg-amber-50 text-amber-600 rounded-xl">
              <Trophy size={24} />
            </div>
            Wins & Claims Management
          </h1>
          <p className="text-sm text-slate-500 mt-1">
            Track raffle prize claims, manage winner delivery fulfillment, and handle store credit
            conversions.
          </p>
        </div>
      </div>

      {/* KPI Summary Cards */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4">
        <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3">
          <div className="p-3 bg-amber-50 text-amber-600 rounded-xl shrink-0">
            <Trophy size={22} />
          </div>
          <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
              Total Winners
            </p>
            <p className="text-xl sm:text-2xl font-bold text-slate-900 mt-0.5">{totalWinsCount}</p>
          </div>
        </div>

        <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3">
          <div className="p-3 bg-blue-50 text-blue-600 rounded-xl shrink-0">
            <Clock size={22} />
          </div>
          <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
              Pending Delivery
            </p>
            <p className="text-xl sm:text-2xl font-bold text-blue-600 mt-0.5">{pendingCount}</p>
          </div>
        </div>

        <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3">
          <div className="p-3 bg-emerald-50 text-emerald-600 rounded-xl shrink-0">
            <CheckCircle size={22} />
          </div>
          <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
              Delivered
            </p>
            <p className="text-xl sm:text-2xl font-bold text-emerald-600 mt-0.5">
              {deliveredCount}
            </p>
          </div>
        </div>

        <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3">
          <div className="p-3 bg-purple-50 text-purple-600 rounded-xl shrink-0">
            <Wallet size={22} />
          </div>
          <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
              Converted Credits
            </p>
            <p className="text-xl sm:text-2xl font-bold text-purple-600 mt-0.5">{convertedCount}</p>
          </div>
        </div>
      </div>

      {/* Filter Toolbar */}
      <div className="bg-white p-4 rounded-2xl border border-slate-200/80 shadow-xs flex flex-col sm:flex-row gap-3">
        <div className="relative flex-1">
          <Search size={18} className="absolute left-3.5 top-3 text-slate-400" />
          <input
            type="text"
            placeholder="Search winner name, email, or item..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:outline-none focus:border-red-500 transition"
          />
        </div>

        <div className="flex items-center gap-2">
          <Filter size={18} className="text-slate-400 shrink-0" />
          <select
            value={filterStatus}
            onChange={(e) => {
              setFilterStatus(e.target.value);
              setPage(1);
            }}
            className="w-full sm:w-auto px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm font-semibold text-slate-700 focus:outline-none focus:border-red-500"
          >
            <option value="all">All Delivery Statuses</option>
            {DELIVERY_STATUSES.map((s) => (
              <option key={s.value} value={s.value}>
                {s.label}
              </option>
            ))}
          </select>
        </div>
      </div>

      {/* Loading */}
      {isLoading && (
        <div className="space-y-4">
          {[1, 2, 3].map((i) => (
            <div
              key={i}
              className="bg-white rounded-2xl p-6 border border-slate-100 shadow-xs animate-pulse space-y-4"
            >
              <div className="h-5 w-1/3 bg-slate-200 rounded" />
              <div className="h-4 w-2/3 bg-slate-200 rounded" />
              <div className="h-8 w-1/4 bg-slate-200 rounded" />
            </div>
          ))}
        </div>
      )}

      {/* Wins List */}
      {!isLoading && (
        <div className="space-y-4">
          {filteredWins.map((win: any) => {
            const currentStatus =
              DELIVERY_STATUSES.find((s) => s.value === win.deliveryStatus) || DELIVERY_STATUSES[0];
            const StatusIcon = currentStatus.icon;
            const imageUrl = win.item?.imageUrl?.startsWith('/uploads')
              ? `${process.env.NEXT_PUBLIC_API_URL || 'http://localhost:5000'}${win.item.imageUrl}`
              : win.item?.imageUrl;

            const winnerAddress = [win.winner?.address, win.winner?.city, win.winner?.state]
              .filter(Boolean)
              .join(', ');

            return (
              <div
                key={win.id}
                className="bg-white rounded-2xl border border-slate-200/80 p-5 shadow-xs hover:shadow-md transition space-y-4"
              >
                <div className="flex flex-col md:flex-row gap-5">
                  {/* Item Image */}
                  <div className="w-20 h-20 sm:w-24 sm:h-24 bg-slate-100 rounded-xl overflow-hidden shrink-0 border border-slate-100 flex items-center justify-center">
                    {imageUrl ? (
                      <img
                        src={imageUrl}
                        alt={win.item?.name}
                        className="w-full h-full object-cover"
                      />
                    ) : (
                      <span className="text-3xl">🏆</span>
                    )}
                  </div>

                  {/* Info & Winner Address */}
                  <div className="flex-1 min-w-0 space-y-3">
                    <div className="flex flex-wrap items-start justify-between gap-2">
                      <div>
                        <h3 className="font-bold text-slate-900 text-base sm:text-lg flex items-center gap-2">
                          {win.item?.name}
                          <span className="text-xs bg-red-50 text-red-600 px-2 py-0.5 rounded-full font-bold border border-red-100">
                            ₦{win.item?.value?.toLocaleString()}
                          </span>
                        </h3>
                      </div>
                      <span
                        className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold border ${currentStatus.color}`}
                      >
                        <StatusIcon size={14} />
                        {currentStatus.label}
                      </span>
                    </div>

                    {/* Winner Details Box */}
                    <div className="p-3.5 bg-slate-50 rounded-xl border border-slate-200/60 text-xs space-y-2">
                      <div className="flex items-center justify-between">
                        <p className="font-bold text-slate-800 text-sm">
                          Winner: <span className="text-red-600">{win.winner?.name}</span>{' '}
                          <span className="font-mono text-slate-400 text-[11px]">
                            ({win.winner?.userNumber})
                          </span>
                        </p>
                      </div>

                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 text-slate-600 pt-1">
                        {win.winner?.email && (
                          <div className="flex items-center justify-between bg-white px-2.5 py-1.5 rounded-lg border border-slate-200/60">
                            <span className="flex items-center gap-1.5 truncate">
                              <Mail size={13} className="text-slate-400 shrink-0" />
                              <span className="truncate">{win.winner.email}</span>
                            </span>
                            <button
                              onClick={() => copyToClipboard(win.winner.email, 'Email')}
                              className="text-slate-400 hover:text-slate-700 p-1"
                              title="Copy email"
                            >
                              {copiedField === 'Email' ? (
                                <Check size={13} className="text-emerald-600" />
                              ) : (
                                <Copy size={13} />
                              )}
                            </button>
                          </div>
                        )}

                        {win.winner?.phone && (
                          <div className="flex items-center justify-between bg-white px-2.5 py-1.5 rounded-lg border border-slate-200/60">
                            <span className="flex items-center gap-1.5 truncate">
                              <Phone size={13} className="text-slate-400 shrink-0" />
                              <span>{win.winner.phone}</span>
                            </span>
                            <button
                              onClick={() => copyToClipboard(win.winner.phone, 'Phone')}
                              className="text-slate-400 hover:text-slate-700 p-1"
                              title="Copy phone"
                            >
                              {copiedField === 'Phone' ? (
                                <Check size={13} className="text-emerald-600" />
                              ) : (
                                <Copy size={13} />
                              )}
                            </button>
                          </div>
                        )}
                      </div>

                      {winnerAddress ? (
                        <div className="pt-1 flex items-start gap-1.5 font-medium text-slate-700">
                          <MapPin size={14} className="text-red-500 shrink-0 mt-0.5" />
                          <span>
                            <strong>Shipping Address:</strong> {winnerAddress}
                          </span>
                        </div>
                      ) : (
                        <div className="pt-1 flex items-center gap-1.5 italic text-slate-400">
                          <MapPin size={13} className="text-slate-300" />
                          <span>Delivery address not yet set in winner profile</span>
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Action Box */}
                  <div className="flex flex-col gap-2.5 justify-center md:items-end shrink-0 pt-3 md:pt-0 border-t md:border-t-0 border-slate-100">
                    <label className="text-[11px] font-bold text-slate-400 uppercase tracking-wider">
                      Update Delivery Status
                    </label>
                    <select
                      value={win.deliveryStatus}
                      onChange={(e) => handleStatusChange(win.id, e.target.value)}
                      disabled={
                        updateDelivery.isPending || win.deliveryStatus === 'CONVERTED_TO_WALLET'
                      }
                      className="text-xs px-3.5 py-2.5 border border-slate-200 rounded-xl focus:outline-none focus:border-red-500 bg-white font-bold text-slate-700 disabled:opacity-50 shadow-xs"
                    >
                      {DELIVERY_STATUSES.map((s) => (
                        <option key={s.value} value={s.value}>
                          {s.label}
                        </option>
                      ))}
                    </select>

                    {win.deliveryStatus !== 'CONVERTED_TO_WALLET' && (
                      <button
                        onClick={() => handleOpenConversionModal(win)}
                        className="inline-flex items-center justify-center gap-1.5 px-3.5 py-2 bg-purple-50 hover:bg-purple-100 text-purple-700 border border-purple-200/80 rounded-xl text-xs font-bold transition shadow-xs"
                      >
                        <Wallet size={14} />
                        Convert Prize to Store Credits
                      </button>
                    )}
                  </div>
                </div>

                {/* Delivery Note */}
                {win.deliveryNote && (
                  <div className="pt-3 border-t border-slate-100 text-xs text-slate-500">
                    <strong className="text-slate-700">Delivery Note:</strong> {win.deliveryNote}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}

      {/* Conversion Modal */}
      {selectedWinForConversion && (
        <div className="fixed inset-0 z-[1001] bg-black/60 backdrop-blur-sm flex items-end sm:items-center justify-center p-0 sm:p-4">
          <div className="bg-white rounded-t-3xl sm:rounded-2xl max-w-md w-full p-6 pb-20 sm:pb-6 shadow-2xl space-y-4 animate-in slide-in-from-bottom sm:zoom-in-95 duration-200">
            {/* Mobile Sheet Bar */}
            <div className="w-12 h-1.5 bg-slate-200 rounded-full mx-auto sm:hidden mb-1" />

            <div className="flex items-center gap-3 text-purple-700">
              <div className="p-3 bg-purple-100 rounded-xl shrink-0">
                <Wallet size={24} />
              </div>
              <div>
                <h3 className="font-bold text-lg text-slate-900">Convert Prize to Store Credits</h3>
                <p className="text-xs text-slate-500">
                  Credit winner&apos;s non-withdrawable wallet balance
                </p>
              </div>
            </div>

            <div className="p-3.5 bg-purple-50 rounded-xl border border-purple-100 text-xs space-y-1.5 text-purple-900 font-medium">
              <p>
                Winner: <strong>{selectedWinForConversion.winner?.name}</strong>
              </p>
              <p>
                Prize Item: <strong>{selectedWinForConversion.item?.name}</strong>
              </p>
              <p>
                Item Market Value:{' '}
                <strong>₦{selectedWinForConversion.item?.value?.toLocaleString()}</strong>
              </p>
              <div className="text-[11px] text-purple-700 bg-purple-100/70 p-2.5 rounded-lg mt-2 font-normal leading-relaxed">
                💡 Credited funds are non-withdrawable cash and can only be used by the winner to
                purchase raffle tickets on the platform.
              </div>
            </div>

            <div className="space-y-3">
              <div>
                <label className="block text-xs font-bold text-slate-700 uppercase mb-1">
                  Credit Amount (₦)
                </label>
                <input
                  type="number"
                  value={conversionAmount}
                  onChange={(e) => setConversionAmount(Number(e.target.value))}
                  className="w-full px-3.5 py-2.5 border border-slate-200 rounded-xl text-sm focus:outline-none focus:border-purple-600 font-bold"
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 uppercase mb-1">
                  Admin Note / Reason
                </label>
                <textarea
                  value={conversionNote}
                  onChange={(e) => setConversionNote(e.target.value)}
                  rows={3}
                  className="w-full px-3.5 py-2.5 border border-slate-200 rounded-xl text-xs focus:outline-none focus:border-purple-600 resize-none"
                />
              </div>
            </div>

            <div className="flex items-center justify-end gap-2 pt-2">
              <button
                onClick={() => setSelectedWinForConversion(null)}
                className="px-4 py-2.5 text-xs font-bold text-slate-600 hover:bg-slate-100 rounded-xl transition"
              >
                Cancel
              </button>
              <button
                onClick={handleConfirmConversion}
                disabled={isConverting}
                className="px-5 py-2.5 text-xs font-bold text-white bg-purple-700 hover:bg-purple-800 rounded-xl shadow-md transition disabled:opacity-50"
              >
                {isConverting ? 'Converting...' : 'Confirm & Credit Wallet'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Empty State */}
      {!isLoading && filteredWins.length === 0 && (
        <div className="bg-white rounded-2xl border border-slate-200/80 p-12 text-center">
          <Trophy size={48} className="mx-auto text-slate-300 mb-3" />
          <h3 className="text-lg font-bold text-slate-700">No win records found</h3>
          <p className="text-sm text-slate-500 mt-1">
            Completed raffles with winning claims will appear here.
          </p>
        </div>
      )}

      {/* Pagination */}
      {pagination && pagination.totalPages > 1 && (
        <div className="flex justify-center items-center gap-2 pt-4">
          <button
            disabled={page <= 1}
            onClick={() => setPage((p) => p - 1)}
            className="px-4 py-2 text-xs font-bold bg-white border border-slate-200 rounded-xl disabled:opacity-50 hover:bg-slate-50 transition"
          >
            Previous
          </button>
          <span className="px-4 py-2 text-xs text-slate-600 font-semibold">
            Page {page} of {pagination.totalPages}
          </span>
          <button
            disabled={page >= pagination.totalPages}
            onClick={() => setPage((p) => p + 1)}
            className="px-4 py-2 text-xs font-bold bg-white border border-slate-200 rounded-xl disabled:opacity-50 hover:bg-slate-50 transition"
          >
            Next
          </button>
        </div>
      )}
    </div>
  );
}

'use client';

import { api } from '@/lib/api';
import { useAdminWins, useUpdateDeliveryStatus } from '@/lib/hooks/useAdmin';
import {
  ArrowUpRight,
  Check,
  CheckCircle,
  Clock,
  Copy,
  Filter,
  Mail,
  MapPin,
  Package,
  Phone,
  Search,
  Trophy,
  Truck,
  Wallet,
} from 'lucide-react';
import { useState } from 'react';
import toast from 'react-hot-toast';

const DELIVERY_STATUSES = [
  {
    value: 'PENDING',
    label: 'Pending',
    icon: Clock,
    color: 'bg-amber-50 text-amber-700 border-amber-200',
  },
  {
    value: 'PROCESSING',
    label: 'Processing',
    icon: Package,
    color: 'bg-blue-50 text-blue-700 border-blue-200',
  },
  {
    value: 'SHIPPED',
    label: 'Shipped',
    icon: Truck,
    color: 'bg-indigo-50 text-indigo-700 border-indigo-200',
  },
  {
    value: 'DELIVERED',
    label: 'Delivered',
    icon: CheckCircle,
    color: 'bg-emerald-50 text-emerald-700 border-emerald-200',
  },
  {
    value: 'CONVERTED_TO_WALLET',
    label: 'Converted to Credits',
    icon: Wallet,
    color: 'bg-purple-50 text-purple-700 border-purple-200',
  },
];

export default function AdminWinsPage() {
  const [filterStatus, setFilterStatus] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [page, setPage] = useState(1);
  const { data, isLoading, refetch } = useAdminWins({ page, deliveryStatus: filterStatus });
  const updateDelivery = useUpdateDeliveryStatus();

  const [selectedWinForConversion, setSelectedWinForConversion] = useState<any>(null);
  const [conversionAmount, setConversionAmount] = useState<number>(0);
  const [conversionNote, setConversionNote] = useState('');
  const [isConverting, setIsConverting] = useState(false);
  const [copiedField, setCopiedField] = useState<string | null>(null);

  const wins = data?.wins ?? [];
  const pagination = data?.pagination ?? null;

  const copyToClipboard = (text: string, label: string) => {
    if (!text) return;
    navigator.clipboard.writeText(text);
    setCopiedField(label);
    toast.success(`Copied ${label}`);
    setTimeout(() => setCopiedField(null), 2000);
  };

  const handleStatusChange = async (raffleId: string, newStatus: string) => {
    try {
      await updateDelivery.mutateAsync({ raffleId, deliveryStatus: newStatus });
      toast.success(`Delivery status updated to ${newStatus}`);
    } catch (err: any) {
      toast.error(err.message || 'Failed to update delivery status');
    }
  };

  const handleOpenConversionModal = (win: any) => {
    setSelectedWinForConversion(win);
    setConversionAmount(win.item?.value || 0);
    setConversionNote(
      `Unclaimed/Unavailable physical prize converted to non-withdrawable store credits for ${win.item?.name}.`,
    );
  };

  const handleConfirmConversion = async () => {
    if (!selectedWinForConversion) return;
    setIsConverting(true);
    try {
      const res = (await api.post(
        `/api/admin/wins/${selectedWinForConversion.id}/convert-to-wallet`,
        {
          amount: conversionAmount,
          note: conversionNote,
        },
      )) as any;

      if (res.success) {
        toast.success(res.message || 'Prize successfully converted to store credits!');
        setSelectedWinForConversion(null);
        refetch();
      } else {
        toast.error(res.message || 'Failed to convert prize');
      }
    } catch (err: any) {
      toast.error(err.message || 'Error converting prize to store credit');
    } finally {
      setIsConverting(false);
    }
  };

  // Filter by search query (winner name, email, item name)
  const filteredWins = wins.filter((w: any) => {
    if (!searchQuery.trim()) return true;
    const q = searchQuery.toLowerCase();
    return (
      w.item?.name?.toLowerCase().includes(q) ||
      w.winner?.name?.toLowerCase().includes(q) ||
      w.winner?.email?.toLowerCase().includes(q) ||
      w.winner?.userNumber?.toLowerCase().includes(q)
    );
  });

  // KPI Metrics calculation
  const totalWinsCount = wins.length;
  const pendingCount = wins.filter(
    (w: any) => w.deliveryStatus === 'PENDING' || w.deliveryStatus === 'PROCESSING',
  ).length;
  const deliveredCount = wins.filter((w: any) => w.deliveryStatus === 'DELIVERED').length;
  const convertedCount = wins.filter((w: any) => w.deliveryStatus === 'CONVERTED_TO_WALLET').length;

  return (
    <div className="space-y-6 pb-20 md:pb-0">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl sm:text-3xl font-bold text-slate-900 flex items-center gap-2.5">
            <div className="p-2 bg-amber-50 text-amber-600 rounded-xl">
              <Trophy size={24} />
            </div>
            Wins & Claims Management
          </h1>
          <p className="text-sm text-slate-500 mt-1">
            Track raffle prize claims, manage winner delivery fulfillment, and handle store credit
            conversions.
          </p>
        </div>
      </div>

      {/* KPI Summary Cards */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4">
        <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3">
          <div className="p-3 bg-amber-50 text-amber-600 rounded-xl shrink-0">
            <Trophy size={22} />
          </div>
          <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
              Total Winners
            </p>
            <p className="text-xl sm:text-2xl font-bold text-slate-900 mt-0.5">{totalWinsCount}</p>
          </div>
        </div>

        <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3">
          <div className="p-3 bg-blue-50 text-blue-600 rounded-xl shrink-0">
            <Clock size={22} />
          </div>
          <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
              Pending Delivery
            </p>
            <p className="text-xl sm:text-2xl font-bold text-blue-600 mt-0.5">{pendingCount}</p>
          </div>
        </div>

        <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3">
          <div className="p-3 bg-emerald-50 text-emerald-600 rounded-xl shrink-0">
            <CheckCircle size={22} />
          </div>
          <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
              Delivered
            </p>
            <p className="text-xl sm:text-2xl font-bold text-emerald-600 mt-0.5">
              {deliveredCount}
            </p>
          </div>
        </div>

        <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3">
          <div className="p-3 bg-purple-50 text-purple-600 rounded-xl shrink-0">
            <Wallet size={22} />
          </div>
          <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
              Converted Credits
            </p>
            <p className="text-xl sm:text-2xl font-bold text-purple-600 mt-0.5">{convertedCount}</p>
          </div>
        </div>
      </div>

      {/* Filter Toolbar */}
      <div className="bg-white p-4 rounded-2xl border border-slate-200/80 shadow-xs flex flex-col sm:flex-row gap-3">
        <div className="relative flex-1">
          <Search size={18} className="absolute left-3.5 top-3 text-slate-400" />
          <input
            type="text"
            placeholder="Search winner name, email, or item..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:outline-none focus:border-red-500 transition"
          />
        </div>

        <div className="flex items-center gap-2">
          <Filter size={18} className="text-slate-400 shrink-0" />
          <select
            value={filterStatus}
            onChange={(e) => {
              setFilterStatus(e.target.value);
              setPage(1);
            }}
            className="w-full sm:w-auto px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm font-semibold text-slate-700 focus:outline-none focus:border-red-500"
          >
            <option value="all">All Delivery Statuses</option>
            {DELIVERY_STATUSES.map((s) => (
              <option key={s.value} value={s.value}>
                {s.label}
              </option>
            ))}
          </select>
        </div>
      </div>

      {/* Loading */}
      {isLoading && (
        <div className="space-y-4">
          {[1, 2, 3].map((i) => (
            <div
              key={i}
              className="bg-white rounded-2xl p-6 border border-slate-100 shadow-xs animate-pulse space-y-4"
            >
              <div className="h-5 w-1/3 bg-slate-200 rounded" />
              <div className="h-4 w-2/3 bg-slate-200 rounded" />
              <div className="h-8 w-1/4 bg-slate-200 rounded" />
            </div>
          ))}
        </div>
      )}

      {/* Wins List */}
      {!isLoading && (
        <div className="space-y-4">
          {filteredWins.map((win: any) => {
            const currentStatus =
              DELIVERY_STATUSES.find((s) => s.value === win.deliveryStatus) || DELIVERY_STATUSES[0];
            const StatusIcon = currentStatus.icon;
            const imageUrl = win.item?.imageUrl?.startsWith('/uploads')
              ? `${process.env.NEXT_PUBLIC_API_URL || 'http://localhost:5000'}${win.item.imageUrl}`
              : win.item?.imageUrl;

            const winnerAddress = [win.winner?.address, win.winner?.city, win.winner?.state]
              .filter(Boolean)
              .join(', ');

            return (
              <div
                key={win.id}
                className="bg-white rounded-2xl border border-slate-200/80 p-5 shadow-xs hover:shadow-md transition space-y-4"
              >
                <div className="flex flex-col md:flex-row gap-5">
                  {/* Item Image */}
                  <div className="w-20 h-20 sm:w-24 sm:h-24 bg-slate-100 rounded-xl overflow-hidden shrink-0 border border-slate-100 flex items-center justify-center">
                    {imageUrl ? (
                      <img
                        src={imageUrl}
                        alt={win.item?.name}
                        className="w-full h-full object-cover"
                      />
                    ) : (
                      <span className="text-3xl">🏆</span>
                    )}
                  </div>

                  {/* Info & Winner Address */}
                  <div className="flex-1 min-w-0 space-y-3">
                    <div className="flex flex-wrap items-start justify-between gap-2">
                      <div>
                        <h3 className="font-bold text-slate-900 text-base sm:text-lg flex items-center gap-2">
                          {win.item?.name}
                          <span className="text-xs bg-red-50 text-red-600 px-2 py-0.5 rounded-full font-bold border border-red-100">
                            ₦{win.item?.value?.toLocaleString()}
                          </span>
                        </h3>
                      </div>
                      <span
                        className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold border ${currentStatus.color}`}
                      >
                        <StatusIcon size={14} />
                        {currentStatus.label}
                      </span>
                    </div>

                    {/* Winner Details Box */}
                    <div className="p-3.5 bg-slate-50 rounded-xl border border-slate-200/60 text-xs space-y-2">
                      <div className="flex items-center justify-between">
                        <p className="font-bold text-slate-800 text-sm">
                          Winner: <span className="text-red-600">{win.winner?.name}</span>{' '}
                          <span className="font-mono text-slate-400 text-[11px]">
                            ({win.winner?.userNumber})
                          </span>
                        </p>
                      </div>

                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 text-slate-600 pt-1">
                        {win.winner?.email && (
                          <div className="flex items-center justify-between bg-white px-2.5 py-1.5 rounded-lg border border-slate-200/60">
                            <span className="flex items-center gap-1.5 truncate">
                              <Mail size={13} className="text-slate-400 shrink-0" />
                              <span className="truncate">{win.winner.email}</span>
                            </span>
                            <button
                              onClick={() => copyToClipboard(win.winner.email, 'Email')}
                              className="text-slate-400 hover:text-slate-700 p-1"
                              title="Copy email"
                            >
                              {copiedField === 'Email' ? (
                                <Check size={13} className="text-emerald-600" />
                              ) : (
                                <Copy size={13} />
                              )}
                            </button>
                          </div>
                        )}

                        {win.winner?.phone && (
                          <div className="flex items-center justify-between bg-white px-2.5 py-1.5 rounded-lg border border-slate-200/60">
                            <span className="flex items-center gap-1.5 truncate">
                              <Phone size={13} className="text-slate-400 shrink-0" />
                              <span>{win.winner.phone}</span>
                            </span>
                            <button
                              onClick={() => copyToClipboard(win.winner.phone, 'Phone')}
                              className="text-slate-400 hover:text-slate-700 p-1"
                              title="Copy phone"
                            >
                              {copiedField === 'Phone' ? (
                                <Check size={13} className="text-emerald-600" />
                              ) : (
                                <Copy size={13} />
                              )}
                            </button>
                          </div>
                        )}
                      </div>

                      {winnerAddress ? (
                        <div className="pt-1 flex items-start gap-1.5 font-medium text-slate-700">
                          <MapPin size={14} className="text-red-500 shrink-0 mt-0.5" />
                          <span>
                            <strong>Shipping Address:</strong> {winnerAddress}
                          </span>
                        </div>
                      ) : (
                        <div className="pt-1 flex items-center gap-1.5 italic text-slate-400">
                          <MapPin size={13} className="text-slate-300" />
                          <span>Delivery address not yet set in winner profile</span>
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Action Box */}
                  <div className="flex flex-col gap-2.5 justify-center md:items-end shrink-0 pt-3 md:pt-0 border-t md:border-t-0 border-slate-100">
                    <label className="text-[11px] font-bold text-slate-400 uppercase tracking-wider">
                      Update Delivery Status
                    </label>
                    <select
                      value={win.deliveryStatus}
                      onChange={(e) => handleStatusChange(win.id, e.target.value)}
                      disabled={
                        updateDelivery.isPending || win.deliveryStatus === 'CONVERTED_TO_WALLET'
                      }
                      className="text-xs px-3.5 py-2.5 border border-slate-200 rounded-xl focus:outline-none focus:border-red-500 bg-white font-bold text-slate-700 disabled:opacity-50 shadow-xs"
                    >
                      {DELIVERY_STATUSES.map((s) => (
                        <option key={s.value} value={s.value}>
                          {s.label}
                        </option>
                      ))}
                    </select>

                    {win.deliveryStatus !== 'CONVERTED_TO_WALLET' && (
                      <button
                        onClick={() => handleOpenConversionModal(win)}
                        className="inline-flex items-center justify-center gap-1.5 px-3.5 py-2 bg-purple-50 hover:bg-purple-100 text-purple-700 border border-purple-200/80 rounded-xl text-xs font-bold transition shadow-xs"
                      >
                        <Wallet size={14} />
                        Convert Prize to Store Credits
                      </button>
                    )}
                  </div>
                </div>

                {/* Delivery Note */}
                {win.deliveryNote && (
                  <div className="pt-3 border-t border-slate-100 text-xs text-slate-500">
                    <strong className="text-slate-700">Delivery Note:</strong> {win.deliveryNote}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}

      {/* Conversion Modal */}
      {selectedWinForConversion && (
        <div className="fixed inset-0 z-[1001] bg-black/60 backdrop-blur-sm flex items-end sm:items-center justify-center p-0 sm:p-4">
          <div className="bg-white rounded-t-3xl sm:rounded-2xl max-w-md w-full p-6 pb-20 sm:pb-6 shadow-2xl space-y-4 animate-in slide-in-from-bottom sm:zoom-in-95 duration-200">
            {/* Mobile Sheet Bar */}
            <div className="w-12 h-1.5 bg-slate-200 rounded-full mx-auto sm:hidden mb-1" />

            <div className="flex items-center gap-3 text-purple-700">
              <div className="p-3 bg-purple-100 rounded-xl shrink-0">
                <Wallet size={24} />
              </div>
              <div>
                <h3 className="font-bold text-lg text-slate-900">Convert Prize to Store Credits</h3>
                <p className="text-xs text-slate-500">
                  Credit winner&apos;s non-withdrawable wallet balance
                </p>
              </div>
            </div>

            <div className="p-3.5 bg-purple-50 rounded-xl border border-purple-100 text-xs space-y-1.5 text-purple-900 font-medium">
              <p>
                Winner: <strong>{selectedWinForConversion.winner?.name}</strong>
              </p>
              <p>
                Prize Item: <strong>{selectedWinForConversion.item?.name}</strong>
              </p>
              <p>
                Item Market Value:{' '}
                <strong>₦{selectedWinForConversion.item?.value?.toLocaleString()}</strong>
              </p>
              <div className="text-[11px] text-purple-700 bg-purple-100/70 p-2.5 rounded-lg mt-2 font-normal leading-relaxed">
                💡 Credited funds are non-withdrawable cash and can only be used by the winner to
                purchase raffle tickets on the platform.
              </div>
            </div>

            <div className="space-y-3">
              <div>
                <label className="block text-xs font-bold text-slate-700 uppercase mb-1">
                  Credit Amount (₦)
                </label>
                <input
                  type="number"
                  value={conversionAmount}
                  onChange={(e) => setConversionAmount(Number(e.target.value))}
                  className="w-full px-3.5 py-2.5 border border-slate-200 rounded-xl text-sm focus:outline-none focus:border-purple-600 font-bold"
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 uppercase mb-1">
                  Admin Note / Reason
                </label>
                <textarea
                  value={conversionNote}
                  onChange={(e) => setConversionNote(e.target.value)}
                  rows={3}
                  className="w-full px-3.5 py-2.5 border border-slate-200 rounded-xl text-xs focus:outline-none focus:border-purple-600 resize-none"
                />
              </div>
            </div>

            <div className="flex items-center justify-end gap-2 pt-2">
              <button
                onClick={() => setSelectedWinForConversion(null)}
                className="px-4 py-2.5 text-xs font-bold text-slate-600 hover:bg-slate-100 rounded-xl transition"
              >
                Cancel
              </button>
              <button
                onClick={handleConfirmConversion}
                disabled={isConverting}
                className="px-5 py-2.5 text-xs font-bold text-white bg-purple-700 hover:bg-purple-800 rounded-xl shadow-md transition disabled:opacity-50"
              >
                {isConverting ? 'Converting...' : 'Confirm & Credit Wallet'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Empty State */}
      {!isLoading && filteredWins.length === 0 && (
        <div className="bg-white rounded-2xl border border-slate-200/80 p-12 text-center">
          <Trophy size={48} className="mx-auto text-slate-300 mb-3" />
          <h3 className="text-lg font-bold text-slate-700">No win records found</h3>
          <p className="text-sm text-slate-500 mt-1">
            Completed raffles with winning claims will appear here.
          </p>
        </div>
      )}

      {/* Pagination */}
      {pagination && pagination.totalPages > 1 && (
        <div className="flex justify-center items-center gap-2 pt-4">
          <button
            disabled={page <= 1}
            onClick={() => setPage((p) => p - 1)}
            className="px-4 py-2 text-xs font-bold bg-white border border-slate-200 rounded-xl disabled:opacity-50 hover:bg-slate-50 transition"
          >
            Previous
          </button>
          <span className="px-4 py-2 text-xs text-slate-600 font-semibold">
            Page {page} of {pagination.totalPages}
          </span>
          <button
            disabled={page >= pagination.totalPages}
            onClick={() => setPage((p) => p + 1)}
            className="px-4 py-2 text-xs font-bold bg-white border border-slate-200 rounded-xl disabled:opacity-50 hover:bg-slate-50 transition"
          >
            Next
          </button>
        </div>
      )}
    </div>
  );
}

'use client';

import { api } from '@/lib/api';
import { useAdminWins, useUpdateDeliveryStatus } from '@/lib/hooks/useAdmin';
import {
  ArrowUpRight,
  Check,
  CheckCircle,
  Clock,
  Copy,
  Filter,
  Mail,
  MapPin,
  Package,
  Phone,
  Search,
  Trophy,
  Truck,
  Wallet,
} from 'lucide-react';
import { useState } from 'react';
import toast from 'react-hot-toast';

const DELIVERY_STATUSES = [
  {
    value: 'PENDING',
    label: 'Pending',
    icon: Clock,
    color: 'bg-amber-50 text-amber-700 border-amber-200',
  },
  {
    value: 'PROCESSING',
    label: 'Processing',
    icon: Package,
    color: 'bg-blue-50 text-blue-700 border-blue-200',
  },
  {
    value: 'SHIPPED',
    label: 'Shipped',
    icon: Truck,
    color: 'bg-indigo-50 text-indigo-700 border-indigo-200',
  },
  {
    value: 'DELIVERED',
    label: 'Delivered',
    icon: CheckCircle,
    color: 'bg-emerald-50 text-emerald-700 border-emerald-200',
  },
  {
    value: 'CONVERTED_TO_WALLET',
    label: 'Converted to Credits',
    icon: Wallet,
    color: 'bg-purple-50 text-purple-700 border-purple-200',
  },
];

export default function AdminWinsPage() {
  const [filterStatus, setFilterStatus] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [page, setPage] = useState(1);
  const { data, isLoading, refetch } = useAdminWins({ page, deliveryStatus: filterStatus });
  const updateDelivery = useUpdateDeliveryStatus();

  const [selectedWinForConversion, setSelectedWinForConversion] = useState<any>(null);
  const [conversionAmount, setConversionAmount] = useState<number>(0);
  const [conversionNote, setConversionNote] = useState('');
  const [isConverting, setIsConverting] = useState(false);
  const [copiedField, setCopiedField] = useState<string | null>(null);

  const wins = data?.wins ?? [];
  const pagination = data?.pagination ?? null;

  const copyToClipboard = (text: string, label: string) => {
    if (!text) return;
    navigator.clipboard.writeText(text);
    setCopiedField(label);
    toast.success(`Copied ${label}`);
    setTimeout(() => setCopiedField(null), 2000);
  };

  const handleStatusChange = async (raffleId: string, newStatus: string) => {
    try {
      await updateDelivery.mutateAsync({ raffleId, deliveryStatus: newStatus });
      toast.success(`Delivery status updated to ${newStatus}`);
    } catch (err: any) {
      toast.error(err.message || 'Failed to update delivery status');
    }
  };

  const handleOpenConversionModal = (win: any) => {
    setSelectedWinForConversion(win);
    setConversionAmount(win.item?.value || 0);
    setConversionNote(
      `Unclaimed/Unavailable physical prize converted to non-withdrawable store credits for ${win.item?.name}.`,
    );
  };

  const handleConfirmConversion = async () => {
    if (!selectedWinForConversion) return;
    setIsConverting(true);
    try {
      const res = (await api.post(
        `/api/admin/wins/${selectedWinForConversion.id}/convert-to-wallet`,
        {
          amount: conversionAmount,
          note: conversionNote,
        },
      )) as any;

      if (res.success) {
        toast.success(res.message || 'Prize successfully converted to store credits!');
        setSelectedWinForConversion(null);
        refetch();
      } else {
        toast.error(res.message || 'Failed to convert prize');
      }
    } catch (err: any) {
      toast.error(err.message || 'Error converting prize to store credit');
    } finally {
      setIsConverting(false);
    }
  };

  // Filter by search query (winner name, email, item name)
  const filteredWins = wins.filter((w: any) => {
    if (!searchQuery.trim()) return true;
    const q = searchQuery.toLowerCase();
    return (
      w.item?.name?.toLowerCase().includes(q) ||
      w.winner?.name?.toLowerCase().includes(q) ||
      w.winner?.email?.toLowerCase().includes(q) ||
      w.winner?.userNumber?.toLowerCase().includes(q)
    );
  });

  // KPI Metrics calculation
  const totalWinsCount = wins.length;
  const pendingCount = wins.filter(
    (w: any) => w.deliveryStatus === 'PENDING' || w.deliveryStatus === 'PROCESSING',
  ).length;
  const deliveredCount = wins.filter((w: any) => w.deliveryStatus === 'DELIVERED').length;
  const convertedCount = wins.filter((w: any) => w.deliveryStatus === 'CONVERTED_TO_WALLET').length;

  return (
    <div className="space-y-6 pb-20 md:pb-0">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl sm:text-3xl font-bold text-slate-900 flex items-center gap-2.5">
            <div className="p-2 bg-amber-50 text-amber-600 rounded-xl">
              <Trophy size={24} />
            </div>
            Wins & Claims Management
          </h1>
          <p className="text-sm text-slate-500 mt-1">
            Track raffle prize claims, manage winner delivery fulfillment, and handle store credit
            conversions.
          </p>
        </div>
      </div>

      {/* KPI Summary Cards */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4">
        <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3">
          <div className="p-3 bg-amber-50 text-amber-600 rounded-xl shrink-0">
            <Trophy size={22} />
          </div>
          <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
              Total Winners
            </p>
            <p className="text-xl sm:text-2xl font-bold text-slate-900 mt-0.5">{totalWinsCount}</p>
          </div>
        </div>

        <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3">
          <div className="p-3 bg-blue-50 text-blue-600 rounded-xl shrink-0">
            <Clock size={22} />
          </div>
          <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
              Pending Delivery
            </p>
            <p className="text-xl sm:text-2xl font-bold text-blue-600 mt-0.5">{pendingCount}</p>
          </div>
        </div>

        <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3">
          <div className="p-3 bg-emerald-50 text-emerald-600 rounded-xl shrink-0">
            <CheckCircle size={22} />
          </div>
          <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
              Delivered
            </p>
            <p className="text-xl sm:text-2xl font-bold text-emerald-600 mt-0.5">
              {deliveredCount}
            </p>
          </div>
        </div>

        <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3">
          <div className="p-3 bg-purple-50 text-purple-600 rounded-xl shrink-0">
            <Wallet size={22} />
          </div>
          <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
              Converted Credits
            </p>
            <p className="text-xl sm:text-2xl font-bold text-purple-600 mt-0.5">{convertedCount}</p>
          </div>
        </div>
      </div>

      {/* Filter Toolbar */}
      <div className="bg-white p-4 rounded-2xl border border-slate-200/80 shadow-xs flex flex-col sm:flex-row gap-3">
        <div className="relative flex-1">
          <Search size={18} className="absolute left-3.5 top-3 text-slate-400" />
          <input
            type="text"
            placeholder="Search winner name, email, or item..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:outline-none focus:border-red-500 transition"
          />
        </div>

        <div className="flex items-center gap-2">
          <Filter size={18} className="text-slate-400 shrink-0" />
          <select
            value={filterStatus}
            onChange={(e) => {
              setFilterStatus(e.target.value);
              setPage(1);
            }}
            className="w-full sm:w-auto px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm font-semibold text-slate-700 focus:outline-none focus:border-red-500"
          >
            <option value="all">All Delivery Statuses</option>
            {DELIVERY_STATUSES.map((s) => (
              <option key={s.value} value={s.value}>
                {s.label}
              </option>
            ))}
          </select>
        </div>
      </div>

      {/* Loading */}
      {isLoading && (
        <div className="space-y-4">
          {[1, 2, 3].map((i) => (
            <div
              key={i}
              className="bg-white rounded-2xl p-6 border border-slate-100 shadow-xs animate-pulse space-y-4"
            >
              <div className="h-5 w-1/3 bg-slate-200 rounded" />
              <div className="h-4 w-2/3 bg-slate-200 rounded" />
              <div className="h-8 w-1/4 bg-slate-200 rounded" />
            </div>
          ))}
        </div>
      )}

      {/* Wins List */}
      {!isLoading && (
        <div className="space-y-4">
          {filteredWins.map((win: any) => {
            const currentStatus =
              DELIVERY_STATUSES.find((s) => s.value === win.deliveryStatus) || DELIVERY_STATUSES[0];
            const StatusIcon = currentStatus.icon;
            const imageUrl = win.item?.imageUrl?.startsWith('/uploads')
              ? `${process.env.NEXT_PUBLIC_API_URL || 'http://localhost:5000'}${win.item.imageUrl}`
              : win.item?.imageUrl;

            const winnerAddress = [win.winner?.address, win.winner?.city, win.winner?.state]
              .filter(Boolean)
              .join(', ');

            return (
              <div
                key={win.id}
                className="bg-white rounded-2xl border border-slate-200/80 p-5 shadow-xs hover:shadow-md transition space-y-4"
              >
                <div className="flex flex-col md:flex-row gap-5">
                  {/* Item Image */}
                  <div className="w-20 h-20 sm:w-24 sm:h-24 bg-slate-100 rounded-xl overflow-hidden shrink-0 border border-slate-100 flex items-center justify-center">
                    {imageUrl ? (
                      <img
                        src={imageUrl}
                        alt={win.item?.name}
                        className="w-full h-full object-cover"
                      />
                    ) : (
                      <span className="text-3xl">🏆</span>
                    )}
                  </div>

                  {/* Info & Winner Address */}
                  <div className="flex-1 min-w-0 space-y-3">
                    <div className="flex flex-wrap items-start justify-between gap-2">
                      <div>
                        <h3 className="font-bold text-slate-900 text-base sm:text-lg flex items-center gap-2">
                          {win.item?.name}
                          <span className="text-xs bg-red-50 text-red-600 px-2 py-0.5 rounded-full font-bold border border-red-100">
                            ₦{win.item?.value?.toLocaleString()}
                          </span>
                        </h3>
                      </div>
                      <span
                        className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold border ${currentStatus.color}`}
                      >
                        <StatusIcon size={14} />
                        {currentStatus.label}
                      </span>
                    </div>

                    {/* Winner Details Box */}
                    <div className="p-3.5 bg-slate-50 rounded-xl border border-slate-200/60 text-xs space-y-2">
                      <div className="flex items-center justify-between">
                        <p className="font-bold text-slate-800 text-sm">
                          Winner: <span className="text-red-600">{win.winner?.name}</span>{' '}
                          <span className="font-mono text-slate-400 text-[11px]">
                            ({win.winner?.userNumber})
                          </span>
                        </p>
                      </div>

                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 text-slate-600 pt-1">
                        {win.winner?.email && (
                          <div className="flex items-center justify-between bg-white px-2.5 py-1.5 rounded-lg border border-slate-200/60">
                            <span className="flex items-center gap-1.5 truncate">
                              <Mail size={13} className="text-slate-400 shrink-0" />
                              <span className="truncate">{win.winner.email}</span>
                            </span>
                            <button
                              onClick={() => copyToClipboard(win.winner.email, 'Email')}
                              className="text-slate-400 hover:text-slate-700 p-1"
                              title="Copy email"
                            >
                              {copiedField === 'Email' ? (
                                <Check size={13} className="text-emerald-600" />
                              ) : (
                                <Copy size={13} />
                              )}
                            </button>
                          </div>
                        )}

                        {win.winner?.phone && (
                          <div className="flex items-center justify-between bg-white px-2.5 py-1.5 rounded-lg border border-slate-200/60">
                            <span className="flex items-center gap-1.5 truncate">
                              <Phone size={13} className="text-slate-400 shrink-0" />
                              <span>{win.winner.phone}</span>
                            </span>
                            <button
                              onClick={() => copyToClipboard(win.winner.phone, 'Phone')}
                              className="text-slate-400 hover:text-slate-700 p-1"
                              title="Copy phone"
                            >
                              {copiedField === 'Phone' ? (
                                <Check size={13} className="text-emerald-600" />
                              ) : (
                                <Copy size={13} />
                              )}
                            </button>
                          </div>
                        )}
                      </div>

                      {winnerAddress ? (
                        <div className="pt-1 flex items-start gap-1.5 font-medium text-slate-700">
                          <MapPin size={14} className="text-red-500 shrink-0 mt-0.5" />
                          <span>
                            <strong>Shipping Address:</strong> {winnerAddress}
                          </span>
                        </div>
                      ) : (
                        <div className="pt-1 flex items-center gap-1.5 italic text-slate-400">
                          <MapPin size={13} className="text-slate-300" />
                          <span>Delivery address not yet set in winner profile</span>
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Action Box */}
                  <div className="flex flex-col gap-2.5 justify-center md:items-end shrink-0 pt-3 md:pt-0 border-t md:border-t-0 border-slate-100">
                    <label className="text-[11px] font-bold text-slate-400 uppercase tracking-wider">
                      Update Delivery Status
                    </label>
                    <select
                      value={win.deliveryStatus}
                      onChange={(e) => handleStatusChange(win.id, e.target.value)}
                      disabled={
                        updateDelivery.isPending || win.deliveryStatus === 'CONVERTED_TO_WALLET'
                      }
                      className="text-xs px-3.5 py-2.5 border border-slate-200 rounded-xl focus:outline-none focus:border-red-500 bg-white font-bold text-slate-700 disabled:opacity-50 shadow-xs"
                    >
                      {DELIVERY_STATUSES.map((s) => (
                        <option key={s.value} value={s.value}>
                          {s.label}
                        </option>
                      ))}
                    </select>

                    {win.deliveryStatus !== 'CONVERTED_TO_WALLET' && (
                      <button
                        onClick={() => handleOpenConversionModal(win)}
                        className="inline-flex items-center justify-center gap-1.5 px-3.5 py-2 bg-purple-50 hover:bg-purple-100 text-purple-700 border border-purple-200/80 rounded-xl text-xs font-bold transition shadow-xs"
                      >
                        <Wallet size={14} />
                        Convert Prize to Store Credits
                      </button>
                    )}
                  </div>
                </div>

                {/* Delivery Note */}
                {win.deliveryNote && (
                  <div className="pt-3 border-t border-slate-100 text-xs text-slate-500">
                    <strong className="text-slate-700">Delivery Note:</strong> {win.deliveryNote}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}

      {/* Conversion Modal */}
      {selectedWinForConversion && (
        <div className="fixed inset-0 z-[1001] bg-black/60 backdrop-blur-sm flex items-end sm:items-center justify-center p-0 sm:p-4">
          <div className="bg-white rounded-t-3xl sm:rounded-2xl max-w-md w-full p-6 pb-20 sm:pb-6 shadow-2xl space-y-4 animate-in slide-in-from-bottom sm:zoom-in-95 duration-200">
            {/* Mobile Sheet Bar */}
            <div className="w-12 h-1.5 bg-slate-200 rounded-full mx-auto sm:hidden mb-1" />

            <div className="flex items-center gap-3 text-purple-700">
              <div className="p-3 bg-purple-100 rounded-xl shrink-0">
                <Wallet size={24} />
              </div>
              <div>
                <h3 className="font-bold text-lg text-slate-900">Convert Prize to Store Credits</h3>
                <p className="text-xs text-slate-500">
                  Credit winner&apos;s non-withdrawable wallet balance
                </p>
              </div>
            </div>

            <div className="p-3.5 bg-purple-50 rounded-xl border border-purple-100 text-xs space-y-1.5 text-purple-900 font-medium">
              <p>
                Winner: <strong>{selectedWinForConversion.winner?.name}</strong>
              </p>
              <p>
                Prize Item: <strong>{selectedWinForConversion.item?.name}</strong>
              </p>
              <p>
                Item Market Value:{' '}
                <strong>₦{selectedWinForConversion.item?.value?.toLocaleString()}</strong>
              </p>
              <div className="text-[11px] text-purple-700 bg-purple-100/70 p-2.5 rounded-lg mt-2 font-normal leading-relaxed">
                💡 Credited funds are non-withdrawable cash and can only be used by the winner to
                purchase raffle tickets on the platform.
              </div>
            </div>

            <div className="space-y-3">
              <div>
                <label className="block text-xs font-bold text-slate-700 uppercase mb-1">
                  Credit Amount (₦)
                </label>
                <input
                  type="number"
                  value={conversionAmount}
                  onChange={(e) => setConversionAmount(Number(e.target.value))}
                  className="w-full px-3.5 py-2.5 border border-slate-200 rounded-xl text-sm focus:outline-none focus:border-purple-600 font-bold"
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 uppercase mb-1">
                  Admin Note / Reason
                </label>
                <textarea
                  value={conversionNote}
                  onChange={(e) => setConversionNote(e.target.value)}
                  rows={3}
                  className="w-full px-3.5 py-2.5 border border-slate-200 rounded-xl text-xs focus:outline-none focus:border-purple-600 resize-none"
                />
              </div>
            </div>

            <div className="flex items-center justify-end gap-2 pt-2">
              <button
                onClick={() => setSelectedWinForConversion(null)}
                className="px-4 py-2.5 text-xs font-bold text-slate-600 hover:bg-slate-100 rounded-xl transition"
              >
                Cancel
              </button>
              <button
                onClick={handleConfirmConversion}
                disabled={isConverting}
                className="px-5 py-2.5 text-xs font-bold text-white bg-purple-700 hover:bg-purple-800 rounded-xl shadow-md transition disabled:opacity-50"
              >
                {isConverting ? 'Converting...' : 'Confirm & Credit Wallet'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Empty State */}
      {!isLoading && filteredWins.length === 0 && (
        <div className="bg-white rounded-2xl border border-slate-200/80 p-12 text-center">
          <Trophy size={48} className="mx-auto text-slate-300 mb-3" />
          <h3 className="text-lg font-bold text-slate-700">No win records found</h3>
          <p className="text-sm text-slate-500 mt-1">
            Completed raffles with winning claims will appear here.
          </p>
        </div>
      )}

      {/* Pagination */}
      {pagination && pagination.totalPages > 1 && (
        <div className="flex justify-center items-center gap-2 pt-4">
          <button
            disabled={page <= 1}
            onClick={() => setPage((p) => p - 1)}
            className="px-4 py-2 text-xs font-bold bg-white border border-slate-200 rounded-xl disabled:opacity-50 hover:bg-slate-50 transition"
          >
            Previous
          </button>
          <span className="px-4 py-2 text-xs text-slate-600 font-semibold">
            Page {page} of {pagination.totalPages}
          </span>
          <button
            disabled={page >= pagination.totalPages}
            onClick={() => setPage((p) => p + 1)}
            className="px-4 py-2 text-xs font-bold bg-white border border-slate-200 rounded-xl disabled:opacity-50 hover:bg-slate-50 transition"
          >
            Next
          </button>
        </div>
      )}
    </div>
  );
}

'use client';

import { api } from '@/lib/api';
import { useAdminWins, useUpdateDeliveryStatus } from '@/lib/hooks/useAdmin';
import {
  ArrowUpRight,
  Check,
  CheckCircle,
  Clock,
  Copy,
  Filter,
  Mail,
  MapPin,
  Package,
  Phone,
  Search,
  Trophy,
  Truck,
  Wallet,
} from 'lucide-react';
import { useState } from 'react';
import toast from 'react-hot-toast';

const DELIVERY_STATUSES = [
  {
    value: 'PENDING',
    label: 'Pending',
    icon: Clock,
    color: 'bg-amber-50 text-amber-700 border-amber-200',
  },
  {
    value: 'PROCESSING',
    label: 'Processing',
    icon: Package,
    color: 'bg-blue-50 text-blue-700 border-blue-200',
  },
  {
    value: 'SHIPPED',
    label: 'Shipped',
    icon: Truck,
    color: 'bg-indigo-50 text-indigo-700 border-indigo-200',
  },
  {
    value: 'DELIVERED',
    label: 'Delivered',
    icon: CheckCircle,
    color: 'bg-emerald-50 text-emerald-700 border-emerald-200',
  },
  {
    value: 'CONVERTED_TO_WALLET',
    label: 'Converted to Credits',
    icon: Wallet,
    color: 'bg-purple-50 text-purple-700 border-purple-200',
  },
];

export default function AdminWinsPage() {
  const [filterStatus, setFilterStatus] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [page, setPage] = useState(1);
  const { data, isLoading, refetch } = useAdminWins({ page, deliveryStatus: filterStatus });
  const updateDelivery = useUpdateDeliveryStatus();

  const [selectedWinForConversion, setSelectedWinForConversion] = useState<any>(null);
  const [conversionAmount, setConversionAmount] = useState<number>(0);
  const [conversionNote, setConversionNote] = useState('');
  const [isConverting, setIsConverting] = useState(false);
  const [copiedField, setCopiedField] = useState<string | null>(null);

  const wins = data?.wins ?? [];
  const pagination = data?.pagination ?? null;

  const copyToClipboard = (text: string, label: string) => {
    if (!text) return;
    navigator.clipboard.writeText(text);
    setCopiedField(label);
    toast.success(`Copied ${label}`);
    setTimeout(() => setCopiedField(null), 2000);
  };

  const handleStatusChange = async (raffleId: string, newStatus: string) => {
    try {
      await updateDelivery.mutateAsync({ raffleId, deliveryStatus: newStatus });
      toast.success(`Delivery status updated to ${newStatus}`);
    } catch (err: any) {
      toast.error(err.message || 'Failed to update delivery status');
    }
  };

  const handleOpenConversionModal = (win: any) => {
    setSelectedWinForConversion(win);
    setConversionAmount(win.item?.value || 0);
    setConversionNote(
      `Unclaimed/Unavailable physical prize converted to non-withdrawable store credits for ${win.item?.name}.`,
    );
  };

  const handleConfirmConversion = async () => {
    if (!selectedWinForConversion) return;
    setIsConverting(true);
    try {
      const res = (await api.post(
        `/api/admin/wins/${selectedWinForConversion.id}/convert-to-wallet`,
        {
          amount: conversionAmount,
          note: conversionNote,
        },
      )) as any;

      if (res.success) {
        toast.success(res.message || 'Prize successfully converted to store credits!');
        setSelectedWinForConversion(null);
        refetch();
      } else {
        toast.error(res.message || 'Failed to convert prize');
      }
    } catch (err: any) {
      toast.error(err.message || 'Error converting prize to store credit');
    } finally {
      setIsConverting(false);
    }
  };

  // Filter by search query (winner name, email, item name)
  const filteredWins = wins.filter((w: any) => {
    if (!searchQuery.trim()) return true;
    const q = searchQuery.toLowerCase();
    return (
      w.item?.name?.toLowerCase().includes(q) ||
      w.winner?.name?.toLowerCase().includes(q) ||
      w.winner?.email?.toLowerCase().includes(q) ||
      w.winner?.userNumber?.toLowerCase().includes(q)
    );
  });

  // KPI Metrics calculation
  const totalWinsCount = wins.length;
  const pendingCount = wins.filter(
    (w: any) => w.deliveryStatus === 'PENDING' || w.deliveryStatus === 'PROCESSING',
  ).length;
  const deliveredCount = wins.filter((w: any) => w.deliveryStatus === 'DELIVERED').length;
  const convertedCount = wins.filter((w: any) => w.deliveryStatus === 'CONVERTED_TO_WALLET').length;

  return (
    <div className="space-y-6 pb-20 md:pb-0">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl sm:text-3xl font-bold text-slate-900 flex items-center gap-2.5">
            <div className="p-2 bg-amber-50 text-amber-600 rounded-xl">
              <Trophy size={24} />
            </div>
            Wins & Claims Management
          </h1>
          <p className="text-sm text-slate-500 mt-1">
            Track raffle prize claims, manage winner delivery fulfillment, and handle store credit
            conversions.
          </p>
        </div>
      </div>

      {/* KPI Summary Cards */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4">
        <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3">
          <div className="p-3 bg-amber-50 text-amber-600 rounded-xl shrink-0">
            <Trophy size={22} />
          </div>
          <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
              Total Winners
            </p>
            <p className="text-xl sm:text-2xl font-bold text-slate-900 mt-0.5">{totalWinsCount}</p>
          </div>
        </div>

        <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3">
          <div className="p-3 bg-blue-50 text-blue-600 rounded-xl shrink-0">
            <Clock size={22} />
          </div>
          <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
              Pending Delivery
            </p>
            <p className="text-xl sm:text-2xl font-bold text-blue-600 mt-0.5">{pendingCount}</p>
          </div>
        </div>

        <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3">
          <div className="p-3 bg-emerald-50 text-emerald-600 rounded-xl shrink-0">
            <CheckCircle size={22} />
          </div>
          <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
              Delivered
            </p>
            <p className="text-xl sm:text-2xl font-bold text-emerald-600 mt-0.5">
              {deliveredCount}
            </p>
          </div>
        </div>

        <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3">
          <div className="p-3 bg-purple-50 text-purple-600 rounded-xl shrink-0">
            <Wallet size={22} />
          </div>
          <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
              Converted Credits
            </p>
            <p className="text-xl sm:text-2xl font-bold text-purple-600 mt-0.5">{convertedCount}</p>
          </div>
        </div>
      </div>

      {/* Filter Toolbar */}
      <div className="bg-white p-4 rounded-2xl border border-slate-200/80 shadow-xs flex flex-col sm:flex-row gap-3">
        <div className="relative flex-1">
          <Search size={18} className="absolute left-3.5 top-3 text-slate-400" />
          <input
            type="text"
            placeholder="Search winner name, email, or item..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:outline-none focus:border-red-500 transition"
          />
        </div>

        <div className="flex items-center gap-2">
          <Filter size={18} className="text-slate-400 shrink-0" />
          <select
            value={filterStatus}
            onChange={(e) => {
              setFilterStatus(e.target.value);
              setPage(1);
            }}
            className="w-full sm:w-auto px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm font-semibold text-slate-700 focus:outline-none focus:border-red-500"
          >
            <option value="all">All Delivery Statuses</option>
            {DELIVERY_STATUSES.map((s) => (
              <option key={s.value} value={s.value}>
                {s.label}
              </option>
            ))}
          </select>
        </div>
      </div>

      {/* Loading */}
      {isLoading && (
        <div className="space-y-4">
          {[1, 2, 3].map((i) => (
            <div
              key={i}
              className="bg-white rounded-2xl p-6 border border-slate-100 shadow-xs animate-pulse space-y-4"
            >
              <div className="h-5 w-1/3 bg-slate-200 rounded" />
              <div className="h-4 w-2/3 bg-slate-200 rounded" />
              <div className="h-8 w-1/4 bg-slate-200 rounded" />
            </div>
          ))}
        </div>
      )}

      {/* Wins List */}
      {!isLoading && (
        <div className="space-y-4">
          {filteredWins.map((win: any) => {
            const currentStatus =
              DELIVERY_STATUSES.find((s) => s.value === win.deliveryStatus) || DELIVERY_STATUSES[0];
            const StatusIcon = currentStatus.icon;
            const imageUrl = win.item?.imageUrl?.startsWith('/uploads')
              ? `${process.env.NEXT_PUBLIC_API_URL || 'http://localhost:5000'}${win.item.imageUrl}`
              : win.item?.imageUrl;

            const winnerAddress = [win.winner?.address, win.winner?.city, win.winner?.state]
              .filter(Boolean)
              .join(', ');

            return (
              <div
                key={win.id}
                className="bg-white rounded-2xl border border-slate-200/80 p-5 shadow-xs hover:shadow-md transition space-y-4"
              >
                <div className="flex flex-col md:flex-row gap-5">
                  {/* Item Image */}
                  <div className="w-20 h-20 sm:w-24 sm:h-24 bg-slate-100 rounded-xl overflow-hidden shrink-0 border border-slate-100 flex items-center justify-center">
                    {imageUrl ? (
                      <img
                        src={imageUrl}
                        alt={win.item?.name}
                        className="w-full h-full object-cover"
                      />
                    ) : (
                      <span className="text-3xl">🏆</span>
                    )}
                  </div>

                  {/* Info & Winner Address */}
                  <div className="flex-1 min-w-0 space-y-3">
                    <div className="flex flex-wrap items-start justify-between gap-2">
                      <div>
                        <h3 className="font-bold text-slate-900 text-base sm:text-lg flex items-center gap-2">
                          {win.item?.name}
                          <span className="text-xs bg-red-50 text-red-600 px-2 py-0.5 rounded-full font-bold border border-red-100">
                            ₦{win.item?.value?.toLocaleString()}
                          </span>
                        </h3>
                      </div>
                      <span
                        className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold border ${currentStatus.color}`}
                      >
                        <StatusIcon size={14} />
                        {currentStatus.label}
                      </span>
                    </div>

                    {/* Winner Details Box */}
                    <div className="p-3.5 bg-slate-50 rounded-xl border border-slate-200/60 text-xs space-y-2">
                      <div className="flex items-center justify-between">
                        <p className="font-bold text-slate-800 text-sm">
                          Winner: <span className="text-red-600">{win.winner?.name}</span>{' '}
                          <span className="font-mono text-slate-400 text-[11px]">
                            ({win.winner?.userNumber})
                          </span>
                        </p>
                      </div>

                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 text-slate-600 pt-1">
                        {win.winner?.email && (
                          <div className="flex items-center justify-between bg-white px-2.5 py-1.5 rounded-lg border border-slate-200/60">
                            <span className="flex items-center gap-1.5 truncate">
                              <Mail size={13} className="text-slate-400 shrink-0" />
                              <span className="truncate">{win.winner.email}</span>
                            </span>
                            <button
                              onClick={() => copyToClipboard(win.winner.email, 'Email')}
                              className="text-slate-400 hover:text-slate-700 p-1"
                              title="Copy email"
                            >
                              {copiedField === 'Email' ? (
                                <Check size={13} className="text-emerald-600" />
                              ) : (
                                <Copy size={13} />
                              )}
                            </button>
                          </div>
                        )}

                        {win.winner?.phone && (
                          <div className="flex items-center justify-between bg-white px-2.5 py-1.5 rounded-lg border border-slate-200/60">
                            <span className="flex items-center gap-1.5 truncate">
                              <Phone size={13} className="text-slate-400 shrink-0" />
                              <span>{win.winner.phone}</span>
                            </span>
                            <button
                              onClick={() => copyToClipboard(win.winner.phone, 'Phone')}
                              className="text-slate-400 hover:text-slate-700 p-1"
                              title="Copy phone"
                            >
                              {copiedField === 'Phone' ? (
                                <Check size={13} className="text-emerald-600" />
                              ) : (
                                <Copy size={13} />
                              )}
                            </button>
                          </div>
                        )}
                      </div>

                      {winnerAddress ? (
                        <div className="pt-1 flex items-start gap-1.5 font-medium text-slate-700">
                          <MapPin size={14} className="text-red-500 shrink-0 mt-0.5" />
                          <span>
                            <strong>Shipping Address:</strong> {winnerAddress}
                          </span>
                        </div>
                      ) : (
                        <div className="pt-1 flex items-center gap-1.5 italic text-slate-400">
                          <MapPin size={13} className="text-slate-300" />
                          <span>Delivery address not yet set in winner profile</span>
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Action Box */}
                  <div className="flex flex-col gap-2.5 justify-center md:items-end shrink-0 pt-3 md:pt-0 border-t md:border-t-0 border-slate-100">
                    <label className="text-[11px] font-bold text-slate-400 uppercase tracking-wider">
                      Update Delivery Status
                    </label>
                    <select
                      value={win.deliveryStatus}
                      onChange={(e) => handleStatusChange(win.id, e.target.value)}
                      disabled={
                        updateDelivery.isPending || win.deliveryStatus === 'CONVERTED_TO_WALLET'
                      }
                      className="text-xs px-3.5 py-2.5 border border-slate-200 rounded-xl focus:outline-none focus:border-red-500 bg-white font-bold text-slate-700 disabled:opacity-50 shadow-xs"
                    >
                      {DELIVERY_STATUSES.map((s) => (
                        <option key={s.value} value={s.value}>
                          {s.label}
                        </option>
                      ))}
                    </select>

                    {win.deliveryStatus !== 'CONVERTED_TO_WALLET' && (
                      <button
                        onClick={() => handleOpenConversionModal(win)}
                        className="inline-flex items-center justify-center gap-1.5 px-3.5 py-2 bg-purple-50 hover:bg-purple-100 text-purple-700 border border-purple-200/80 rounded-xl text-xs font-bold transition shadow-xs"
                      >
                        <Wallet size={14} />
                        Convert Prize to Store Credits
                      </button>
                    )}
                  </div>
                </div>

                {/* Delivery Note */}
                {win.deliveryNote && (
                  <div className="pt-3 border-t border-slate-100 text-xs text-slate-500">
                    <strong className="text-slate-700">Delivery Note:</strong> {win.deliveryNote}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}

      {/* Conversion Modal */}
      {selectedWinForConversion && (
        <div className="fixed inset-0 z-[1001] bg-black/60 backdrop-blur-sm flex items-end sm:items-center justify-center p-0 sm:p-4">
          <div className="bg-white rounded-t-3xl sm:rounded-2xl max-w-md w-full p-6 pb-20 sm:pb-6 shadow-2xl space-y-4 animate-in slide-in-from-bottom sm:zoom-in-95 duration-200">
            {/* Mobile Sheet Bar */}
            <div className="w-12 h-1.5 bg-slate-200 rounded-full mx-auto sm:hidden mb-1" />

            <div className="flex items-center gap-3 text-purple-700">
              <div className="p-3 bg-purple-100 rounded-xl shrink-0">
                <Wallet size={24} />
              </div>
              <div>
                <h3 className="font-bold text-lg text-slate-900">Convert Prize to Store Credits</h3>
                <p className="text-xs text-slate-500">
                  Credit winner&apos;s non-withdrawable wallet balance
                </p>
              </div>
            </div>

            <div className="p-3.5 bg-purple-50 rounded-xl border border-purple-100 text-xs space-y-1.5 text-purple-900 font-medium">
              <p>
                Winner: <strong>{selectedWinForConversion.winner?.name}</strong>
              </p>
              <p>
                Prize Item: <strong>{selectedWinForConversion.item?.name}</strong>
              </p>
              <p>
                Item Market Value:{' '}
                <strong>₦{selectedWinForConversion.item?.value?.toLocaleString()}</strong>
              </p>
              <div className="text-[11px] text-purple-700 bg-purple-100/70 p-2.5 rounded-lg mt-2 font-normal leading-relaxed">
                💡 Credited funds are non-withdrawable cash and can only be used by the winner to
                purchase raffle tickets on the platform.
              </div>
            </div>

            <div className="space-y-3">
              <div>
                <label className="block text-xs font-bold text-slate-700 uppercase mb-1">
                  Credit Amount (₦)
                </label>
                <input
                  type="number"
                  value={conversionAmount}
                  onChange={(e) => setConversionAmount(Number(e.target.value))}
                  className="w-full px-3.5 py-2.5 border border-slate-200 rounded-xl text-sm focus:outline-none focus:border-purple-600 font-bold"
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 uppercase mb-1">
                  Admin Note / Reason
                </label>
                <textarea
                  value={conversionNote}
                  onChange={(e) => setConversionNote(e.target.value)}
                  rows={3}
                  className="w-full px-3.5 py-2.5 border border-slate-200 rounded-xl text-xs focus:outline-none focus:border-purple-600 resize-none"
                />
              </div>
            </div>

            <div className="flex items-center justify-end gap-2 pt-2">
              <button
                onClick={() => setSelectedWinForConversion(null)}
                className="px-4 py-2.5 text-xs font-bold text-slate-600 hover:bg-slate-100 rounded-xl transition"
              >
                Cancel
              </button>
              <button
                onClick={handleConfirmConversion}
                disabled={isConverting}
                className="px-5 py-2.5 text-xs font-bold text-white bg-purple-700 hover:bg-purple-800 rounded-xl shadow-md transition disabled:opacity-50"
              >
                {isConverting ? 'Converting...' : 'Confirm & Credit Wallet'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Empty State */}
      {!isLoading && filteredWins.length === 0 && (
        <div className="bg-white rounded-2xl border border-slate-200/80 p-12 text-center">
          <Trophy size={48} className="mx-auto text-slate-300 mb-3" />
          <h3 className="text-lg font-bold text-slate-700">No win records found</h3>
          <p className="text-sm text-slate-500 mt-1">
            Completed raffles with winning claims will appear here.
          </p>
        </div>
      )}

      {/* Pagination */}
      {pagination && pagination.totalPages > 1 && (
        <div className="flex justify-center items-center gap-2 pt-4">
          <button
            disabled={page <= 1}
            onClick={() => setPage((p) => p - 1)}
            className="px-4 py-2 text-xs font-bold bg-white border border-slate-200 rounded-xl disabled:opacity-50 hover:bg-slate-50 transition"
          >
            Previous
          </button>
          <span className="px-4 py-2 text-xs text-slate-600 font-semibold">
            Page {page} of {pagination.totalPages}
          </span>
          <button
            disabled={page >= pagination.totalPages}
            onClick={() => setPage((p) => p + 1)}
            className="px-4 py-2 text-xs font-bold bg-white border border-slate-200 rounded-xl disabled:opacity-50 hover:bg-slate-50 transition"
          >
            Next
          </button>
        </div>
      )}
    </div>
  );
}

'use client';

import { api } from '@/lib/api';
import { useAdminWins, useUpdateDeliveryStatus } from '@/lib/hooks/useAdmin';
import {
  ArrowUpRight,
  Check,
  CheckCircle,
  Clock,
  Copy,
  Filter,
  Mail,
  MapPin,
  Package,
  Phone,
  Search,
  Trophy,
  Truck,
  Wallet,
} from 'lucide-react';
import { useState } from 'react';
import toast from 'react-hot-toast';

const DELIVERY_STATUSES = [
  {
    value: 'PENDING',
    label: 'Pending',
    icon: Clock,
    color: 'bg-amber-50 text-amber-700 border-amber-200',
  },
  {
    value: 'PROCESSING',
    label: 'Processing',
    icon: Package,
    color: 'bg-blue-50 text-blue-700 border-blue-200',
  },
  {
    value: 'SHIPPED',
    label: 'Shipped',
    icon: Truck,
    color: 'bg-indigo-50 text-indigo-700 border-indigo-200',
  },
  {
    value: 'DELIVERED',
    label: 'Delivered',
    icon: CheckCircle,
    color: 'bg-emerald-50 text-emerald-700 border-emerald-200',
  },
  {
    value: 'CONVERTED_TO_WALLET',
    label: 'Converted to Credits',
    icon: Wallet,
    color: 'bg-purple-50 text-purple-700 border-purple-200',
  },
];

export default function AdminWinsPage() {
  const [filterStatus, setFilterStatus] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [page, setPage] = useState(1);
  const { data, isLoading, refetch } = useAdminWins({ page, deliveryStatus: filterStatus });
  const updateDelivery = useUpdateDeliveryStatus();

  const [selectedWinForConversion, setSelectedWinForConversion] = useState<any>(null);
  const [conversionAmount, setConversionAmount] = useState<number>(0);
  const [conversionNote, setConversionNote] = useState('');
  const [isConverting, setIsConverting] = useState(false);
  const [copiedField, setCopiedField] = useState<string | null>(null);

  const wins = data?.wins ?? [];
  const pagination = data?.pagination ?? null;

  const copyToClipboard = (text: string, label: string) => {
    if (!text) return;
    navigator.clipboard.writeText(text);
    setCopiedField(label);
    toast.success(`Copied ${label}`);
    setTimeout(() => setCopiedField(null), 2000);
  };

  const handleStatusChange = async (raffleId: string, newStatus: string) => {
    try {
      await updateDelivery.mutateAsync({ raffleId, deliveryStatus: newStatus });
      toast.success(`Delivery status updated to ${newStatus}`);
    } catch (err: any) {
      toast.error(err.message || 'Failed to update delivery status');
    }
  };

  const handleOpenConversionModal = (win: any) => {
    setSelectedWinForConversion(win);
    setConversionAmount(win.item?.value || 0);
    setConversionNote(
      `Unclaimed/Unavailable physical prize converted to non-withdrawable store credits for ${win.item?.name}.`,
    );
  };

  const handleConfirmConversion = async () => {
    if (!selectedWinForConversion) return;
    setIsConverting(true);
    try {
      const res = (await api.post(
        `/api/admin/wins/${selectedWinForConversion.id}/convert-to-wallet`,
        {
          amount: conversionAmount,
          note: conversionNote,
        },
      )) as any;

      if (res.success) {
        toast.success(res.message || 'Prize successfully converted to store credits!');
        setSelectedWinForConversion(null);
        refetch();
      } else {
        toast.error(res.message || 'Failed to convert prize');
      }
    } catch (err: any) {
      toast.error(err.message || 'Error converting prize to store credit');
    } finally {
      setIsConverting(false);
    }
  };

  // Filter by search query (winner name, email, item name)
  const filteredWins = wins.filter((w: any) => {
    if (!searchQuery.trim()) return true;
    const q = searchQuery.toLowerCase();
    return (
      w.item?.name?.toLowerCase().includes(q) ||
      w.winner?.name?.toLowerCase().includes(q) ||
      w.winner?.email?.toLowerCase().includes(q) ||
      w.winner?.userNumber?.toLowerCase().includes(q)
    );
  });

  // KPI Metrics calculation
  const totalWinsCount = wins.length;
  const pendingCount = wins.filter(
    (w: any) => w.deliveryStatus === 'PENDING' || w.deliveryStatus === 'PROCESSING',
  ).length;
  const deliveredCount = wins.filter((w: any) => w.deliveryStatus === 'DELIVERED').length;
  const convertedCount = wins.filter((w: any) => w.deliveryStatus === 'CONVERTED_TO_WALLET').length;

  return (
    <div className="space-y-6 pb-20 md:pb-0">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl sm:text-3xl font-bold text-slate-900 flex items-center gap-2.5">
            <div className="p-2 bg-amber-50 text-amber-600 rounded-xl">
              <Trophy size={24} />
            </div>
            Wins & Claims Management
          </h1>
          <p className="text-sm text-slate-500 mt-1">
            Track raffle prize claims, manage winner delivery fulfillment, and handle store credit
            conversions.
          </p>
        </div>
      </div>

      {/* KPI Summary Cards */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4">
        <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3">
          <div className="p-3 bg-amber-50 text-amber-600 rounded-xl shrink-0">
            <Trophy size={22} />
          </div>
          <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
              Total Winners
            </p>
            <p className="text-xl sm:text-2xl font-bold text-slate-900 mt-0.5">{totalWinsCount}</p>
          </div>
        </div>

        <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3">
          <div className="p-3 bg-blue-50 text-blue-600 rounded-xl shrink-0">
            <Clock size={22} />
          </div>
          <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
              Pending Delivery
            </p>
            <p className="text-xl sm:text-2xl font-bold text-blue-600 mt-0.5">{pendingCount}</p>
          </div>
        </div>

        <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3">
          <div className="p-3 bg-emerald-50 text-emerald-600 rounded-xl shrink-0">
            <CheckCircle size={22} />
          </div>
          <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
              Delivered
            </p>
            <p className="text-xl sm:text-2xl font-bold text-emerald-600 mt-0.5">
              {deliveredCount}
            </p>
          </div>
        </div>

        <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3">
          <div className="p-3 bg-purple-50 text-purple-600 rounded-xl shrink-0">
            <Wallet size={22} />
          </div>
          <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
              Converted Credits
            </p>
            <p className="text-xl sm:text-2xl font-bold text-purple-600 mt-0.5">{convertedCount}</p>
          </div>
        </div>
      </div>

      {/* Filter Toolbar */}
      <div className="bg-white p-4 rounded-2xl border border-slate-200/80 shadow-xs flex flex-col sm:flex-row gap-3">
        <div className="relative flex-1">
          <Search size={18} className="absolute left-3.5 top-3 text-slate-400" />
          <input
            type="text"
            placeholder="Search winner name, email, or item..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:outline-none focus:border-red-500 transition"
          />
        </div>

        <div className="flex items-center gap-2">
          <Filter size={18} className="text-slate-400 shrink-0" />
          <select
            value={filterStatus}
            onChange={(e) => {
              setFilterStatus(e.target.value);
              setPage(1);
            }}
            className="w-full sm:w-auto px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm font-semibold text-slate-700 focus:outline-none focus:border-red-500"
          >
            <option value="all">All Delivery Statuses</option>
            {DELIVERY_STATUSES.map((s) => (
              <option key={s.value} value={s.value}>
                {s.label}
              </option>
            ))}
          </select>
        </div>
      </div>

      {/* Loading */}
      {isLoading && (
        <div className="space-y-4">
          {[1, 2, 3].map((i) => (
            <div
              key={i}
              className="bg-white rounded-2xl p-6 border border-slate-100 shadow-xs animate-pulse space-y-4"
            >
              <div className="h-5 w-1/3 bg-slate-200 rounded" />
              <div className="h-4 w-2/3 bg-slate-200 rounded" />
              <div className="h-8 w-1/4 bg-slate-200 rounded" />
            </div>
          ))}
        </div>
      )}

      {/* Wins List */}
      {!isLoading && (
        <div className="space-y-4">
          {filteredWins.map((win: any) => {
            const currentStatus =
              DELIVERY_STATUSES.find((s) => s.value === win.deliveryStatus) || DELIVERY_STATUSES[0];
            const StatusIcon = currentStatus.icon;
            const imageUrl = win.item?.imageUrl?.startsWith('/uploads')
              ? `${process.env.NEXT_PUBLIC_API_URL || 'http://localhost:5000'}${win.item.imageUrl}`
              : win.item?.imageUrl;

            const winnerAddress = [win.winner?.address, win.winner?.city, win.winner?.state]
              .filter(Boolean)
              .join(', ');

            return (
              <div
                key={win.id}
                className="bg-white rounded-2xl border border-slate-200/80 p-5 shadow-xs hover:shadow-md transition space-y-4"
              >
                <div className="flex flex-col md:flex-row gap-5">
                  {/* Item Image */}
                  <div className="w-20 h-20 sm:w-24 sm:h-24 bg-slate-100 rounded-xl overflow-hidden shrink-0 border border-slate-100 flex items-center justify-center">
                    {imageUrl ? (
                      <img
                        src={imageUrl}
                        alt={win.item?.name}
                        className="w-full h-full object-cover"
                      />
                    ) : (
                      <span className="text-3xl">🏆</span>
                    )}
                  </div>

                  {/* Info & Winner Address */}
                  <div className="flex-1 min-w-0 space-y-3">
                    <div className="flex flex-wrap items-start justify-between gap-2">
                      <div>
                        <h3 className="font-bold text-slate-900 text-base sm:text-lg flex items-center gap-2">
                          {win.item?.name}
                          <span className="text-xs bg-red-50 text-red-600 px-2 py-0.5 rounded-full font-bold border border-red-100">
                            ₦{win.item?.value?.toLocaleString()}
                          </span>
                        </h3>
                      </div>
                      <span
                        className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold border ${currentStatus.color}`}
                      >
                        <StatusIcon size={14} />
                        {currentStatus.label}
                      </span>
                    </div>

                    {/* Winner Details Box */}
                    <div className="p-3.5 bg-slate-50 rounded-xl border border-slate-200/60 text-xs space-y-2">
                      <div className="flex items-center justify-between">
                        <p className="font-bold text-slate-800 text-sm">
                          Winner: <span className="text-red-600">{win.winner?.name}</span>{' '}
                          <span className="font-mono text-slate-400 text-[11px]">
                            ({win.winner?.userNumber})
                          </span>
                        </p>
                      </div>

                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 text-slate-600 pt-1">
                        {win.winner?.email && (
                          <div className="flex items-center justify-between bg-white px-2.5 py-1.5 rounded-lg border border-slate-200/60">
                            <span className="flex items-center gap-1.5 truncate">
                              <Mail size={13} className="text-slate-400 shrink-0" />
                              <span className="truncate">{win.winner.email}</span>
                            </span>
                            <button
                              onClick={() => copyToClipboard(win.winner.email, 'Email')}
                              className="text-slate-400 hover:text-slate-700 p-1"
                              title="Copy email"
                            >
                              {copiedField === 'Email' ? (
                                <Check size={13} className="text-emerald-600" />
                              ) : (
                                <Copy size={13} />
                              )}
                            </button>
                          </div>
                        )}

                        {win.winner?.phone && (
                          <div className="flex items-center justify-between bg-white px-2.5 py-1.5 rounded-lg border border-slate-200/60">
                            <span className="flex items-center gap-1.5 truncate">
                              <Phone size={13} className="text-slate-400 shrink-0" />
                              <span>{win.winner.phone}</span>
                            </span>
                            <button
                              onClick={() => copyToClipboard(win.winner.phone, 'Phone')}
                              className="text-slate-400 hover:text-slate-700 p-1"
                              title="Copy phone"
                            >
                              {copiedField === 'Phone' ? (
                                <Check size={13} className="text-emerald-600" />
                              ) : (
                                <Copy size={13} />
                              )}
                            </button>
                          </div>
                        )}
                      </div>

                      {winnerAddress ? (
                        <div className="pt-1 flex items-start gap-1.5 font-medium text-slate-700">
                          <MapPin size={14} className="text-red-500 shrink-0 mt-0.5" />
                          <span>
                            <strong>Shipping Address:</strong> {winnerAddress}
                          </span>
                        </div>
                      ) : (
                        <div className="pt-1 flex items-center gap-1.5 italic text-slate-400">
                          <MapPin size={13} className="text-slate-300" />
                          <span>Delivery address not yet set in winner profile</span>
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Action Box */}
                  <div className="flex flex-col gap-2.5 justify-center md:items-end shrink-0 pt-3 md:pt-0 border-t md:border-t-0 border-slate-100">
                    <label className="text-[11px] font-bold text-slate-400 uppercase tracking-wider">
                      Update Delivery Status
                    </label>
                    <select
                      value={win.deliveryStatus}
                      onChange={(e) => handleStatusChange(win.id, e.target.value)}
                      disabled={
                        updateDelivery.isPending || win.deliveryStatus === 'CONVERTED_TO_WALLET'
                      }
                      className="text-xs px-3.5 py-2.5 border border-slate-200 rounded-xl focus:outline-none focus:border-red-500 bg-white font-bold text-slate-700 disabled:opacity-50 shadow-xs"
                    >
                      {DELIVERY_STATUSES.map((s) => (
                        <option key={s.value} value={s.value}>
                          {s.label}
                        </option>
                      ))}
                    </select>

                    {win.deliveryStatus !== 'CONVERTED_TO_WALLET' && (
                      <button
                        onClick={() => handleOpenConversionModal(win)}
                        className="inline-flex items-center justify-center gap-1.5 px-3.5 py-2 bg-purple-50 hover:bg-purple-100 text-purple-700 border border-purple-200/80 rounded-xl text-xs font-bold transition shadow-xs"
                      >
                        <Wallet size={14} />
                        Convert Prize to Store Credits
                      </button>
                    )}
                  </div>
                </div>

                {/* Delivery Note */}
                {win.deliveryNote && (
                  <div className="pt-3 border-t border-slate-100 text-xs text-slate-500">
                    <strong className="text-slate-700">Delivery Note:</strong> {win.deliveryNote}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}

      {/* Conversion Modal */}
      {selectedWinForConversion && (
        <div className="fixed inset-0 z-[1001] bg-black/60 backdrop-blur-sm flex items-end sm:items-center justify-center p-0 sm:p-4">
          <div className="bg-white rounded-t-3xl sm:rounded-2xl max-w-md w-full p-6 pb-20 sm:pb-6 shadow-2xl space-y-4 animate-in slide-in-from-bottom sm:zoom-in-95 duration-200">
            {/* Mobile Sheet Bar */}
            <div className="w-12 h-1.5 bg-slate-200 rounded-full mx-auto sm:hidden mb-1" />

            <div className="flex items-center gap-3 text-purple-700">
              <div className="p-3 bg-purple-100 rounded-xl shrink-0">
                <Wallet size={24} />
              </div>
              <div>
                <h3 className="font-bold text-lg text-slate-900">Convert Prize to Store Credits</h3>
                <p className="text-xs text-slate-500">
                  Credit winner&apos;s non-withdrawable wallet balance
                </p>
              </div>
            </div>

            <div className="p-3.5 bg-purple-50 rounded-xl border border-purple-100 text-xs space-y-1.5 text-purple-900 font-medium">
              <p>
                Winner: <strong>{selectedWinForConversion.winner?.name}</strong>
              </p>
              <p>
                Prize Item: <strong>{selectedWinForConversion.item?.name}</strong>
              </p>
              <p>
                Item Market Value:{' '}
                <strong>₦{selectedWinForConversion.item?.value?.toLocaleString()}</strong>
              </p>
              <div className="text-[11px] text-purple-700 bg-purple-100/70 p-2.5 rounded-lg mt-2 font-normal leading-relaxed">
                💡 Credited funds are non-withdrawable cash and can only be used by the winner to
                purchase raffle tickets on the platform.
              </div>
            </div>

            <div className="space-y-3">
              <div>
                <label className="block text-xs font-bold text-slate-700 uppercase mb-1">
                  Credit Amount (₦)
                </label>
                <input
                  type="number"
                  value={conversionAmount}
                  onChange={(e) => setConversionAmount(Number(e.target.value))}
                  className="w-full px-3.5 py-2.5 border border-slate-200 rounded-xl text-sm focus:outline-none focus:border-purple-600 font-bold"
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 uppercase mb-1">
                  Admin Note / Reason
                </label>
                <textarea
                  value={conversionNote}
                  onChange={(e) => setConversionNote(e.target.value)}
                  rows={3}
                  className="w-full px-3.5 py-2.5 border border-slate-200 rounded-xl text-xs focus:outline-none focus:border-purple-600 resize-none"
                />
              </div>
            </div>

            <div className="flex items-center justify-end gap-2 pt-2">
              <button
                onClick={() => setSelectedWinForConversion(null)}
                className="px-4 py-2.5 text-xs font-bold text-slate-600 hover:bg-slate-100 rounded-xl transition"
              >
                Cancel
              </button>
              <button
                onClick={handleConfirmConversion}
                disabled={isConverting}
                className="px-5 py-2.5 text-xs font-bold text-white bg-purple-700 hover:bg-purple-800 rounded-xl shadow-md transition disabled:opacity-50"
              >
                {isConverting ? 'Converting...' : 'Confirm & Credit Wallet'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Empty State */}
      {!isLoading && filteredWins.length === 0 && (
        <div className="bg-white rounded-2xl border border-slate-200/80 p-12 text-center">
          <Trophy size={48} className="mx-auto text-slate-300 mb-3" />
          <h3 className="text-lg font-bold text-slate-700">No win records found</h3>
          <p className="text-sm text-slate-500 mt-1">
            Completed raffles with winning claims will appear here.
          </p>
        </div>
      )}

      {/* Pagination */}
      {pagination && pagination.totalPages > 1 && (
        <div className="flex justify-center items-center gap-2 pt-4">
          <button
            disabled={page <= 1}
            onClick={() => setPage((p) => p - 1)}
            className="px-4 py-2 text-xs font-bold bg-white border border-slate-200 rounded-xl disabled:opacity-50 hover:bg-slate-50 transition"
          >
            Previous
          </button>
          <span className="px-4 py-2 text-xs text-slate-600 font-semibold">
            Page {page} of {pagination.totalPages}
          </span>
          <button
            disabled={page >= pagination.totalPages}
            onClick={() => setPage((p) => p + 1)}
            className="px-4 py-2 text-xs font-bold bg-white border border-slate-200 rounded-xl disabled:opacity-50 hover:bg-slate-50 transition"
          >
            Next
          </button>
        </div>
      )}
    </div>
  );
}

'use client';

import { api } from '@/lib/api';
import { useAdminWins, useUpdateDeliveryStatus } from '@/lib/hooks/useAdmin';
import {
  ArrowUpRight,
  Check,
  CheckCircle,
  Clock,
  Copy,
  Filter,
  Mail,
  MapPin,
  Package,
  Phone,
  Search,
  Trophy,
  Truck,
  Wallet,
} from 'lucide-react';
import { useState } from 'react';
import toast from 'react-hot-toast';

const DELIVERY_STATUSES = [
  {
    value: 'PENDING',
    label: 'Pending',
    icon: Clock,
    color: 'bg-amber-50 text-amber-700 border-amber-200',
  },
  {
    value: 'PROCESSING',
    label: 'Processing',
    icon: Package,
    color: 'bg-blue-50 text-blue-700 border-blue-200',
  },
  {
    value: 'SHIPPED',
    label: 'Shipped',
    icon: Truck,
    color: 'bg-indigo-50 text-indigo-700 border-indigo-200',
  },
  {
    value: 'DELIVERED',
    label: 'Delivered',
    icon: CheckCircle,
    color: 'bg-emerald-50 text-emerald-700 border-emerald-200',
  },
  {
    value: 'CONVERTED_TO_WALLET',
    label: 'Converted to Credits',
    icon: Wallet,
    color: 'bg-purple-50 text-purple-700 border-purple-200',
  },
];

export default function AdminWinsPage() {
  const [filterStatus, setFilterStatus] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [page, setPage] = useState(1);
  const { data, isLoading, refetch } = useAdminWins({ page, deliveryStatus: filterStatus });
  const updateDelivery = useUpdateDeliveryStatus();

  const [selectedWinForConversion, setSelectedWinForConversion] = useState<any>(null);
  const [conversionAmount, setConversionAmount] = useState<number>(0);
  const [conversionNote, setConversionNote] = useState('');
  const [isConverting, setIsConverting] = useState(false);
  const [copiedField, setCopiedField] = useState<string | null>(null);

  const wins = data?.wins ?? [];
  const pagination = data?.pagination ?? null;

  const copyToClipboard = (text: string, label: string) => {
    if (!text) return;
    navigator.clipboard.writeText(text);
    setCopiedField(label);
    toast.success(`Copied ${label}`);
    setTimeout(() => setCopiedField(null), 2000);
  };

  const handleStatusChange = async (raffleId: string, newStatus: string) => {
    try {
      await updateDelivery.mutateAsync({ raffleId, deliveryStatus: newStatus });
      toast.success(`Delivery status updated to ${newStatus}`);
    } catch (err: any) {
      toast.error(err.message || 'Failed to update delivery status');
    }
  };

  const handleOpenConversionModal = (win: any) => {
    setSelectedWinForConversion(win);
    setConversionAmount(win.item?.value || 0);
    setConversionNote(
      `Unclaimed/Unavailable physical prize converted to non-withdrawable store credits for ${win.item?.name}.`,
    );
  };

  const handleConfirmConversion = async () => {
    if (!selectedWinForConversion) return;
    setIsConverting(true);
    try {
      const res = (await api.post(
        `/api/admin/wins/${selectedWinForConversion.id}/convert-to-wallet`,
        {
          amount: conversionAmount,
          note: conversionNote,
        },
      )) as any;

      if (res.success) {
        toast.success(res.message || 'Prize successfully converted to store credits!');
        setSelectedWinForConversion(null);
        refetch();
      } else {
        toast.error(res.message || 'Failed to convert prize');
      }
    } catch (err: any) {
      toast.error(err.message || 'Error converting prize to store credit');
    } finally {
      setIsConverting(false);
    }
  };

  // Filter by search query (winner name, email, item name)
  const filteredWins = wins.filter((w: any) => {
    if (!searchQuery.trim()) return true;
    const q = searchQuery.toLowerCase();
    return (
      w.item?.name?.toLowerCase().includes(q) ||
      w.winner?.name?.toLowerCase().includes(q) ||
      w.winner?.email?.toLowerCase().includes(q) ||
      w.winner?.userNumber?.toLowerCase().includes(q)
    );
  });

  // KPI Metrics calculation
  const totalWinsCount = wins.length;
  const pendingCount = wins.filter(
    (w: any) => w.deliveryStatus === 'PENDING' || w.deliveryStatus === 'PROCESSING',
  ).length;
  const deliveredCount = wins.filter((w: any) => w.deliveryStatus === 'DELIVERED').length;
  const convertedCount = wins.filter((w: any) => w.deliveryStatus === 'CONVERTED_TO_WALLET').length;

  return (
    <div className="space-y-6 pb-20 md:pb-0">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl sm:text-3xl font-bold text-slate-900 flex items-center gap-2.5">
            <div className="p-2 bg-amber-50 text-amber-600 rounded-xl">
              <Trophy size={24} />
            </div>
            Wins & Claims Management
          </h1>
          <p className="text-sm text-slate-500 mt-1">
            Track raffle prize claims, manage winner delivery fulfillment, and handle store credit
            conversions.
          </p>
        </div>
      </div>

      {/* KPI Summary Cards */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4">
        <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3">
          <div className="p-3 bg-amber-50 text-amber-600 rounded-xl shrink-0">
            <Trophy size={22} />
          </div>
          <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
              Total Winners
            </p>
            <p className="text-xl sm:text-2xl font-bold text-slate-900 mt-0.5">{totalWinsCount}</p>
          </div>
        </div>

        <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3">
          <div className="p-3 bg-blue-50 text-blue-600 rounded-xl shrink-0">
            <Clock size={22} />
          </div>
          <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
              Pending Delivery
            </p>
            <p className="text-xl sm:text-2xl font-bold text-blue-600 mt-0.5">{pendingCount}</p>
          </div>
        </div>

        <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3">
          <div className="p-3 bg-emerald-50 text-emerald-600 rounded-xl shrink-0">
            <CheckCircle size={22} />
          </div>
          <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
              Delivered
            </p>
            <p className="text-xl sm:text-2xl font-bold text-emerald-600 mt-0.5">
              {deliveredCount}
            </p>
          </div>
        </div>

        <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3">
          <div className="p-3 bg-purple-50 text-purple-600 rounded-xl shrink-0">
            <Wallet size={22} />
          </div>
          <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
              Converted Credits
            </p>
            <p className="text-xl sm:text-2xl font-bold text-purple-600 mt-0.5">{convertedCount}</p>
          </div>
        </div>
      </div>

      {/* Filter Toolbar */}
      <div className="bg-white p-4 rounded-2xl border border-slate-200/80 shadow-xs flex flex-col sm:flex-row gap-3">
        <div className="relative flex-1">
          <Search size={18} className="absolute left-3.5 top-3 text-slate-400" />
          <input
            type="text"
            placeholder="Search winner name, email, or item..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:outline-none focus:border-red-500 transition"
          />
        </div>

        <div className="flex items-center gap-2">
          <Filter size={18} className="text-slate-400 shrink-0" />
          <select
            value={filterStatus}
            onChange={(e) => {
              setFilterStatus(e.target.value);
              setPage(1);
            }}
            className="w-full sm:w-auto px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm font-semibold text-slate-700 focus:outline-none focus:border-red-500"
          >
            <option value="all">All Delivery Statuses</option>
            {DELIVERY_STATUSES.map((s) => (
              <option key={s.value} value={s.value}>
                {s.label}
              </option>
            ))}
          </select>
        </div>
      </div>

      {/* Loading */}
      {isLoading && (
        <div className="space-y-4">
          {[1, 2, 3].map((i) => (
            <div
              key={i}
              className="bg-white rounded-2xl p-6 border border-slate-100 shadow-xs animate-pulse space-y-4"
            >
              <div className="h-5 w-1/3 bg-slate-200 rounded" />
              <div className="h-4 w-2/3 bg-slate-200 rounded" />
              <div className="h-8 w-1/4 bg-slate-200 rounded" />
            </div>
          ))}
        </div>
      )}

      {/* Wins List */}
      {!isLoading && (
        <div className="space-y-4">
          {filteredWins.map((win: any) => {
            const currentStatus =
              DELIVERY_STATUSES.find((s) => s.value === win.deliveryStatus) || DELIVERY_STATUSES[0];
            const StatusIcon = currentStatus.icon;
            const imageUrl = win.item?.imageUrl?.startsWith('/uploads')
              ? `${process.env.NEXT_PUBLIC_API_URL || 'http://localhost:5000'}${win.item.imageUrl}`
              : win.item?.imageUrl;

            const winnerAddress = [win.winner?.address, win.winner?.city, win.winner?.state]
              .filter(Boolean)
              .join(', ');

            return (
              <div
                key={win.id}
                className="bg-white rounded-2xl border border-slate-200/80 p-5 shadow-xs hover:shadow-md transition space-y-4"
              >
                <div className="flex flex-col md:flex-row gap-5">
                  {/* Item Image */}
                  <div className="w-20 h-20 sm:w-24 sm:h-24 bg-slate-100 rounded-xl overflow-hidden shrink-0 border border-slate-100 flex items-center justify-center">
                    {imageUrl ? (
                      <img
                        src={imageUrl}
                        alt={win.item?.name}
                        className="w-full h-full object-cover"
                      />
                    ) : (
                      <span className="text-3xl">🏆</span>
                    )}
                  </div>

                  {/* Info & Winner Address */}
                  <div className="flex-1 min-w-0 space-y-3">
                    <div className="flex flex-wrap items-start justify-between gap-2">
                      <div>
                        <h3 className="font-bold text-slate-900 text-base sm:text-lg flex items-center gap-2">
                          {win.item?.name}
                          <span className="text-xs bg-red-50 text-red-600 px-2 py-0.5 rounded-full font-bold border border-red-100">
                            ₦{win.item?.value?.toLocaleString()}
                          </span>
                        </h3>
                      </div>
                      <span
                        className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold border ${currentStatus.color}`}
                      >
                        <StatusIcon size={14} />
                        {currentStatus.label}
                      </span>
                    </div>

                    {/* Winner Details Box */}
                    <div className="p-3.5 bg-slate-50 rounded-xl border border-slate-200/60 text-xs space-y-2">
                      <div className="flex items-center justify-between">
                        <p className="font-bold text-slate-800 text-sm">
                          Winner: <span className="text-red-600">{win.winner?.name}</span>{' '}
                          <span className="font-mono text-slate-400 text-[11px]">
                            ({win.winner?.userNumber})
                          </span>
                        </p>
                      </div>

                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 text-slate-600 pt-1">
                        {win.winner?.email && (
                          <div className="flex items-center justify-between bg-white px-2.5 py-1.5 rounded-lg border border-slate-200/60">
                            <span className="flex items-center gap-1.5 truncate">
                              <Mail size={13} className="text-slate-400 shrink-0" />
                              <span className="truncate">{win.winner.email}</span>
                            </span>
                            <button
                              onClick={() => copyToClipboard(win.winner.email, 'Email')}
                              className="text-slate-400 hover:text-slate-700 p-1"
                              title="Copy email"
                            >
                              {copiedField === 'Email' ? (
                                <Check size={13} className="text-emerald-600" />
                              ) : (
                                <Copy size={13} />
                              )}
                            </button>
                          </div>
                        )}

                        {win.winner?.phone && (
                          <div className="flex items-center justify-between bg-white px-2.5 py-1.5 rounded-lg border border-slate-200/60">
                            <span className="flex items-center gap-1.5 truncate">
                              <Phone size={13} className="text-slate-400 shrink-0" />
                              <span>{win.winner.phone}</span>
                            </span>
                            <button
                              onClick={() => copyToClipboard(win.winner.phone, 'Phone')}
                              className="text-slate-400 hover:text-slate-700 p-1"
                              title="Copy phone"
                            >
                              {copiedField === 'Phone' ? (
                                <Check size={13} className="text-emerald-600" />
                              ) : (
                                <Copy size={13} />
                              )}
                            </button>
                          </div>
                        )}
                      </div>

                      {winnerAddress ? (
                        <div className="pt-1 flex items-start gap-1.5 font-medium text-slate-700">
                          <MapPin size={14} className="text-red-500 shrink-0 mt-0.5" />
                          <span>
                            <strong>Shipping Address:</strong> {winnerAddress}
                          </span>
                        </div>
                      ) : (
                        <div className="pt-1 flex items-center gap-1.5 italic text-slate-400">
                          <MapPin size={13} className="text-slate-300" />
                          <span>Delivery address not yet set in winner profile</span>
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Action Box */}
                  <div className="flex flex-col gap-2.5 justify-center md:items-end shrink-0 pt-3 md:pt-0 border-t md:border-t-0 border-slate-100">
                    <label className="text-[11px] font-bold text-slate-400 uppercase tracking-wider">
                      Update Delivery Status
                    </label>
                    <select
                      value={win.deliveryStatus}
                      onChange={(e) => handleStatusChange(win.id, e.target.value)}
                      disabled={
                        updateDelivery.isPending || win.deliveryStatus === 'CONVERTED_TO_WALLET'
                      }
                      className="text-xs px-3.5 py-2.5 border border-slate-200 rounded-xl focus:outline-none focus:border-red-500 bg-white font-bold text-slate-700 disabled:opacity-50 shadow-xs"
                    >
                      {DELIVERY_STATUSES.map((s) => (
                        <option key={s.value} value={s.value}>
                          {s.label}
                        </option>
                      ))}
                    </select>

                    {win.deliveryStatus !== 'CONVERTED_TO_WALLET' && (
                      <button
                        onClick={() => handleOpenConversionModal(win)}
                        className="inline-flex items-center justify-center gap-1.5 px-3.5 py-2 bg-purple-50 hover:bg-purple-100 text-purple-700 border border-purple-200/80 rounded-xl text-xs font-bold transition shadow-xs"
                      >
                        <Wallet size={14} />
                        Convert Prize to Store Credits
                      </button>
                    )}
                  </div>
                </div>

                {/* Delivery Note */}
                {win.deliveryNote && (
                  <div className="pt-3 border-t border-slate-100 text-xs text-slate-500">
                    <strong className="text-slate-700">Delivery Note:</strong> {win.deliveryNote}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}

      {/* Conversion Modal */}
      {selectedWinForConversion && (
        <div className="fixed inset-0 z-[1001] bg-black/60 backdrop-blur-sm flex items-end sm:items-center justify-center p-0 sm:p-4">
          <div className="bg-white rounded-t-3xl sm:rounded-2xl max-w-md w-full p-6 pb-20 sm:pb-6 shadow-2xl space-y-4 animate-in slide-in-from-bottom sm:zoom-in-95 duration-200">
            {/* Mobile Sheet Bar */}
            <div className="w-12 h-1.5 bg-slate-200 rounded-full mx-auto sm:hidden mb-1" />

            <div className="flex items-center gap-3 text-purple-700">
              <div className="p-3 bg-purple-100 rounded-xl shrink-0">
                <Wallet size={24} />
              </div>
              <div>
                <h3 className="font-bold text-lg text-slate-900">Convert Prize to Store Credits</h3>
                <p className="text-xs text-slate-500">
                  Credit winner&apos;s non-withdrawable wallet balance
                </p>
              </div>
            </div>

            <div className="p-3.5 bg-purple-50 rounded-xl border border-purple-100 text-xs space-y-1.5 text-purple-900 font-medium">
              <p>
                Winner: <strong>{selectedWinForConversion.winner?.name}</strong>
              </p>
              <p>
                Prize Item: <strong>{selectedWinForConversion.item?.name}</strong>
              </p>
              <p>
                Item Market Value:{' '}
                <strong>₦{selectedWinForConversion.item?.value?.toLocaleString()}</strong>
              </p>
              <div className="text-[11px] text-purple-700 bg-purple-100/70 p-2.5 rounded-lg mt-2 font-normal leading-relaxed">
                💡 Credited funds are non-withdrawable cash and can only be used by the winner to
                purchase raffle tickets on the platform.
              </div>
            </div>

            <div className="space-y-3">
              <div>
                <label className="block text-xs font-bold text-slate-700 uppercase mb-1">
                  Credit Amount (₦)
                </label>
                <input
                  type="number"
                  value={conversionAmount}
                  onChange={(e) => setConversionAmount(Number(e.target.value))}
                  className="w-full px-3.5 py-2.5 border border-slate-200 rounded-xl text-sm focus:outline-none focus:border-purple-600 font-bold"
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 uppercase mb-1">
                  Admin Note / Reason
                </label>
                <textarea
                  value={conversionNote}
                  onChange={(e) => setConversionNote(e.target.value)}
                  rows={3}
                  className="w-full px-3.5 py-2.5 border border-slate-200 rounded-xl text-xs focus:outline-none focus:border-purple-600 resize-none"
                />
              </div>
            </div>

            <div className="flex items-center justify-end gap-2 pt-2">
              <button
                onClick={() => setSelectedWinForConversion(null)}
                className="px-4 py-2.5 text-xs font-bold text-slate-600 hover:bg-slate-100 rounded-xl transition"
              >
                Cancel
              </button>
              <button
                onClick={handleConfirmConversion}
                disabled={isConverting}
                className="px-5 py-2.5 text-xs font-bold text-white bg-purple-700 hover:bg-purple-800 rounded-xl shadow-md transition disabled:opacity-50"
              >
                {isConverting ? 'Converting...' : 'Confirm & Credit Wallet'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Empty State */}
      {!isLoading && filteredWins.length === 0 && (
        <div className="bg-white rounded-2xl border border-slate-200/80 p-12 text-center">
          <Trophy size={48} className="mx-auto text-slate-300 mb-3" />
          <h3 className="text-lg font-bold text-slate-700">No win records found</h3>
          <p className="text-sm text-slate-500 mt-1">
            Completed raffles with winning claims will appear here.
          </p>
        </div>
      )}

      {/* Pagination */}
      {pagination && pagination.totalPages > 1 && (
        <div className="flex justify-center items-center gap-2 pt-4">
          <button
            disabled={page <= 1}
            onClick={() => setPage((p) => p - 1)}
            className="px-4 py-2 text-xs font-bold bg-white border border-slate-200 rounded-xl disabled:opacity-50 hover:bg-slate-50 transition"
          >
            Previous
          </button>
          <span className="px-4 py-2 text-xs text-slate-600 font-semibold">
            Page {page} of {pagination.totalPages}
          </span>
          <button
            disabled={page >= pagination.totalPages}
            onClick={() => setPage((p) => p + 1)}
            className="px-4 py-2 text-xs font-bold bg-white border border-slate-200 rounded-xl disabled:opacity-50 hover:bg-slate-50 transition"
          >
            Next
          </button>
        </div>
      )}
    </div>
  );
}

'use client';

import { api } from '@/lib/api';
import { useAdminWins, useUpdateDeliveryStatus } from '@/lib/hooks/useAdmin';
import {
  ArrowUpRight,
  Check,
  CheckCircle,
  Clock,
  Copy,
  Filter,
  Mail,
  MapPin,
  Package,
  Phone,
  Search,
  Trophy,
  Truck,
  Wallet,
} from 'lucide-react';
import { useState } from 'react';
import toast from 'react-hot-toast';

const DELIVERY_STATUSES = [
  {
    value: 'PENDING',
    label: 'Pending',
    icon: Clock,
    color: 'bg-amber-50 text-amber-700 border-amber-200',
  },
  {
    value: 'PROCESSING',
    label: 'Processing',
    icon: Package,
    color: 'bg-blue-50 text-blue-700 border-blue-200',
  },
  {
    value: 'SHIPPED',
    label: 'Shipped',
    icon: Truck,
    color: 'bg-indigo-50 text-indigo-700 border-indigo-200',
  },
  {
    value: 'DELIVERED',
    label: 'Delivered',
    icon: CheckCircle,
    color: 'bg-emerald-50 text-emerald-700 border-emerald-200',
  },
  {
    value: 'CONVERTED_TO_WALLET',
    label: 'Converted to Credits',
    icon: Wallet,
    color: 'bg-purple-50 text-purple-700 border-purple-200',
  },
];

export default function AdminWinsPage() {
  const [filterStatus, setFilterStatus] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [page, setPage] = useState(1);
  const { data, isLoading, refetch } = useAdminWins({ page, deliveryStatus: filterStatus });
  const updateDelivery = useUpdateDeliveryStatus();

  const [selectedWinForConversion, setSelectedWinForConversion] = useState<any>(null);
  const [conversionAmount, setConversionAmount] = useState<number>(0);
  const [conversionNote, setConversionNote] = useState('');
  const [isConverting, setIsConverting] = useState(false);
  const [copiedField, setCopiedField] = useState<string | null>(null);

  const wins = data?.wins ?? [];
  const pagination = data?.pagination ?? null;

  const copyToClipboard = (text: string, label: string) => {
    if (!text) return;
    navigator.clipboard.writeText(text);
    setCopiedField(label);
    toast.success(`Copied ${label}`);
    setTimeout(() => setCopiedField(null), 2000);
  };

  const handleStatusChange = async (raffleId: string, newStatus: string) => {
    try {
      await updateDelivery.mutateAsync({ raffleId, deliveryStatus: newStatus });
      toast.success(`Delivery status updated to ${newStatus}`);
    } catch (err: any) {
      toast.error(err.message || 'Failed to update delivery status');
    }
  };

  const handleOpenConversionModal = (win: any) => {
    setSelectedWinForConversion(win);
    setConversionAmount(win.item?.value || 0);
    setConversionNote(
      `Unclaimed/Unavailable physical prize converted to non-withdrawable store credits for ${win.item?.name}.`,
    );
  };

  const handleConfirmConversion = async () => {
    if (!selectedWinForConversion) return;
    setIsConverting(true);
    try {
      const res = (await api.post(
        `/api/admin/wins/${selectedWinForConversion.id}/convert-to-wallet`,
        {
          amount: conversionAmount,
          note: conversionNote,
        },
      )) as any;

      if (res.success) {
        toast.success(res.message || 'Prize successfully converted to store credits!');
        setSelectedWinForConversion(null);
        refetch();
      } else {
        toast.error(res.message || 'Failed to convert prize');
      }
    } catch (err: any) {
      toast.error(err.message || 'Error converting prize to store credit');
    } finally {
      setIsConverting(false);
    }
  };

  // Filter by search query (winner name, email, item name)
  const filteredWins = wins.filter((w: any) => {
    if (!searchQuery.trim()) return true;
    const q = searchQuery.toLowerCase();
    return (
      w.item?.name?.toLowerCase().includes(q) ||
      w.winner?.name?.toLowerCase().includes(q) ||
      w.winner?.email?.toLowerCase().includes(q) ||
      w.winner?.userNumber?.toLowerCase().includes(q)
    );
  });

  // KPI Metrics calculation
  const totalWinsCount = wins.length;
  const pendingCount = wins.filter(
    (w: any) => w.deliveryStatus === 'PENDING' || w.deliveryStatus === 'PROCESSING',
  ).length;
  const deliveredCount = wins.filter((w: any) => w.deliveryStatus === 'DELIVERED').length;
  const convertedCount = wins.filter((w: any) => w.deliveryStatus === 'CONVERTED_TO_WALLET').length;

  return (
    <div className="space-y-6 pb-20 md:pb-0">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl sm:text-3xl font-bold text-slate-900 flex items-center gap-2.5">
            <div className="p-2 bg-amber-50 text-amber-600 rounded-xl">
              <Trophy size={24} />
            </div>
            Wins & Claims Management
          </h1>
          <p className="text-sm text-slate-500 mt-1">
            Track raffle prize claims, manage winner delivery fulfillment, and handle store credit
            conversions.
          </p>
        </div>
      </div>

      {/* KPI Summary Cards */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4">
        <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3">
          <div className="p-3 bg-amber-50 text-amber-600 rounded-xl shrink-0">
            <Trophy size={22} />
          </div>
          <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
              Total Winners
            </p>
            <p className="text-xl sm:text-2xl font-bold text-slate-900 mt-0.5">{totalWinsCount}</p>
          </div>
        </div>

        <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3">
          <div className="p-3 bg-blue-50 text-blue-600 rounded-xl shrink-0">
            <Clock size={22} />
          </div>
          <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
              Pending Delivery
            </p>
            <p className="text-xl sm:text-2xl font-bold text-blue-600 mt-0.5">{pendingCount}</p>
          </div>
        </div>

        <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3">
          <div className="p-3 bg-emerald-50 text-emerald-600 rounded-xl shrink-0">
            <CheckCircle size={22} />
          </div>
          <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
              Delivered
            </p>
            <p className="text-xl sm:text-2xl font-bold text-emerald-600 mt-0.5">
              {deliveredCount}
            </p>
          </div>
        </div>

        <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3">
          <div className="p-3 bg-purple-50 text-purple-600 rounded-xl shrink-0">
            <Wallet size={22} />
          </div>
          <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
              Converted Credits
            </p>
            <p className="text-xl sm:text-2xl font-bold text-purple-600 mt-0.5">{convertedCount}</p>
          </div>
        </div>
      </div>

      {/* Filter Toolbar */}
      <div className="bg-white p-4 rounded-2xl border border-slate-200/80 shadow-xs flex flex-col sm:flex-row gap-3">
        <div className="relative flex-1">
          <Search size={18} className="absolute left-3.5 top-3 text-slate-400" />
          <input
            type="text"
            placeholder="Search winner name, email, or item..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:outline-none focus:border-red-500 transition"
          />
        </div>

        <div className="flex items-center gap-2">
          <Filter size={18} className="text-slate-400 shrink-0" />
          <select
            value={filterStatus}
            onChange={(e) => {
              setFilterStatus(e.target.value);
              setPage(1);
            }}
            className="w-full sm:w-auto px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm font-semibold text-slate-700 focus:outline-none focus:border-red-500"
          >
            <option value="all">All Delivery Statuses</option>
            {DELIVERY_STATUSES.map((s) => (
              <option key={s.value} value={s.value}>
                {s.label}
              </option>
            ))}
          </select>
        </div>
      </div>

      {/* Loading */}
      {isLoading && (
        <div className="space-y-4">
          {[1, 2, 3].map((i) => (
            <div
              key={i}
              className="bg-white rounded-2xl p-6 border border-slate-100 shadow-xs animate-pulse space-y-4"
            >
              <div className="h-5 w-1/3 bg-slate-200 rounded" />
              <div className="h-4 w-2/3 bg-slate-200 rounded" />
              <div className="h-8 w-1/4 bg-slate-200 rounded" />
            </div>
          ))}
        </div>
      )}

      {/* Wins List */}
      {!isLoading && (
        <div className="space-y-4">
          {filteredWins.map((win: any) => {
            const currentStatus =
              DELIVERY_STATUSES.find((s) => s.value === win.deliveryStatus) || DELIVERY_STATUSES[0];
            const StatusIcon = currentStatus.icon;
            const imageUrl = win.item?.imageUrl?.startsWith('/uploads')
              ? `${process.env.NEXT_PUBLIC_API_URL || 'http://localhost:5000'}${win.item.imageUrl}`
              : win.item?.imageUrl;

            const winnerAddress = [win.winner?.address, win.winner?.city, win.winner?.state]
              .filter(Boolean)
              .join(', ');

            return (
              <div
                key={win.id}
                className="bg-white rounded-2xl border border-slate-200/80 p-5 shadow-xs hover:shadow-md transition space-y-4"
              >
                <div className="flex flex-col md:flex-row gap-5">
                  {/* Item Image */}
                  <div className="w-20 h-20 sm:w-24 sm:h-24 bg-slate-100 rounded-xl overflow-hidden shrink-0 border border-slate-100 flex items-center justify-center">
                    {imageUrl ? (
                      <img
                        src={imageUrl}
                        alt={win.item?.name}
                        className="w-full h-full object-cover"
                      />
                    ) : (
                      <span className="text-3xl">🏆</span>
                    )}
                  </div>

                  {/* Info & Winner Address */}
                  <div className="flex-1 min-w-0 space-y-3">
                    <div className="flex flex-wrap items-start justify-between gap-2">
                      <div>
                        <h3 className="font-bold text-slate-900 text-base sm:text-lg flex items-center gap-2">
                          {win.item?.name}
                          <span className="text-xs bg-red-50 text-red-600 px-2 py-0.5 rounded-full font-bold border border-red-100">
                            ₦{win.item?.value?.toLocaleString()}
                          </span>
                        </h3>
                      </div>
                      <span
                        className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold border ${currentStatus.color}`}
                      >
                        <StatusIcon size={14} />
                        {currentStatus.label}
                      </span>
                    </div>

                    {/* Winner Details Box */}
                    <div className="p-3.5 bg-slate-50 rounded-xl border border-slate-200/60 text-xs space-y-2">
                      <div className="flex items-center justify-between">
                        <p className="font-bold text-slate-800 text-sm">
                          Winner: <span className="text-red-600">{win.winner?.name}</span>{' '}
                          <span className="font-mono text-slate-400 text-[11px]">
                            ({win.winner?.userNumber})
                          </span>
                        </p>
                      </div>

                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 text-slate-600 pt-1">
                        {win.winner?.email && (
                          <div className="flex items-center justify-between bg-white px-2.5 py-1.5 rounded-lg border border-slate-200/60">
                            <span className="flex items-center gap-1.5 truncate">
                              <Mail size={13} className="text-slate-400 shrink-0" />
                              <span className="truncate">{win.winner.email}</span>
                            </span>
                            <button
                              onClick={() => copyToClipboard(win.winner.email, 'Email')}
                              className="text-slate-400 hover:text-slate-700 p-1"
                              title="Copy email"
                            >
                              {copiedField === 'Email' ? (
                                <Check size={13} className="text-emerald-600" />
                              ) : (
                                <Copy size={13} />
                              )}
                            </button>
                          </div>
                        )}

                        {win.winner?.phone && (
                          <div className="flex items-center justify-between bg-white px-2.5 py-1.5 rounded-lg border border-slate-200/60">
                            <span className="flex items-center gap-1.5 truncate">
                              <Phone size={13} className="text-slate-400 shrink-0" />
                              <span>{win.winner.phone}</span>
                            </span>
                            <button
                              onClick={() => copyToClipboard(win.winner.phone, 'Phone')}
                              className="text-slate-400 hover:text-slate-700 p-1"
                              title="Copy phone"
                            >
                              {copiedField === 'Phone' ? (
                                <Check size={13} className="text-emerald-600" />
                              ) : (
                                <Copy size={13} />
                              )}
                            </button>
                          </div>
                        )}
                      </div>

                      {winnerAddress ? (
                        <div className="pt-1 flex items-start gap-1.5 font-medium text-slate-700">
                          <MapPin size={14} className="text-red-500 shrink-0 mt-0.5" />
                          <span>
                            <strong>Shipping Address:</strong> {winnerAddress}
                          </span>
                        </div>
                      ) : (
                        <div className="pt-1 flex items-center gap-1.5 italic text-slate-400">
                          <MapPin size={13} className="text-slate-300" />
                          <span>Delivery address not yet set in winner profile</span>
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Action Box */}
                  <div className="flex flex-col gap-2.5 justify-center md:items-end shrink-0 pt-3 md:pt-0 border-t md:border-t-0 border-slate-100">
                    <label className="text-[11px] font-bold text-slate-400 uppercase tracking-wider">
                      Update Delivery Status
                    </label>
                    <select
                      value={win.deliveryStatus}
                      onChange={(e) => handleStatusChange(win.id, e.target.value)}
                      disabled={
                        updateDelivery.isPending || win.deliveryStatus === 'CONVERTED_TO_WALLET'
                      }
                      className="text-xs px-3.5 py-2.5 border border-slate-200 rounded-xl focus:outline-none focus:border-red-500 bg-white font-bold text-slate-700 disabled:opacity-50 shadow-xs"
                    >
                      {DELIVERY_STATUSES.map((s) => (
                        <option key={s.value} value={s.value}>
                          {s.label}
                        </option>
                      ))}
                    </select>

                    {win.deliveryStatus !== 'CONVERTED_TO_WALLET' && (
                      <button
                        onClick={() => handleOpenConversionModal(win)}
                        className="inline-flex items-center justify-center gap-1.5 px-3.5 py-2 bg-purple-50 hover:bg-purple-100 text-purple-700 border border-purple-200/80 rounded-xl text-xs font-bold transition shadow-xs"
                      >
                        <Wallet size={14} />
                        Convert Prize to Store Credits
                      </button>
                    )}
                  </div>
                </div>

                {/* Delivery Note */}
                {win.deliveryNote && (
                  <div className="pt-3 border-t border-slate-100 text-xs text-slate-500">
                    <strong className="text-slate-700">Delivery Note:</strong> {win.deliveryNote}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}

      {/* Conversion Modal */}
      {selectedWinForConversion && (
        <div className="fixed inset-0 z-[1001] bg-black/60 backdrop-blur-sm flex items-end sm:items-center justify-center p-0 sm:p-4">
          <div className="bg-white rounded-t-3xl sm:rounded-2xl max-w-md w-full p-6 pb-20 sm:pb-6 shadow-2xl space-y-4 animate-in slide-in-from-bottom sm:zoom-in-95 duration-200">
            {/* Mobile Sheet Bar */}
            <div className="w-12 h-1.5 bg-slate-200 rounded-full mx-auto sm:hidden mb-1" />

            <div className="flex items-center gap-3 text-purple-700">
              <div className="p-3 bg-purple-100 rounded-xl shrink-0">
                <Wallet size={24} />
              </div>
              <div>
                <h3 className="font-bold text-lg text-slate-900">Convert Prize to Store Credits</h3>
                <p className="text-xs text-slate-500">
                  Credit winner&apos;s non-withdrawable wallet balance
                </p>
              </div>
            </div>

            <div className="p-3.5 bg-purple-50 rounded-xl border border-purple-100 text-xs space-y-1.5 text-purple-900 font-medium">
              <p>
                Winner: <strong>{selectedWinForConversion.winner?.name}</strong>
              </p>
              <p>
                Prize Item: <strong>{selectedWinForConversion.item?.name}</strong>
              </p>
              <p>
                Item Market Value:{' '}
                <strong>₦{selectedWinForConversion.item?.value?.toLocaleString()}</strong>
              </p>
              <div className="text-[11px] text-purple-700 bg-purple-100/70 p-2.5 rounded-lg mt-2 font-normal leading-relaxed">
                💡 Credited funds are non-withdrawable cash and can only be used by the winner to
                purchase raffle tickets on the platform.
              </div>
            </div>

            <div className="space-y-3">
              <div>
                <label className="block text-xs font-bold text-slate-700 uppercase mb-1">
                  Credit Amount (₦)
                </label>
                <input
                  type="number"
                  value={conversionAmount}
                  onChange={(e) => setConversionAmount(Number(e.target.value))}
                  className="w-full px-3.5 py-2.5 border border-slate-200 rounded-xl text-sm focus:outline-none focus:border-purple-600 font-bold"
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 uppercase mb-1">
                  Admin Note / Reason
                </label>
                <textarea
                  value={conversionNote}
                  onChange={(e) => setConversionNote(e.target.value)}
                  rows={3}
                  className="w-full px-3.5 py-2.5 border border-slate-200 rounded-xl text-xs focus:outline-none focus:border-purple-600 resize-none"
                />
              </div>
            </div>

            <div className="flex items-center justify-end gap-2 pt-2">
              <button
                onClick={() => setSelectedWinForConversion(null)}
                className="px-4 py-2.5 text-xs font-bold text-slate-600 hover:bg-slate-100 rounded-xl transition"
              >
                Cancel
              </button>
              <button
                onClick={handleConfirmConversion}
                disabled={isConverting}
                className="px-5 py-2.5 text-xs font-bold text-white bg-purple-700 hover:bg-purple-800 rounded-xl shadow-md transition disabled:opacity-50"
              >
                {isConverting ? 'Converting...' : 'Confirm & Credit Wallet'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Empty State */}
      {!isLoading && filteredWins.length === 0 && (
        <div className="bg-white rounded-2xl border border-slate-200/80 p-12 text-center">
          <Trophy size={48} className="mx-auto text-slate-300 mb-3" />
          <h3 className="text-lg font-bold text-slate-700">No win records found</h3>
          <p className="text-sm text-slate-500 mt-1">
            Completed raffles with winning claims will appear here.
          </p>
        </div>
      )}

      {/* Pagination */}
      {pagination && pagination.totalPages > 1 && (
        <div className="flex justify-center items-center gap-2 pt-4">
          <button
            disabled={page <= 1}
            onClick={() => setPage((p) => p - 1)}
            className="px-4 py-2 text-xs font-bold bg-white border border-slate-200 rounded-xl disabled:opacity-50 hover:bg-slate-50 transition"
          >
            Previous
          </button>
          <span className="px-4 py-2 text-xs text-slate-600 font-semibold">
            Page {page} of {pagination.totalPages}
          </span>
          <button
            disabled={page >= pagination.totalPages}
            onClick={() => setPage((p) => p + 1)}
            className="px-4 py-2 text-xs font-bold bg-white border border-slate-200 rounded-xl disabled:opacity-50 hover:bg-slate-50 transition"
          >
            Next
          </button>
        </div>
      )}
    </div>
  );
}

'use client';

import { api } from '@/lib/api';
import { useAdminWins, useUpdateDeliveryStatus } from '@/lib/hooks/useAdmin';
import {
  ArrowUpRight,
  Check,
  CheckCircle,
  Clock,
  Copy,
  Filter,
  Mail,
  MapPin,
  Package,
  Phone,
  Search,
  Trophy,
  Truck,
  Wallet,
} from 'lucide-react';
import { useState } from 'react';
import toast from 'react-hot-toast';

const DELIVERY_STATUSES = [
  {
    value: 'PENDING',
    label: 'Pending',
    icon: Clock,
    color: 'bg-amber-50 text-amber-700 border-amber-200',
  },
  {
    value: 'PROCESSING',
    label: 'Processing',
    icon: Package,
    color: 'bg-blue-50 text-blue-700 border-blue-200',
  },
  {
    value: 'SHIPPED',
    label: 'Shipped',
    icon: Truck,
    color: 'bg-indigo-50 text-indigo-700 border-indigo-200',
  },
  {
    value: 'DELIVERED',
    label: 'Delivered',
    icon: CheckCircle,
    color: 'bg-emerald-50 text-emerald-700 border-emerald-200',
  },
  {
    value: 'CONVERTED_TO_WALLET',
    label: 'Converted to Credits',
    icon: Wallet,
    color: 'bg-purple-50 text-purple-700 border-purple-200',
  },
];

export default function AdminWinsPage() {
  const [filterStatus, setFilterStatus] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [page, setPage] = useState(1);
  const { data, isLoading, refetch } = useAdminWins({ page, deliveryStatus: filterStatus });
  const updateDelivery = useUpdateDeliveryStatus();

  const [selectedWinForConversion, setSelectedWinForConversion] = useState<any>(null);
  const [conversionAmount, setConversionAmount] = useState<number>(0);
  const [conversionNote, setConversionNote] = useState('');
  const [isConverting, setIsConverting] = useState(false);
  const [copiedField, setCopiedField] = useState<string | null>(null);

  const wins = data?.wins ?? [];
  const pagination = data?.pagination ?? null;

  const copyToClipboard = (text: string, label: string) => {
    if (!text) return;
    navigator.clipboard.writeText(text);
    setCopiedField(label);
    toast.success(`Copied ${label}`);
    setTimeout(() => setCopiedField(null), 2000);
  };

  const handleStatusChange = async (raffleId: string, newStatus: string) => {
    try {
      await updateDelivery.mutateAsync({ raffleId, deliveryStatus: newStatus });
      toast.success(`Delivery status updated to ${newStatus}`);
    } catch (err: any) {
      toast.error(err.message || 'Failed to update delivery status');
    }
  };

  const handleOpenConversionModal = (win: any) => {
    setSelectedWinForConversion(win);
    setConversionAmount(win.item?.value || 0);
    setConversionNote(
      `Unclaimed/Unavailable physical prize converted to non-withdrawable store credits for ${win.item?.name}.`,
    );
  };

  const handleConfirmConversion = async () => {
    if (!selectedWinForConversion) return;
    setIsConverting(true);
    try {
      const res = (await api.post(
        `/api/admin/wins/${selectedWinForConversion.id}/convert-to-wallet`,
        {
          amount: conversionAmount,
          note: conversionNote,
        },
      )) as any;

      if (res.success) {
        toast.success(res.message || 'Prize successfully converted to store credits!');
        setSelectedWinForConversion(null);
        refetch();
      } else {
        toast.error(res.message || 'Failed to convert prize');
      }
    } catch (err: any) {
      toast.error(err.message || 'Error converting prize to store credit');
    } finally {
      setIsConverting(false);
    }
  };

  // Filter by search query (winner name, email, item name)
  const filteredWins = wins.filter((w: any) => {
    if (!searchQuery.trim()) return true;
    const q = searchQuery.toLowerCase();
    return (
      w.item?.name?.toLowerCase().includes(q) ||
      w.winner?.name?.toLowerCase().includes(q) ||
      w.winner?.email?.toLowerCase().includes(q) ||
      w.winner?.userNumber?.toLowerCase().includes(q)
    );
  });

  // KPI Metrics calculation
  const totalWinsCount = wins.length;
  const pendingCount = wins.filter(
    (w: any) => w.deliveryStatus === 'PENDING' || w.deliveryStatus === 'PROCESSING',
  ).length;
  const deliveredCount = wins.filter((w: any) => w.deliveryStatus === 'DELIVERED').length;
  const convertedCount = wins.filter((w: any) => w.deliveryStatus === 'CONVERTED_TO_WALLET').length;

  return (
    <div className="space-y-6 pb-20 md:pb-0">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl sm:text-3xl font-bold text-slate-900 flex items-center gap-2.5">
            <div className="p-2 bg-amber-50 text-amber-600 rounded-xl">
              <Trophy size={24} />
            </div>
            Wins & Claims Management
          </h1>
          <p className="text-sm text-slate-500 mt-1">
            Track raffle prize claims, manage winner delivery fulfillment, and handle store credit
            conversions.
          </p>
        </div>
      </div>

      {/* KPI Summary Cards */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4">
        <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3">
          <div className="p-3 bg-amber-50 text-amber-600 rounded-xl shrink-0">
            <Trophy size={22} />
          </div>
          <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
              Total Winners
            </p>
            <p className="text-xl sm:text-2xl font-bold text-slate-900 mt-0.5">{totalWinsCount}</p>
          </div>
        </div>

        <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3">
          <div className="p-3 bg-blue-50 text-blue-600 rounded-xl shrink-0">
            <Clock size={22} />
          </div>
          <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
              Pending Delivery
            </p>
            <p className="text-xl sm:text-2xl font-bold text-blue-600 mt-0.5">{pendingCount}</p>
          </div>
        </div>

        <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3">
          <div className="p-3 bg-emerald-50 text-emerald-600 rounded-xl shrink-0">
            <CheckCircle size={22} />
          </div>
          <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
              Delivered
            </p>
            <p className="text-xl sm:text-2xl font-bold text-emerald-600 mt-0.5">
              {deliveredCount}
            </p>
          </div>
        </div>

        <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3">
          <div className="p-3 bg-purple-50 text-purple-600 rounded-xl shrink-0">
            <Wallet size={22} />
          </div>
          <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
              Converted Credits
            </p>
            <p className="text-xl sm:text-2xl font-bold text-purple-600 mt-0.5">{convertedCount}</p>
          </div>
        </div>
      </div>

      {/* Filter Toolbar */}
      <div className="bg-white p-4 rounded-2xl border border-slate-200/80 shadow-xs flex flex-col sm:flex-row gap-3">
        <div className="relative flex-1">
          <Search size={18} className="absolute left-3.5 top-3 text-slate-400" />
          <input
            type="text"
            placeholder="Search winner name, email, or item..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:outline-none focus:border-red-500 transition"
          />
        </div>

        <div className="flex items-center gap-2">
          <Filter size={18} className="text-slate-400 shrink-0" />
          <select
            value={filterStatus}
            onChange={(e) => {
              setFilterStatus(e.target.value);
              setPage(1);
            }}
            className="w-full sm:w-auto px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm font-semibold text-slate-700 focus:outline-none focus:border-red-500"
          >
            <option value="all">All Delivery Statuses</option>
            {DELIVERY_STATUSES.map((s) => (
              <option key={s.value} value={s.value}>
                {s.label}
              </option>
            ))}
          </select>
        </div>
      </div>

      {/* Loading */}
      {isLoading && (
        <div className="space-y-4">
          {[1, 2, 3].map((i) => (
            <div
              key={i}
              className="bg-white rounded-2xl p-6 border border-slate-100 shadow-xs animate-pulse space-y-4"
            >
              <div className="h-5 w-1/3 bg-slate-200 rounded" />
              <div className="h-4 w-2/3 bg-slate-200 rounded" />
              <div className="h-8 w-1/4 bg-slate-200 rounded" />
            </div>
          ))}
        </div>
      )}

      {/* Wins List */}
      {!isLoading && (
        <div className="space-y-4">
          {filteredWins.map((win: any) => {
            const currentStatus =
              DELIVERY_STATUSES.find((s) => s.value === win.deliveryStatus) || DELIVERY_STATUSES[0];
            const StatusIcon = currentStatus.icon;
            const imageUrl = win.item?.imageUrl?.startsWith('/uploads')
              ? `${process.env.NEXT_PUBLIC_API_URL || 'http://localhost:5000'}${win.item.imageUrl}`
              : win.item?.imageUrl;

            const winnerAddress = [win.winner?.address, win.winner?.city, win.winner?.state]
              .filter(Boolean)
              .join(', ');

            return (
              <div
                key={win.id}
                className="bg-white rounded-2xl border border-slate-200/80 p-5 shadow-xs hover:shadow-md transition space-y-4"
              >
                <div className="flex flex-col md:flex-row gap-5">
                  {/* Item Image */}
                  <div className="w-20 h-20 sm:w-24 sm:h-24 bg-slate-100 rounded-xl overflow-hidden shrink-0 border border-slate-100 flex items-center justify-center">
                    {imageUrl ? (
                      <img
                        src={imageUrl}
                        alt={win.item?.name}
                        className="w-full h-full object-cover"
                      />
                    ) : (
                      <span className="text-3xl">🏆</span>
                    )}
                  </div>

                  {/* Info & Winner Address */}
                  <div className="flex-1 min-w-0 space-y-3">
                    <div className="flex flex-wrap items-start justify-between gap-2">
                      <div>
                        <h3 className="font-bold text-slate-900 text-base sm:text-lg flex items-center gap-2">
                          {win.item?.name}
                          <span className="text-xs bg-red-50 text-red-600 px-2 py-0.5 rounded-full font-bold border border-red-100">
                            ₦{win.item?.value?.toLocaleString()}
                          </span>
                        </h3>
                      </div>
                      <span
                        className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold border ${currentStatus.color}`}
                      >
                        <StatusIcon size={14} />
                        {currentStatus.label}
                      </span>
                    </div>

                    {/* Winner Details Box */}
                    <div className="p-3.5 bg-slate-50 rounded-xl border border-slate-200/60 text-xs space-y-2">
                      <div className="flex items-center justify-between">
                        <p className="font-bold text-slate-800 text-sm">
                          Winner: <span className="text-red-600">{win.winner?.name}</span>{' '}
                          <span className="font-mono text-slate-400 text-[11px]">
                            ({win.winner?.userNumber})
                          </span>
                        </p>
                      </div>

                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 text-slate-600 pt-1">
                        {win.winner?.email && (
                          <div className="flex items-center justify-between bg-white px-2.5 py-1.5 rounded-lg border border-slate-200/60">
                            <span className="flex items-center gap-1.5 truncate">
                              <Mail size={13} className="text-slate-400 shrink-0" />
                              <span className="truncate">{win.winner.email}</span>
                            </span>
                            <button
                              onClick={() => copyToClipboard(win.winner.email, 'Email')}
                              className="text-slate-400 hover:text-slate-700 p-1"
                              title="Copy email"
                            >
                              {copiedField === 'Email' ? (
                                <Check size={13} className="text-emerald-600" />
                              ) : (
                                <Copy size={13} />
                              )}
                            </button>
                          </div>
                        )}

                        {win.winner?.phone && (
                          <div className="flex items-center justify-between bg-white px-2.5 py-1.5 rounded-lg border border-slate-200/60">
                            <span className="flex items-center gap-1.5 truncate">
                              <Phone size={13} className="text-slate-400 shrink-0" />
                              <span>{win.winner.phone}</span>
                            </span>
                            <button
                              onClick={() => copyToClipboard(win.winner.phone, 'Phone')}
                              className="text-slate-400 hover:text-slate-700 p-1"
                              title="Copy phone"
                            >
                              {copiedField === 'Phone' ? (
                                <Check size={13} className="text-emerald-600" />
                              ) : (
                                <Copy size={13} />
                              )}
                            </button>
                          </div>
                        )}
                      </div>

                      {winnerAddress ? (
                        <div className="pt-1 flex items-start gap-1.5 font-medium text-slate-700">
                          <MapPin size={14} className="text-red-500 shrink-0 mt-0.5" />
                          <span>
                            <strong>Shipping Address:</strong> {winnerAddress}
                          </span>
                        </div>
                      ) : (
                        <div className="pt-1 flex items-center gap-1.5 italic text-slate-400">
                          <MapPin size={13} className="text-slate-300" />
                          <span>Delivery address not yet set in winner profile</span>
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Action Box */}
                  <div className="flex flex-col gap-2.5 justify-center md:items-end shrink-0 pt-3 md:pt-0 border-t md:border-t-0 border-slate-100">
                    <label className="text-[11px] font-bold text-slate-400 uppercase tracking-wider">
                      Update Delivery Status
                    </label>
                    <select
                      value={win.deliveryStatus}
                      onChange={(e) => handleStatusChange(win.id, e.target.value)}
                      disabled={
                        updateDelivery.isPending || win.deliveryStatus === 'CONVERTED_TO_WALLET'
                      }
                      className="text-xs px-3.5 py-2.5 border border-slate-200 rounded-xl focus:outline-none focus:border-red-500 bg-white font-bold text-slate-700 disabled:opacity-50 shadow-xs"
                    >
                      {DELIVERY_STATUSES.map((s) => (
                        <option key={s.value} value={s.value}>
                          {s.label}
                        </option>
                      ))}
                    </select>

                    {win.deliveryStatus !== 'CONVERTED_TO_WALLET' && (
                      <button
                        onClick={() => handleOpenConversionModal(win)}
                        className="inline-flex items-center justify-center gap-1.5 px-3.5 py-2 bg-purple-50 hover:bg-purple-100 text-purple-700 border border-purple-200/80 rounded-xl text-xs font-bold transition shadow-xs"
                      >
                        <Wallet size={14} />
                        Convert Prize to Store Credits
                      </button>
                    )}
                  </div>
                </div>

                {/* Delivery Note */}
                {win.deliveryNote && (
                  <div className="pt-3 border-t border-slate-100 text-xs text-slate-500">
                    <strong className="text-slate-700">Delivery Note:</strong> {win.deliveryNote}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}

      {/* Conversion Modal */}
      {selectedWinForConversion && (
        <div className="fixed inset-0 z-[1001] bg-black/60 backdrop-blur-sm flex items-end sm:items-center justify-center p-0 sm:p-4">
          <div className="bg-white rounded-t-3xl sm:rounded-2xl max-w-md w-full p-6 pb-20 sm:pb-6 shadow-2xl space-y-4 animate-in slide-in-from-bottom sm:zoom-in-95 duration-200">
            {/* Mobile Sheet Bar */}
            <div className="w-12 h-1.5 bg-slate-200 rounded-full mx-auto sm:hidden mb-1" />

            <div className="flex items-center gap-3 text-purple-700">
              <div className="p-3 bg-purple-100 rounded-xl shrink-0">
                <Wallet size={24} />
              </div>
              <div>
                <h3 className="font-bold text-lg text-slate-900">Convert Prize to Store Credits</h3>
                <p className="text-xs text-slate-500">
                  Credit winner&apos;s non-withdrawable wallet balance
                </p>
              </div>
            </div>

            <div className="p-3.5 bg-purple-50 rounded-xl border border-purple-100 text-xs space-y-1.5 text-purple-900 font-medium">
              <p>
                Winner: <strong>{selectedWinForConversion.winner?.name}</strong>
              </p>
              <p>
                Prize Item: <strong>{selectedWinForConversion.item?.name}</strong>
              </p>
              <p>
                Item Market Value:{' '}
                <strong>₦{selectedWinForConversion.item?.value?.toLocaleString()}</strong>
              </p>
              <div className="text-[11px] text-purple-700 bg-purple-100/70 p-2.5 rounded-lg mt-2 font-normal leading-relaxed">
                💡 Credited funds are non-withdrawable cash and can only be used by the winner to
                purchase raffle tickets on the platform.
              </div>
            </div>

            <div className="space-y-3">
              <div>
                <label className="block text-xs font-bold text-slate-700 uppercase mb-1">
                  Credit Amount (₦)
                </label>
                <input
                  type="number"
                  value={conversionAmount}
                  onChange={(e) => setConversionAmount(Number(e.target.value))}
                  className="w-full px-3.5 py-2.5 border border-slate-200 rounded-xl text-sm focus:outline-none focus:border-purple-600 font-bold"
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 uppercase mb-1">
                  Admin Note / Reason
                </label>
                <textarea
                  value={conversionNote}
                  onChange={(e) => setConversionNote(e.target.value)}
                  rows={3}
                  className="w-full px-3.5 py-2.5 border border-slate-200 rounded-xl text-xs focus:outline-none focus:border-purple-600 resize-none"
                />
              </div>
            </div>

            <div className="flex items-center justify-end gap-2 pt-2">
              <button
                onClick={() => setSelectedWinForConversion(null)}
                className="px-4 py-2.5 text-xs font-bold text-slate-600 hover:bg-slate-100 rounded-xl transition"
              >
                Cancel
              </button>
              <button
                onClick={handleConfirmConversion}
                disabled={isConverting}
                className="px-5 py-2.5 text-xs font-bold text-white bg-purple-700 hover:bg-purple-800 rounded-xl shadow-md transition disabled:opacity-50"
              >
                {isConverting ? 'Converting...' : 'Confirm & Credit Wallet'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Empty State */}
      {!isLoading && filteredWins.length === 0 && (
        <div className="bg-white rounded-2xl border border-slate-200/80 p-12 text-center">
          <Trophy size={48} className="mx-auto text-slate-300 mb-3" />
          <h3 className="text-lg font-bold text-slate-700">No win records found</h3>
          <p className="text-sm text-slate-500 mt-1">
            Completed raffles with winning claims will appear here.
          </p>
        </div>
      )}

      {/* Pagination */}
      {pagination && pagination.totalPages > 1 && (
        <div className="flex justify-center items-center gap-2 pt-4">
          <button
            disabled={page <= 1}
            onClick={() => setPage((p) => p - 1)}
            className="px-4 py-2 text-xs font-bold bg-white border border-slate-200 rounded-xl disabled:opacity-50 hover:bg-slate-50 transition"
          >
            Previous
          </button>
          <span className="px-4 py-2 text-xs text-slate-600 font-semibold">
            Page {page} of {pagination.totalPages}
          </span>
          <button
            disabled={page >= pagination.totalPages}
            onClick={() => setPage((p) => p + 1)}
            className="px-4 py-2 text-xs font-bold bg-white border border-slate-200 rounded-xl disabled:opacity-50 hover:bg-slate-50 transition"
          >
            Next
          </button>
        </div>
      )}
    </div>
  );
}

'use client';

import { api } from '@/lib/api';
import { useAdminWins, useUpdateDeliveryStatus } from '@/lib/hooks/useAdmin';
import {
  ArrowUpRight,
  Check,
  CheckCircle,
  Clock,
  Copy,
  Filter,
  Mail,
  MapPin,
  Package,
  Phone,
  Search,
  Trophy,
  Truck,
  Wallet,
} from 'lucide-react';
import { useState } from 'react';
import toast from 'react-hot-toast';

const DELIVERY_STATUSES = [
  {
    value: 'PENDING',
    label: 'Pending',
    icon: Clock,
    color: 'bg-amber-50 text-amber-700 border-amber-200',
  },
  {
    value: 'PROCESSING',
    label: 'Processing',
    icon: Package,
    color: 'bg-blue-50 text-blue-700 border-blue-200',
  },
  {
    value: 'SHIPPED',
    label: 'Shipped',
    icon: Truck,
    color: 'bg-indigo-50 text-indigo-700 border-indigo-200',
  },
  {
    value: 'DELIVERED',
    label: 'Delivered',
    icon: CheckCircle,
    color: 'bg-emerald-50 text-emerald-700 border-emerald-200',
  },
  {
    value: 'CONVERTED_TO_WALLET',
    label: 'Converted to Credits',
    icon: Wallet,
    color: 'bg-purple-50 text-purple-700 border-purple-200',
  },
];

export default function AdminWinsPage() {
  const [filterStatus, setFilterStatus] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [page, setPage] = useState(1);
  const { data, isLoading, refetch } = useAdminWins({ page, deliveryStatus: filterStatus });
  const updateDelivery = useUpdateDeliveryStatus();

  const [selectedWinForConversion, setSelectedWinForConversion] = useState<any>(null);
  const [conversionAmount, setConversionAmount] = useState<number>(0);
  const [conversionNote, setConversionNote] = useState('');
  const [isConverting, setIsConverting] = useState(false);
  const [copiedField, setCopiedField] = useState<string | null>(null);

  const wins = data?.wins ?? [];
  const pagination = data?.pagination ?? null;

  const copyToClipboard = (text: string, label: string) => {
    if (!text) return;
    navigator.clipboard.writeText(text);
    setCopiedField(label);
    toast.success(`Copied ${label}`);
    setTimeout(() => setCopiedField(null), 2000);
  };

  const handleStatusChange = async (raffleId: string, newStatus: string) => {
    try {
      await updateDelivery.mutateAsync({ raffleId, deliveryStatus: newStatus });
      toast.success(`Delivery status updated to ${newStatus}`);
    } catch (err: any) {
      toast.error(err.message || 'Failed to update delivery status');
    }
  };

  const handleOpenConversionModal = (win: any) => {
    setSelectedWinForConversion(win);
    setConversionAmount(win.item?.value || 0);
    setConversionNote(
      `Unclaimed/Unavailable physical prize converted to non-withdrawable store credits for ${win.item?.name}.`,
    );
  };

  const handleConfirmConversion = async () => {
    if (!selectedWinForConversion) return;
    setIsConverting(true);
    try {
      const res = (await api.post(
        `/api/admin/wins/${selectedWinForConversion.id}/convert-to-wallet`,
        {
          amount: conversionAmount,
          note: conversionNote,
        },
      )) as any;

      if (res.success) {
        toast.success(res.message || 'Prize successfully converted to store credits!');
        setSelectedWinForConversion(null);
        refetch();
      } else {
        toast.error(res.message || 'Failed to convert prize');
      }
    } catch (err: any) {
      toast.error(err.message || 'Error converting prize to store credit');
    } finally {
      setIsConverting(false);
    }
  };

  // Filter by search query (winner name, email, item name)
  const filteredWins = wins.filter((w: any) => {
    if (!searchQuery.trim()) return true;
    const q = searchQuery.toLowerCase();
    return (
      w.item?.name?.toLowerCase().includes(q) ||
      w.winner?.name?.toLowerCase().includes(q) ||
      w.winner?.email?.toLowerCase().includes(q) ||
      w.winner?.userNumber?.toLowerCase().includes(q)
    );
  });

  // KPI Metrics calculation
  const totalWinsCount = wins.length;
  const pendingCount = wins.filter(
    (w: any) => w.deliveryStatus === 'PENDING' || w.deliveryStatus === 'PROCESSING',
  ).length;
  const deliveredCount = wins.filter((w: any) => w.deliveryStatus === 'DELIVERED').length;
  const convertedCount = wins.filter((w: any) => w.deliveryStatus === 'CONVERTED_TO_WALLET').length;

  return (
    <div className="space-y-6 pb-20 md:pb-0">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl sm:text-3xl font-bold text-slate-900 flex items-center gap-2.5">
            <div className="p-2 bg-amber-50 text-amber-600 rounded-xl">
              <Trophy size={24} />
            </div>
            Wins & Claims Management
          </h1>
          <p className="text-sm text-slate-500 mt-1">
            Track raffle prize claims, manage winner delivery fulfillment, and handle store credit
            conversions.
          </p>
        </div>
      </div>

      {/* KPI Summary Cards */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4">
        <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3">
          <div className="p-3 bg-amber-50 text-amber-600 rounded-xl shrink-0">
            <Trophy size={22} />
          </div>
          <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
              Total Winners
            </p>
            <p className="text-xl sm:text-2xl font-bold text-slate-900 mt-0.5">{totalWinsCount}</p>
          </div>
        </div>

        <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3">
          <div className="p-3 bg-blue-50 text-blue-600 rounded-xl shrink-0">
            <Clock size={22} />
          </div>
          <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
              Pending Delivery
            </p>
            <p className="text-xl sm:text-2xl font-bold text-blue-600 mt-0.5">{pendingCount}</p>
          </div>
        </div>

        <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3">
          <div className="p-3 bg-emerald-50 text-emerald-600 rounded-xl shrink-0">
            <CheckCircle size={22} />
          </div>
          <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
              Delivered
            </p>
            <p className="text-xl sm:text-2xl font-bold text-emerald-600 mt-0.5">
              {deliveredCount}
            </p>
          </div>
        </div>

        <div className="bg-white p-4 sm:p-5 rounded-2xl border border-slate-200/80 shadow-xs flex items-center gap-3">
          <div className="p-3 bg-purple-50 text-purple-600 rounded-xl shrink-0">
            <Wallet size={22} />
          </div>
          <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
              Converted Credits
            </p>
            <p className="text-xl sm:text-2xl font-bold text-purple-600 mt-0.5">{convertedCount}</p>
          </div>
        </div>
      </div>

      {/* Filter Toolbar */}
      <div className="bg-white p-4 rounded-2xl border border-slate-200/80 shadow-xs flex flex-col sm:flex-row gap-3">
        <div className="relative flex-1">
          <Search size={18} className="absolute left-3.5 top-3 text-slate-400" />
          <input
            type="text"
            placeholder="Search winner name, email, or item..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:outline-none focus:border-red-500 transition"
          />
        </div>

        <div className="flex items-center gap-2">
          <Filter size={18} className="text-slate-400 shrink-0" />
          <select
            value={filterStatus}
            onChange={(e) => {
              setFilterStatus(e.target.value);
              setPage(1);
            }}
            className="w-full sm:w-auto px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm font-semibold text-slate-700 focus:outline-none focus:border-red-500"
          >
            <option value="all">All Delivery Statuses</option>
            {DELIVERY_STATUSES.map((s) => (
              <option key={s.value} value={s.value}>
                {s.label}
              </option>
            ))}
          </select>
        </div>
      </div>

      {/* Loading */}
      {isLoading && (
        <div className="space-y-4">
          {[1, 2, 3].map((i) => (
            <div
              key={i}
              className="bg-white rounded-2xl p-6 border border-slate-100 shadow-xs animate-pulse space-y-4"
            >
              <div className="h-5 w-1/3 bg-slate-200 rounded" />
              <div className="h-4 w-2/3 bg-slate-200 rounded" />
              <div className="h-8 w-1/4 bg-slate-200 rounded" />
            </div>
          ))}
        </div>
      )}

      {/* Wins List */}
      {!isLoading && (
        <div className="space-y-4">
          {filteredWins.map((win: any) => {
            const currentStatus =
              DELIVERY_STATUSES.find((s) => s.value === win.deliveryStatus) || DELIVERY_STATUSES[0];
            const StatusIcon = currentStatus.icon;
            const imageUrl = win.item?.imageUrl?.startsWith('/uploads')
              ? `${process.env.NEXT_PUBLIC_API_URL || 'http://localhost:5000'}${win.item.imageUrl}`
              : win.item?.imageUrl;

            const winnerAddress = [win.winner?.address, win.winner?.city, win.winner?.state]
              .filter(Boolean)
              .join(', ');

            return (
              <div
                key={win.id}
                className="bg-white rounded-2xl border border-slate-200/80 p-5 shadow-xs hover:shadow-md transition space-y-4"
              >
                <div className="flex flex-col md:flex-row gap-5">
                  {/* Item Image */}
                  <div className="w-20 h-20 sm:w-24 sm:h-24 bg-slate-100 rounded-xl overflow-hidden shrink-0 border border-slate-100 flex items-center justify-center">
                    {imageUrl ? (
                      <img
                        src={imageUrl}
                        alt={win.item?.name}
                        className="w-full h-full object-cover"
                      />
                    ) : (
                      <span className="text-3xl">🏆</span>
                    )}
                  </div>

                  {/* Info & Winner Address */}
                  <div className="flex-1 min-w-0 space-y-3">
                    <div className="flex flex-wrap items-start justify-between gap-2">
                      <div>
                        <h3 className="font-bold text-slate-900 text-base sm:text-lg flex items-center gap-2">
                          {win.item?.name}
                          <span className="text-xs bg-red-50 text-red-600 px-2 py-0.5 rounded-full font-bold border border-red-100">
                            ₦{win.item?.value?.toLocaleString()}
                          </span>
                        </h3>
                      </div>
                      <span
                        className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold border ${currentStatus.color}`}
                      >
                        <StatusIcon size={14} />
                        {currentStatus.label}
                      </span>
                    </div>

                    {/* Winner Details Box */}
                    <div className="p-3.5 bg-slate-50 rounded-xl border border-slate-200/60 text-xs space-y-2">
                      <div className="flex items-center justify-between">
                        <p className="font-bold text-slate-800 text-sm">
                          Winner: <span className="text-red-600">{win.winner?.name}</span>{' '}
                          <span className="font-mono text-slate-400 text-[11px]">
                            ({win.winner?.userNumber})
                          </span>
                        </p>
                      </div>

                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 text-slate-600 pt-1">
                        {win.winner?.email && (
                          <div className="flex items-center justify-between bg-white px-2.5 py-1.5 rounded-lg border border-slate-200/60">
                            <span className="flex items-center gap-1.5 truncate">
                              <Mail size={13} className="text-slate-400 shrink-0" />
                              <span className="truncate">{win.winner.email}</span>
                            </span>
                            <button
                              onClick={() => copyToClipboard(win.winner.email, 'Email')}
                              className="text-slate-400 hover:text-slate-700 p-1"
                              title="Copy email"
                            >
                              {copiedField === 'Email' ? (
                                <Check size={13} className="text-emerald-600" />
                              ) : (
                                <Copy size={13} />
                              )}
                            </button>
                          </div>
                        )}

                        {win.winner?.phone && (
                          <div className="flex items-center justify-between bg-white px-2.5 py-1.5 rounded-lg border border-slate-200/60">
                            <span className="flex items-center gap-1.5 truncate">
                              <Phone size={13} className="text-slate-400 shrink-0" />
                              <span>{win.winner.phone}</span>
                            </span>
                            <button
                              onClick={() => copyToClipboard(win.winner.phone, 'Phone')}
                              className="text-slate-400 hover:text-slate-700 p-1"
                              title="Copy phone"
                            >
                              {copiedField === 'Phone' ? (
                                <Check size={13} className="text-emerald-600" />
                              ) : (
                                <Copy size={13} />
                              )}
                            </button>
                          </div>
                        )}
                      </div>

                      {winnerAddress ? (
                        <div className="pt-1 flex items-start gap-1.5 font-medium text-slate-700">
                          <MapPin size={14} className="text-red-500 shrink-0 mt-0.5" />
                          <span>
                            <strong>Shipping Address:</strong> {winnerAddress}
                          </span>
                        </div>
                      ) : (
                        <div className="pt-1 flex items-center gap-1.5 italic text-slate-400">
                          <MapPin size={13} className="text-slate-300" />
                          <span>Delivery address not yet set in winner profile</span>
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Action Box */}
                  <div className="flex flex-col gap-2.5 justify-center md:items-end shrink-0 pt-3 md:pt-0 border-t md:border-t-0 border-slate-100">
                    <label className="text-[11px] font-bold text-slate-400 uppercase tracking-wider">
                      Update Delivery Status
                    </label>
                    <select
                      value={win.deliveryStatus}
                      onChange={(e) => handleStatusChange(win.id, e.target.value)}
                      disabled={
                        updateDelivery.isPending || win.deliveryStatus === 'CONVERTED_TO_WALLET'
                      }
                      className="text-xs px-3.5 py-2.5 border border-slate-200 rounded-xl focus:outline-none focus:border-red-500 bg-white font-bold text-slate-700 disabled:opacity-50 shadow-xs"
                    >
                      {DELIVERY_STATUSES.map((s) => (
                        <option key={s.value} value={s.value}>
                          {s.label}
                        </option>
                      ))}
                    </select>

                    {win.deliveryStatus !== 'CONVERTED_TO_WALLET' && (
                      <button
                        onClick={() => handleOpenConversionModal(win)}
                        className="inline-flex items-center justify-center gap-1.5 px-3.5 py-2 bg-purple-50 hover:bg-purple-100 text-purple-700 border border-purple-200/80 rounded-xl text-xs font-bold transition shadow-xs"
                      >
                        <Wallet size={14} />
                        Convert Prize to Store Credits
                      </button>
                    )}
                  </div>
                </div>

                {/* Delivery Note */}
                {win.deliveryNote && (
                  <div className="pt-3 border-t border-slate-100 text-xs text-slate-500">
                    <strong className="text-slate-700">Delivery Note:</strong> {win.deliveryNote}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}

      {/* Conversion Modal */}
      {selectedWinForConversion && (
        <div className="fixed inset-0 z-[1001] bg-black/60 backdrop-blur-sm flex items-end sm:items-center justify-center p-0 sm:p-4">
          <div className="bg-white rounded-t-3xl sm:rounded-2xl max-w-md w-full p-6 pb-20 sm:pb-6 shadow-2xl space-y-4 animate-in slide-in-from-bottom sm:zoom-in-95 duration-200">
            {/* Mobile Sheet Bar */}
            <div className="w-12 h-1.5 bg-slate-200 rounded-full mx-auto sm:hidden mb-1" />

            <div className="flex items-center gap-3 text-purple-700">
              <div className="p-3 bg-purple-100 rounded-xl shrink-0">
                <Wallet size={24} />
              </div>
              <div>
                <h3 className="font-bold text-lg text-slate-900">Convert Prize to Store Credits</h3>
                <p className="text-xs text-slate-500">
                  Credit winner&apos;s non-withdrawable wallet balance
                </p>
              </div>
            </div>

            <div className="p-3.5 bg-purple-50 rounded-xl border border-purple-100 text-xs space-y-1.5 text-purple-900 font-medium">
              <p>
                Winner: <strong>{selectedWinForConversion.winner?.name}</strong>
              </p>
              <p>
                Prize Item: <strong>{selectedWinForConversion.item?.name}</strong>
              </p>
              <p>
                Item Market Value:{' '}
                <strong>₦{selectedWinForConversion.item?.value?.toLocaleString()}</strong>
              </p>
              <div className="text-[11px] text-purple-700 bg-purple-100/70 p-2.5 rounded-lg mt-2 font-normal leading-relaxed">
                💡 Credited funds are non-withdrawable cash and can only be used by the winner to
                purchase raffle tickets on the platform.
              </div>
            </div>

            <div className="space-y-3">
              <div>
                <label className="block text-xs font-bold text-slate-700 uppercase mb-1">
                  Credit Amount (₦)
                </label>
                <input
                  type="number"
                  value={conversionAmount}
                  onChange={(e) => setConversionAmount(Number(e.target.value))}
                  className="w-full px-3.5 py-2.5 border border-slate-200 rounded-xl text-sm focus:outline-none focus:border-purple-600 font-bold"
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 uppercase mb-1">
                  Admin Note / Reason
                </label>
                <textarea
                  value={conversionNote}
                  onChange={(e) => setConversionNote(e.target.value)}
                  rows={3}
                  className="w-full px-3.5 py-2.5 border border-slate-200 rounded-xl text-xs focus:outline-none focus:border-purple-600 resize-none"
                />
              </div>
            </div>

            <div className="flex items-center justify-end gap-2 pt-2">
              <button
                onClick={() => setSelectedWinForConversion(null)}
                className="px-4 py-2.5 text-xs font-bold text-slate-600 hover:bg-slate-100 rounded-xl transition"
              >
                Cancel
              </button>
              <button
                onClick={handleConfirmConversion}
                disabled={isConverting}
                className="px-5 py-2.5 text-xs font-bold text-white bg-purple-700 hover:bg-purple-800 rounded-xl shadow-md transition disabled:opacity-50"
              >
                {isConverting ? 'Converting...' : 'Confirm & Credit Wallet'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Empty State */}
      {!isLoading && filteredWins.length === 0 && (
        <div className="bg-white rounded-2xl border border-slate-200/80 p-12 text-center">
          <Trophy size={48} className="mx-auto text-slate-300 mb-3" />
          <h3 className="text-lg font-bold text-slate-700">No win records found</h3>
          <p className="text-sm text-slate-500 mt-1">
            Completed raffles with winning claims will appear here.
          </p>
        </div>
      )}

      {/* Pagination */}
      {pagination && pagination.totalPages > 1 && (
        <div className="flex justify-center items-center gap-2 pt-4">
          <button
            disabled={page <= 1}
            onClick={() => setPage((p) => p - 1)}
            className="px-4 py-2 text-xs font-bold bg-white border border-slate-200 rounded-xl disabled:opacity-50 hover:bg-slate-50 transition"
          >
            Previous
          </button>
          <span className="px-4 py-2 text-xs text-slate-600 font-semibold">
            Page {page} of {pagination.totalPages}
          </span>
          <button
            disabled={page >= pagination.totalPages}
            onClick={() => setPage((p) => p + 1)}
            className="px-4 py-2 text-xs font-bold bg-white border border-slate-200 rounded-xl disabled:opacity-50 hover:bg-slate-50 transition"
          >
            Next
          </button>
        </div>
      )}
    </div>
  );
}

'use client';

import EarningsStatCard from '@/components/earnings/EarningsStatCard';
import ReferralSection from '@/components/earnings/ReferralSection';
import TaskCard from '@/components/earnings/TaskCard';
import WatchAdModal from '@/components/earnings/WatchAdModal';
import WalletTransactionRow from '@/components/wallet/WalletTransactionRow';
import { useAuthStore } from '@/lib/authStore';
import { useCompleteTask, useCompletedTasks, useTasks } from '@/lib/hooks/useTasks';
import type { StatsRange } from '@/lib/hooks/useTasks';
import { useWalletTransactions } from '@/lib/hooks/useWallet';
import { Award, Calendar, CheckCircle, Lightbulb, Play, Share2, Users, Zap } from 'lucide-react';
import React, { useState } from 'react';
import toast from 'react-hot-toast';

export default function EarningsPage() {
  const { user } = useAuthStore();
  const { data: tasks = [], isLoading: tasksLoading } = useTasks();
  const [statsRange, setStatsRange] = useState<StatsRange>('today');
  const { data: completedData, isLoading: completedLoading } = useCompletedTasks(statsRange);
  const { data: txData } = useWalletTransactions();
  const completeTaskMutation = useCompleteTask();

  const [showWatchAd, setShowWatchAd] = useState(false);
  const [adTimer, setAdTimer] = useState(0);
  const [adTotalDuration, setAdTotalDuration] = useState(30);
  const [_completingTaskId, setCompletingTaskId] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'tasks' | 'earnings'>('tasks');
  const [clickedTaskIds, setClickedTaskIds] = useState<Set<string>>(new Set());

  const completedTaskIds = new Set((completedData?.completedTasks ?? []).map((ct) => ct.taskId));

  // NOTE: DAILY_LOGIN auto-complete is handled by the dashboard page, not here.

  const userStats = {
    totalPoints: user?.walletBalance ?? 1000,
    totalPointsEarned: completedData?.summary.totalPointsEarned ?? 0,
    tasksCompleted: completedData?.summary.totalTasksCompleted ?? 0,
    referrals: (completedData?.completedTasks ?? []).filter((ct) => ct.task.type === 'REFERRAL')
      .length,
  };

  const handleCompleteTask = async (task: any) => {
    if (task.type.startsWith('WATCH_AD')) {
      const duration = task.adDuration || 30;
      // Simulate watching an ad before completing
      setCompletingTaskId(task.id);
      setShowWatchAd(true);
      setAdTimer(duration);
      setAdTotalDuration(duration);
      const interval = setInterval(() => {
        setAdTimer((prev) => {
          if (prev <= 1) {
            clearInterval(interval);
            setShowWatchAd(false);
            // Now actually complete the task via API
            completeTaskMutation.mutate(task.id, {
              onError: (err: any) => toast.error(err.message || 'Failed to complete task'),
            });
            setCompletingTaskId(null);
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    } else {
      setCompletingTaskId(task.id);
      completeTaskMutation.mutate(task.id, {
        onSuccess: () => setCompletingTaskId(null),
        onError: (err: any) => {
          toast.error(err.message || 'Failed to complete task');
          setCompletingTaskId(null);
        },
      });
    }
  };
  const handleTaskAction = (task: any) => {
    if (task.type.startsWith('SOCIAL_')) {
      handleCompleteTask(task);
      return;
    }

    if (task.actionUrl && !clickedTaskIds.has(task.id)) {
      window.open(task.actionUrl, '_blank');
      setClickedTaskIds((prev) => new Set(prev).add(task.id));
      return;
    }
    handleCompleteTask(task);
  };

  const getButtonLabel = (task: any) => {
    // Social tasks: show completed state
    if (
      task.type.startsWith('SOCIAL_') &&
      (task.recentlyCompleted || completedTaskIds.has(task.id as string))
    ) {
      return 'Completed ✓';
    }
    // Daily login: show claimed state
    if (task.type === 'DAILY_LOGIN' && task.completedToday) {
      return 'Claimed ✓';
    }
    // Watch ad tasks: show completed state
    if (task.type.startsWith('WATCH_AD') && completedTaskIds.has(task.id as string)) {
      return 'Completed ✓';
    }
    if (task.actionUrl && clickedTaskIds.has(task.id)) return "I've Done This";
    switch (task.type) {
      case 'WATCH_AD_VIDEO':
        return 'Watch Video';
      case 'WATCH_AD_PICTURE':
        return 'View Picture';
      case 'WATCH_AD_BANNER':
        return 'View Banner';
      case 'SOCIAL_SHARE':
      case 'SOCIAL_LIKE':
      case 'SOCIAL_COMMENT':
      case 'SOCIAL_FOLLOW':
        return 'Share Now';
      case 'DAILY_LOGIN':
        return 'Claim';
      case 'SURVEY':
        return 'Start Survey';
      default:
        return task.actionUrl ? 'Go To Link' : 'Complete';
    }
  };

  // Group tasks by type for display
  const watchAdTasks = tasks.filter((t) => t.type.startsWith('WATCH_AD'));
  const socialTasks = tasks.filter((t) => t.type.startsWith('SOCIAL_'));

  // Deduplicate DAILY_LOGIN — only show one card
  const seenDailyLogin = { seen: false };
  const otherTasks = tasks.filter((t) => {
    if (t.type === 'DAILY_LOGIN') {
      if (seenDailyLogin.seen) return false;
      seenDailyLogin.seen = true;
      return true;
    }
    return t.type === 'SURVEY';
  });

  // Count today's completions per task for daily limit tracking
  const getCompletionsToday = (taskId: string) => {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    return (completedData?.completedTasks ?? []).filter(
      (ct) => ct.taskId === taskId && new Date(ct.completedAt) >= today,
    ).length;
  };

  if (tasksLoading || completedLoading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="flex flex-col items-center gap-3">
          <span className="w-8 h-8 border-3 border-red-600 border-t-transparent rounded-full animate-spin" />
          <p className="text-gray-600">Loading tasks...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 pb-20 md:pb-0">
      {/* Header */}
      <div className="bg-gradient-to-r from-red-600 to-red-700 text-white rounded-xl mb-6 md:mb-8">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 py-6 md:py-8">
          <h1 className="text-2xl md:text-3xl font-bold mb-2">Earn Naira Rewards</h1>
          <p className="text-red-100 text-sm md:text-base">
            Complete tasks and watch ads to earn free Naira added directly to your wallet
          </p>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 py-4 md:py-8">
        {/* Tabs Header */}
        <div className="flex space-x-8 border-b border-gray-200 mb-8">
          <button
            onClick={() => setActiveTab('tasks')}
            className={`pb-3 px-1 font-semibold text-base transition-colors border-b-2 ${activeTab === 'tasks' ? 'border-red-600 text-red-600' : 'border-transparent text-gray-500 hover:text-gray-800'}`}
          >
            Tasks
          </button>
          <button
            onClick={() => setActiveTab('earnings')}
            className={`pb-3 px-1 font-semibold text-base transition-colors border-b-2 ${activeTab === 'earnings' ? 'border-red-600 text-red-600' : 'border-transparent text-gray-500 hover:text-gray-800'}`}
          >
            My Earnings
          </button>
        </div>

        {activeTab === 'earnings' ? (
          <div className="space-y-8">
            {/* Time Range Filter */}
            <div className="flex items-center gap-2 flex-wrap">
              <Calendar size={16} className="text-gray-400" />
              {(
                [
                  ['today', 'Today'],
                  ['week', 'This Week'],
                  ['month', 'This Month'],
                  ['year', 'This Year'],
                  ['all', 'All Time'],
                ] as const
              ).map(([value, label]) => (
                <button
                  key={value}
                  onClick={() => setStatsRange(value)}
                  className={`px-4 py-1.5 rounded-full text-sm font-semibold transition-all ${
                    statsRange === value
                      ? 'bg-red-600 text-white shadow-sm'
                      : 'bg-white text-gray-600 border border-gray-200 hover:border-red-200 hover:text-red-600'
                  }`}
                >
                  {label}
                </button>
              ))}
            </div>

            {/* Stats */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 md:gap-6 mb-8">
              <EarningsStatCard
                title="Wallet Balance"
                value={`₦${userStats.totalPoints.toLocaleString()}`}
                subtitle="Available"
                icon={<Zap size={20} className="text-green-500" />}
                borderColor="border-green-500"
              />
              <EarningsStatCard
                title="Earned"
                value={`₦${userStats.totalPointsEarned.toLocaleString()}`}
                subtitle={
                  statsRange === 'all'
                    ? 'All time'
                    : statsRange === 'today'
                      ? 'Today'
                      : statsRange === 'week'
                        ? 'This week'
                        : statsRange === 'month'
                          ? 'This month'
                          : 'This year'
                }
                icon={<Award size={20} className="text-green-500" />}
                borderColor="border-green-500"
              />
              <EarningsStatCard
                title="Tasks Done"
                value={userStats.tasksCompleted}
                subtitle={
                  statsRange === 'all'
                    ? 'All time'
                    : statsRange === 'today'
                      ? 'Today'
                      : statsRange === 'week'
                        ? 'This week'
                        : statsRange === 'month'
                          ? 'This month'
                          : 'This year'
                }
                icon={<CheckCircle size={24} className="text-blue-500" />}
                borderColor="border-blue-500"
              />
              <EarningsStatCard
                title="Referrals"
                value={userStats.referrals}
                subtitle={
                  statsRange === 'all'
                    ? 'All time'
                    : statsRange === 'today'
                      ? 'Today'
                      : statsRange === 'week'
                        ? 'This week'
                        : statsRange === 'month'
                          ? 'This month'
                          : 'This year'
                }
                icon={<Users size={24} className="text-purple-500" />}
                borderColor="border-purple-500"
              />
            </div>

            {/* Conversion Info */}
            <div className="bg-blue-50 border-l-4 border-blue-500 rounded-lg p-6 mb-8">
              <p className="text-blue-900 font-semibold mb-2 flex items-center gap-2">
                <Lightbulb size={20} className="text-yellow-500" /> How It Works
              </p>
              <p className="text-blue-800 text-sm">
                Earn Naira rewards directly into your wallet by watching ads, completing tasks, and
                referring friends. Use your wallet balance to enter any raffle draw!
              </p>
            </div>

            {/* Wallet Transactions History */}
            <div className="bg-white rounded-2xl border border-gray-200 p-6 shadow-xs">
              <h3 className="font-bold text-gray-900 text-lg mb-4">Wallet Transactions</h3>
              {txData?.transactions && txData.transactions.length > 0 ? (
                <div className="overflow-x-auto">
                  <table className="w-full">
                    <thead className="bg-gray-50 border-b border-gray-200">
                      <tr>
                        <th className="px-4 py-3 text-left text-xs font-bold text-gray-600 uppercase">
                          Type
                        </th>
                        <th className="px-4 py-3 text-left text-xs font-bold text-gray-600 uppercase">
                          Description
                        </th>
                        <th className="px-4 py-3 text-left text-xs font-bold text-gray-600 uppercase">
                          Date
                        </th>
                        <th className="px-4 py-3 text-left text-xs font-bold text-gray-600 uppercase">
                          Ref
                        </th>
                        <th className="px-4 py-3 text-right text-xs font-bold text-gray-600 uppercase">
                          Amount
                        </th>
                        <th className="px-4 py-3 text-center text-xs font-bold text-gray-600 uppercase">
                          Status
                        </th>
                      </tr>
                    </thead>
                    <tbody>
                      {txData.transactions.map((tx) => {
                        const date = new Date(tx.createdAt);
                        const isMinus = tx.type === 'WITHDRAWAL' || tx.type === 'TICKET_PURCHASE';
                        const mapType = (t: string) => {
                          if (t === 'TICKET_PURCHASE') return 'purchase';
                          if (t === 'TASK_REWARD' || t === 'RAFFLE_WIN') return 'reward';
                          if (t === 'WITHDRAWAL') return 'withdrawal';
                          return 'deposit';
                        };
                        return (
                          <WalletTransactionRow
                            key={tx.id}
                            transaction={{
                              id: tx.id,
                              type: mapType(tx.type) as any,
                              rawType: tx.type,
                              description: tx.description || `${tx.type} transaction`,
                              amount: isMinus ? -tx.amount : tx.amount,
                              date: date.toISOString().split('T')[0],
                              time: date.toTimeString().slice(0, 5),
                              status: tx.status === 'COMPLETED' ? 'completed' : 'pending',
                              reference: tx.reference || `TXN-${tx.id.slice(0, 8)}`,
                            }}
                          />
                        );
                      })}
                    </tbody>
                  </table>
                </div>
              ) : (
                <div className="text-center py-8 bg-gray-50 rounded-xl border border-dashed border-gray-200">
                  <p className="text-gray-700 font-bold text-sm">No transactions recorded yet</p>
                  <p className="text-gray-500 text-xs mt-1">
                    Your wallet activity will show up here
                  </p>
                </div>
              )}
            </div>
          </div>
        ) : (
          <div className="space-y-8">
            {/* Watch Ads */}
            {watchAdTasks.length > 0 && (
              <div>
                <h2 className="text-2xl font-bold text-gray-900 mb-4 flex items-center gap-2">
                  <Play size={24} className="text-blue-500" /> Watch & Earn
                </h2>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                  {watchAdTasks.map((task) => (
                    <TaskCard
                      key={task.id}
                      task={{
                        id: task.id as any,
                        type: task.type.toLowerCase(),
                        title: task.title,
                        description: task.description,
                        points: task.points,
                        time: task.adDuration ? `${task.adDuration}s` : '30s',
                        actionUrl: task.actionUrl,
                        platform: task.platform,
                      }}
                      isCompleted={completedTaskIds.has(task.id as string) || !!task.completedToday}
                      isClickedUrl={clickedTaskIds.has(task.id as string)}
                      onComplete={() => handleTaskAction(task)}
                      buttonLabel={getButtonLabel(task)}
                      completionsToday={getCompletionsToday(task.id)}
                      dailyLimit={task.dailyLimit}
                    />
                  ))}
                </div>
              </div>
            )}

            {/* Social Share */}
            {socialTasks.length > 0 && (
