    if (task.actionUrl && clickedTaskIds.has(task.id)) return "I've Done This";
    switch (task.type) {
      case 'WATCH_AD_VIDEO':
        return 'Watch Video';
      case 'WATCH_AD_PICTURE':
        return 'View Picture';
      case 'WATCH_AD_BANNER':
        return 'View Banner';
      case 'SOCIAL_SHARE':
      case 'SOCIAL_LIKE':
      case 'SOCIAL_COMMENT':
      case 'SOCIAL_FOLLOW':
        return 'Share Now';
      case 'DAILY_LOGIN':
        return 'Claim';
      case 'SURVEY':
        return 'Start Survey';
      default:
        return task.actionUrl ? 'Go To Link' : 'Complete';
