                </h2>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                  {watchAdTasks.map((task) => (
                    <TaskCard
                      key={task.id}
                      task={{
                        id: task.id as any,
                        type: task.type.toLowerCase(),
                        title: task.title,
                        description: task.description,
                        points: task.points,
