// POST /api/auth/login
export const login = async (req: Request, res: Response) => {
  try {
    const { email, password } = req.body;

    const user = await prisma.user.findUnique({ where: { email } });
    if (!user) {
      res.status(401).json({
        success: false,
        message: 'Invalid email or password.',
      });
      return;
    }

    // Check if both email and WhatsApp are verified
    if (!user.emailVerified || !user.whatsappVerified) {
      res.status(403).json({
        success: false,
        message: 'Please complete verification (email & WhatsApp) before logging in.',
        needsVerification: true,
        userId: user.id,
        emailVerified: user.emailVerified,
        whatsappVerified: user.whatsappVerified,
      });
      return;
    }

    // Check if account is suspended
    if (user.status === 'SUSPENDED') {
      res.status(403).json({
        success: false,
        message: 'Your account has been suspended. Please contact support.',
      });
      return;
    }

    // Verify password
    const isPasswordValid = await bcrypt.compare(password, user.password);
    if (!isPasswordValid) {
      res.status(401).json({
        success: false,
        message: 'Invalid email or password.',
      });
      return;
    }

    // Check if 2FA is enabled
    if (user.twoFactorEnabled && user.twoFactorMethod) {
      // Generate a short-lived temp token for the 2FA verification step
      const tempToken = generateTempToken(user.id, user.twoFactorMethod);

      // For EMAIL method, send an OTP now
      if (user.twoFactorMethod === 'EMAIL') {
        const { code, expiry } = await generateAndSend2FAEmailOTP(user.email, user.name);
        await prisma.user.update({
          where: { id: user.id },
          data: {
            emailVerificationCode: code,
            emailCodeExpiry: expiry,
          },
        });
      }

      res.status(200).json({
        success: true,
        message: 'Two-factor authentication required.',
        data: {
          requires2FA: true,
          tempToken,
          method: user.twoFactorMethod,
        },
      });
      return;
    }

    // No 2FA — generate tokens directly
    const accessToken = generateAccessToken(user.id, user.role);
    const refreshToken = generateRefreshToken(user.id, user.role);

    // Store refresh token in database
    await prisma.user.update({
      where: { id: user.id },
      data: { refreshToken },
    });

    res.status(200).json({
      success: true,
      message: 'Login successful.',
      data: {
        accessToken,
        refreshToken,
        user: {
          id: user.id,
          userNumber: user.userNumber,
          email: user.email,
          name: user.name,
          phone: user.phone,
          walletBalance: user.walletBalance,
          rafflePoints: user.rafflePoints,
          role: user.role,
        },
      },
    });
  } catch (error) {
    console.error('[Auth] Login error:', error);
    res.status(500).json({
      success: false,
      message: 'Login failed. Please try again.',
    });
  }
};

// POST /api/auth/refresh-token
export const refreshAccessToken = async (req: Request, res: Response) => {
  try {
    const { refreshToken } = req.body;

    if (!refreshToken) {
      res.status(400).json({
        success: false,
        message: 'Refresh token is required.',
      });
      return;
    }

    const decoded = verifyRefreshToken(refreshToken);

    const user = await prisma.user.findUnique({
      where: { id: decoded.userId },
    });

    if (!user || user.refreshToken !== refreshToken) {
      res.status(401).json({
        success: false,
        message: 'Invalid refresh token.',
      });
      return;
    }

    const newAccessToken = generateAccessToken(user.id, user.role);
    const newRefreshToken = generateRefreshToken(user.id, user.role);

    await prisma.user.update({
      where: { id: user.id },
      data: { refreshToken: newRefreshToken },
    });

    res.status(200).json({
      success: true,
      data: {
        accessToken: newAccessToken,
        refreshToken: newRefreshToken,
      },
    });
  } catch {
    res.status(401).json({
      success: false,
      message: 'Invalid or expired refresh token.',
    });
  }
};

