import bcrypt from 'bcryptjs';
import type { Request, Response } from 'express';
import { prisma } from '../config/database';
import {
  sendEmailOTP,
  sendPasswordResetEmail,
  sendVerificationEmail,
  sendWelcomeEmail,
} from '../services/brevo';
import { sendSMSOTP, sendWhatsAppOTP } from '../services/infobip';
import {
  generateAccessToken,
  generateOTPCode,
  generateRefreshToken,
  generateResetToken,
  generateTempToken,
  generateVerificationToken,
  verifyRefreshToken,
  verifyTempToken,
} from '../services/jwt';
import {
  generateAndSend2FAEmailOTP,
  generateQRCodeURL,
  generateSecret,
  verifyTOTPToken,
} from '../services/twoFactor';
import { logTransaction } from '../utils/transactions';

// Generate unique User Number: RAF-XXXXXX
const generateUserNumber = (): string => {
  const randomNum = Math.floor(100000 + Math.random() * 900000);
  return `RAF-${randomNum}`;
};

// OTP expiry: 10 minutes
const OTP_EXPIRY_MS = 10 * 60 * 1000;

// POST /api/auth/register
export const register = async (req: Request, res: Response) => {
  try {
    const { name, email, password, phone, referralCode } = req.body;

    if (!phone) {
      res.status(400).json({
        success: false,
        message: 'WhatsApp number is required.',
      });
      return;
    }

    // Check if email already exists
    const existingUser = await prisma.user.findUnique({
      where: { email },
      select: { id: true, email: true },
    });
    if (existingUser) {
      res.status(400).json({
        success: false,
        message: 'An account with this email already exists.',
      });
      return;
    }

    // Hash password
    const salt = await bcrypt.genSalt(10);
    const hashedPassword = await bcrypt.hash(password, salt);

    // Generate unique User Number
    let userNumber = generateUserNumber();
    let numberExists = await prisma.user.findUnique({
      where: { userNumber },
      select: { id: true },
    });
    while (numberExists) {
      userNumber = generateUserNumber();
      numberExists = await prisma.user.findUnique({
        where: { userNumber },
        select: { id: true },
      });
    }

    // Generate OTP codes for both channels
    const emailCode = generateOTPCode();
    const whatsappCode = generateOTPCode();
    const codeExpiry = new Date(Date.now() + OTP_EXPIRY_MS);

    // Fetch dynamic signup bonus & referral bonus settings configured by admin
    const [signupSetting, referralSetting] = await Promise.all([
      (
        prisma as unknown as {
          setting: { findUnique: (args: { where: { key: string } }) => Promise<{ value: string } | null> };
        }
      ).setting.findUnique({ where: { key: 'signup_bonus' } }),
      (
        prisma as unknown as {
          setting: { findUnique: (args: { where: { key: string } }) => Promise<{ value: string } | null> };
        }
      ).setting.findUnique({ where: { key: 'referral_bonus' } }),
    ]);

    const signupBonus = signupSetting ? Number.parseFloat(signupSetting.value) || 1000 : 1000;
    const referralBonus = referralSetting ? Number.parseFloat(referralSetting.value) || 500 : 500;

    // Handle referral
    let referredBy: string | null = null;
    let referrerUser: { id: string; userNumber: string; name: string } | null = null;
    if (referralCode) {
      const referrer = await prisma.user.findUnique({
        where: { userNumber: referralCode },
        select: { id: true, userNumber: true, name: true },
      });
      if (referrer) {
        referredBy = referrer.userNumber;
        referrerUser = referrer;
      }
    }

    // Create user with dynamic Sign-up Bonus
    const user = await prisma.user.create({
      data: {
        userNumber,
        email,
        password: hashedPassword,
        name,
        phone: phone || null,
        referredBy,
        walletBalance: signupBonus,
        emailVerified: false,
        whatsappVerified: false,
        emailVerificationCode: emailCode,
        emailCodeExpiry: codeExpiry,
        whatsappVerificationCode: whatsappCode,
        whatsappCodeExpiry: codeExpiry,
      },
    });

    // Log transaction for Sign-up Bonus
    if (signupBonus > 0) {
      await logTransaction({
        userId: user.id,
        type: 'TASK_REWARD',
        amount: signupBonus,
        status: 'COMPLETED',
        description: `Welcome Sign-up Bonus: ₦${signupBonus.toLocaleString()} credited to your wallet.`,
      });
    }

    // Credit referral bonus to referrer if applicable
    if (referrerUser && referralBonus > 0) {
      await prisma.user.update({
        where: { id: referrerUser.id },
        data: {
          walletBalance: { increment: referralBonus },
        },
      });
      await logTransaction({
        userId: referrerUser.id,
        type: 'TASK_REWARD',
        amount: referralBonus,
        status: 'COMPLETED',
        description: `Referral Bonus: ₦${referralBonus.toLocaleString()} credited for inviting ${user.name || user.userNumber}.`,
      });
    }

    // Send OTPs via both channels
    await Promise.all([sendEmailOTP(email, name, emailCode), sendWhatsAppOTP(phone, whatsappCode)]);

    res.status(201).json({
      success: true,
      message: 'Account created! Please verify your email and WhatsApp number.',
      data: {
        userId: user.id,
        userNumber: user.userNumber,
        email: user.email,
        name: user.name,
      },
    });
  } catch (error) {
    console.error('[Auth] Register error:', error);
    res.status(500).json({
      success: false,
      message: 'Failed to create account. Please try again.',
    });
  }
};

// POST /api/auth/verify-email-otp
export const verifyEmailOTP = async (req: Request, res: Response) => {
  try {
    const { userId, code } = req.body;

    if (!userId || !code) {
      res.status(400).json({
        success: false,
        message: 'User ID and verification code are required.',
      });
      return;
    }

    const user = await prisma.user.findUnique({ where: { id: userId } });

    if (!user) {
      res.status(404).json({ success: false, message: 'User not found.' });
      return;
    }

    if (user.emailVerified) {
      res.status(400).json({
        success: false,
        message: 'Email is already verified.',
        alreadyVerified: true,
      });
      return;
    }

    if (!user.emailVerificationCode || user.emailVerificationCode !== code) {
      res.status(400).json({
        success: false,
        message: 'Invalid verification code.',
      });
      return;
    }

    if (user.emailCodeExpiry && user.emailCodeExpiry < new Date()) {
      res.status(400).json({
        success: false,
        message: 'Verification code has expired. Please request a new one.',
      });
      return;
    }

    // Mark email as verified
    await prisma.user.update({
      where: { id: user.id },
      data: {
        emailVerified: true,
        emailVerificationCode: null,
        emailCodeExpiry: null,
      },
    });

    // Check if both channels are now verified
    const bothVerified = user.whatsappVerified; // email is now true
    if (bothVerified) {
      await handleFullVerification(user);
    }

    res.status(200).json({
      success: true,
      message: 'Email verified successfully!',
      data: { bothVerified },
    });
  } catch (error) {
    console.error('[Auth] Verify email OTP error:', error);
    res.status(500).json({
      success: false,
      message: 'Failed to verify email.',
    });
  }
};

