// Helper: handle actions after both channels are verified
async function handleFullVerification(user: VerificationUser) {
  // Award referral bonus if applicable
  if (user.referredBy) {
    const referrer = await prisma.user.findUnique({
      where: { userNumber: user.referredBy },
    });
    if (referrer) {
      await prisma.user.update({
        where: { id: referrer.id },
        data: { walletBalance: { increment: 500 } },
      });

      await logTransaction({
        userId: referrer.id,
        type: 'TASK_REWARD',
        amount: 500,
        status: 'COMPLETED',
        description: `Referral bonus: ₦500 for ${user.name} (${user.userNumber}) completing verification.`,
      });
    }
  }

  // Send welcome email
  await sendWelcomeEmail(user.email, user.name);
}

// Legacy: POST /api/auth/verify-email (keep for backward compatibility)
export const verifyEmail = async (req: Request, res: Response) => {
  try {
    const { token } = req.body;

    if (!token) {
      res.status(400).json({
        success: false,
        message: 'Verification token is required.',
      });
      return;
    }

    const user = await prisma.user.findUnique({
      where: { verificationToken: token },
    });

    if (!user) {
      res.status(400).json({
        success: false,
        message: 'Invalid verification token.',
      });
      return;
    }

    if (user.emailVerified) {
      res.status(400).json({
        success: false,
        message: 'Email is already verified.',
      });
      return;
    }

    if (user.verificationTokenExpiry && user.verificationTokenExpiry < new Date()) {
      res.status(400).json({
        success: false,
        message: 'Verification token has expired. Please request a new one.',
      });
      return;
    }

    await prisma.user.update({
      where: { id: user.id },
      data: {
        emailVerified: true,
        verificationToken: null,
        verificationTokenExpiry: null,
      },
    });

    if (user.whatsappVerified) {
      await handleFullVerification(user);
    }

    res.status(200).json({
      success: true,
      message: 'Email verified successfully! You can now log in.',
    });
  } catch (error) {
    console.error('[Auth] Verify email error:', error);
    res.status(500).json({
      success: false,
      message: 'Failed to verify email. Please try again.',
    });
  }
};

// POST /api/auth/resend-verification (legacy)
export const resendVerification = async (req: Request, res: Response) => {
  try {
