function getEndsIn(raffleDate: string): string {
  const now = new Date();
  const end = new Date(raffleDate);
  const diff = end.getTime() - now.getTime();
  if (diff <= 0) return 'Ended';
  const days = Math.ceil(diff / (1000 * 60 * 60 * 24));
  if (days === 1) return '1 day';
  return `${days} days`;
}

