'use client';

import { resolveImageUrl } from '@/lib/imageUrl';
import { Clock, Ticket, Users } from 'lucide-react';

interface RaffleItem {
  id: string | number;
  name: string;
  image: string;
  ticketPrice: number;
  ticketsSold: number;
  ticketsTotal: number;
  status: 'active' | 'completed';
  endsIn: string;
}

interface RaffleCardProps {
  item: RaffleItem;
  isAuthenticated: boolean;
  onViewDetails?: (item: RaffleItem) => void;
}

export default function RaffleCard({ item, isAuthenticated, onViewDetails }: RaffleCardProps) {
  const progressPercent = Math.min(100, Math.round((item.ticketsSold / item.ticketsTotal) * 100));
  const imageUrl = resolveImageUrl(item.image);
  const ticketsRemaining = item.ticketsTotal - item.ticketsSold;

  const handleClick = () => {
    if (onViewDetails) onViewDetails(item);
  };

  return (
    <div
      className="group bg-white rounded-2xl border border-gray-100 hover:border-gray-200 shadow-sm hover:shadow-lg transition-all duration-300 overflow-hidden hover:-translate-y-0.5 cursor-pointer"
      onClick={handleClick}
    >
      {/* Image */}
      <div className="relative h-44 sm:h-48 bg-gray-50 overflow-hidden">
        {imageUrl ? (
          <img
            src={imageUrl}
            alt={item.name}
            className="w-full h-full object-cover group-hover:scale-[1.03] transition-transform duration-500"
          />
        ) : (
          <div className="flex items-center justify-center h-full text-5xl">
            {item.image || '📦'}
          </div>
        )}

        {/* Status badge */}
        <div
          className={`absolute top-3 left-3 flex items-center gap-1.5 px-2.5 py-1 text-xs font-bold rounded-full backdrop-blur-sm ${
            item.status === 'active' ? 'bg-emerald-500 text-white' : 'bg-gray-700/80 text-white'
          }`}
        >
          {item.status === 'active' && (
            <span className="w-1.5 h-1.5 bg-white rounded-full animate-pulse" />
          )}
          {item.status === 'active' ? 'LIVE' : 'ENDED'}
        </div>

        {/* Countdown */}
        {item.status === 'active' && (
          <div className="absolute top-3 right-3 flex items-center gap-1 px-2.5 py-1 bg-white text-gray-700 text-xs font-semibold rounded-full shadow-sm">
            <Clock size={11} className="text-[#C0000C]" />
            {item.endsIn}
          </div>
        )}

        {/* Price tag overlay at bottom */}
        <div className="absolute bottom-0 left-0 right-0 px-3 py-2 bg-gradient-to-t from-black/60 to-transparent flex items-end justify-between">
          <span className="text-white font-black text-base">
            ₦{item.ticketPrice.toLocaleString()}
            <span className="text-white/70 font-normal text-xs ml-1">/ticket</span>
          </span>
        </div>
      </div>

      {/* Content */}
      <div className="p-4">
        <h3 className="text-sm font-bold text-gray-900 mb-3 truncate">{item.name}</h3>

        {/* Progress */}
        <div className="mb-4">
          <div className="flex justify-between items-center mb-1.5 text-xs text-gray-500">
            <span className="flex items-center gap-1">
              <Users size={11} />
              {item.ticketsSold.toLocaleString()} sold
            </span>
            <span className="font-semibold text-gray-900">{progressPercent}%</span>
          </div>
          <div className="w-full bg-gray-100 rounded-full h-1.5 overflow-hidden">
            <div
              className="h-full rounded-full bg-[#C0000C] transition-all duration-700"
              style={{ width: `${progressPercent}%` }}
            />
          </div>
          <div className="mt-1.5 flex items-center gap-1 text-xs text-gray-400">
            <Ticket size={10} />
            {ticketsRemaining.toLocaleString()} ticket{ticketsRemaining !== 1 ? 's' : ''} left
          </div>
        </div>

        {/* CTA */}
        <button
          className="w-full py-2.5 text-sm font-bold text-[#C0000C] border border-[#C0000C] rounded-xl hover:bg-[#C0000C] hover:text-white transition-colors active:scale-[0.98]"
          onClick={(e) => {
            e.stopPropagation();
            handleClick();
          }}
        >
          View Details
        </button>
      </div>
    </div>
  );
}

'use client';

import HowItWorksModal from '@/components/landing/HowItWorksModal';
import TermsModal from '@/components/terms/TermsModal';
import { useAuthStore } from '@/lib/authStore';
import {
  Award,
  CreditCard,
  FileText,
  HelpCircle,
  Home,
  Image as ImageIcon,
  LayoutDashboard,
  LogOut,
  Menu,
  Receipt,
  Settings,
  Ticket,
  Trophy,
  User,
  Users as UsersIcon,
  Wallet,
  X,
  Zap,
} from 'lucide-react';
import Link from 'next/link';
import { usePathname, useRouter } from 'next/navigation';
import { useState } from 'react';

// Pages where the bottom nav should be completely hidden
const HIDDEN_PATHS = ['/login', '/register', '/forgot-password'];

export default function AppBottomNav() {
  const pathname = usePathname();
  const router = useRouter();
  const { user, isAuthenticated, logout } = useAuthStore();
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [termsOpen, setTermsOpen] = useState(false);
  const [howItWorksOpen, setHowItWorksOpen] = useState(false);

  const isAdmin = isAuthenticated && (user as any)?.role === 'ADMIN';
  const isHidden = HIDDEN_PATHS.some((p) => pathname?.startsWith(p));
  const isAdminPage = pathname?.startsWith('/admin') || isAdmin;
  const _isDashboardPage = pathname?.startsWith('/dashboard');

  const isActive = (path: string) => {
    if (path === '/dashboard' || path === '/admin' || path === '/') return pathname === path;
    return pathname === path || pathname?.startsWith(`${path}/`);
  };

  const tabClass = (active: boolean) =>
    `flex flex-col items-center justify-center flex-1 h-full gap-0.5 transition-colors ${
      active ? 'text-[#C0000C]' : 'text-gray-500 hover:text-gray-800'
    }`;

  const labelClass = (active: boolean) =>
    `text-[10px] font-bold ${active ? 'text-[#C0000C]' : 'text-gray-500'}`;

  if (isHidden) return null;

  // ─── UNAUTHENTICATED ────────────────────────────────────────
  if (!isAuthenticated && !isAdminPage) {
    return (
      <>
        <nav className="md:hidden fixed bottom-0 inset-x-0 bg-white border-t border-gray-100 shadow-2xl h-16 z-[60]">
          <div className="flex h-full max-w-xl mx-auto">
            <Link href="/" className={tabClass(isActive('/'))}>
              <Home size={22} strokeWidth={isActive('/') ? 2.5 : 1.8} />
              <span className={labelClass(isActive('/'))}>Home</span>
            </Link>
            <Link href="/login" className={tabClass(isActive('/login'))}>
              <User size={22} strokeWidth={isActive('/login') ? 2.5 : 1.8} />
              <span className={labelClass(isActive('/login'))}>Sign In</span>
            </Link>
          </div>
        </nav>
        <div className="h-16 md:hidden" />
      </>
    );
  }

  // ─── ADMIN ──────────────────────────────────────────────────
  if (isAdminPage) {
    const adminTabs = [
      { href: '/admin', icon: LayoutDashboard, label: 'Overview', exact: true },
      { href: '/admin/raffles', icon: Ticket, label: 'Raffles' },
      { href: '/admin/wins', icon: Trophy, label: 'Wins' },
    ];

    return (
      <>
        <nav className="md:hidden fixed bottom-0 inset-x-0 bg-white border-t border-gray-100 shadow-2xl h-16 z-[60]">
          <div className="flex h-full max-w-xl mx-auto">
            {adminTabs.map((tab) => {
              const active = tab.exact ? pathname === tab.href : isActive(tab.href);
              return (
                <Link key={tab.href} href={tab.href} className={tabClass(active)}>
                  <tab.icon size={22} strokeWidth={active ? 2.5 : 1.8} />
                  <span className={labelClass(active)}>{tab.label}</span>
                </Link>
              );
            })}

            {/* More drawer */}
            <button onClick={() => setDrawerOpen(true)} className={tabClass(drawerOpen)}>
              <Menu size={22} strokeWidth={drawerOpen ? 2.5 : 1.8} />
              <span className={labelClass(drawerOpen)}>More</span>
            </button>
          </div>
        </nav>

        {/* Admin More Drawer */}
        {drawerOpen && (
          <div
            className="md:hidden fixed inset-0 z-[100] bg-black/60 backdrop-blur-sm flex items-end"
            onClick={() => setDrawerOpen(false)}
          >
            <div
              className="w-full bg-white rounded-t-3xl p-6 space-y-4 max-h-[85vh] overflow-y-auto"
              onClick={(e) => e.stopPropagation()}
            >
              <div className="w-10 h-1.5 bg-gray-200 rounded-full mx-auto" />
              <div className="flex items-center justify-between border-b border-gray-100 pb-3">
                <div>
                  <h3 className="font-black text-gray-900">Admin Panel</h3>
                  <p className="text-xs text-gray-400">{user?.name}</p>
                </div>
                <button
                  onClick={() => setDrawerOpen(false)}
                  className="w-8 h-8 bg-gray-100 rounded-full flex items-center justify-center"
                >
                  <X size={16} />
                </button>
              </div>
              <div className="grid grid-cols-2 gap-3">
                {[
                  {
                    href: '/admin/users',
                    icon: UsersIcon,
                    label: 'Users',
                    sub: 'Manage Accounts',
                    color: 'bg-blue-100 text-blue-600',
                  },
                  {
                    href: '/admin/banners',
                    icon: ImageIcon,
                    label: 'Banners',
                    sub: 'Promos & Slides',
                    color: 'bg-emerald-100 text-emerald-600',
                  },
                  {
                    href: '/admin/analytics',
                    icon: Trophy,
                    label: 'Analytics',
                    sub: 'Platform Stats',
                    color: 'bg-amber-100 text-amber-600',
                  },
                  {
                    href: '/admin/transactions',
                    icon: Receipt,
                    label: 'Transactions',
                    sub: 'Audit Logs',
                    color: 'bg-purple-100 text-purple-600',
                  },
                  {
                    href: '/admin/tasks',
                    icon: Zap,
                    label: 'Tasks',
                    sub: 'Earn Rules',
                    color: 'bg-orange-100 text-orange-600',
                  },
                  {
                    href: '/admin/terms',
                    icon: FileText,
                    label: 'Terms',
                    sub: 'Site Content',
                    color: 'bg-teal-100 text-teal-600',
                  },
                  {
                    href: '/admin/settings',
                    icon: Settings,
                    label: 'Settings',
                    sub: 'System Config',
                    color: 'bg-indigo-100 text-indigo-600',
                  },
                ].map((item) => (
                  <Link
                    key={item.href}
                    href={item.href}
                    onClick={() => setDrawerOpen(false)}
                    className="flex items-center gap-3 p-3 bg-gray-50 rounded-2xl border border-gray-100 hover:bg-gray-100 transition-colors"
                  >
                    <div className={`p-2 rounded-xl ${item.color}`}>
                      <item.icon size={18} />
                    </div>
                    <div>
                      <div className="font-bold text-gray-900 text-xs">{item.label}</div>
                      <div className="text-[10px] text-gray-400">{item.sub}</div>
                    </div>
                  </Link>
                ))}
              </div>
              <div className="border-t border-gray-100 pt-2">
                <button
                  onClick={() => {
                    setDrawerOpen(false);
                    logout();
                    router.push('/');
                  }}
                  className="w-full flex items-center justify-center gap-2 py-3 text-red-600 font-bold text-sm bg-red-50 rounded-2xl border border-red-100 hover:bg-red-100 transition-colors"
                >
                  <LogOut size={16} /> Sign Out
                </button>
              </div>
            </div>
          </div>
        )}

        <div className="h-16 md:hidden" />
      </>
    );
  }

  // ─── AUTHENTICATED USER (dashboard + all other pages) ───────
