                {/* Secondary: Add to Cart */}
                <button
                  onClick={handleAddToCart}
                  className={`w-full py-3.5 font-bold text-sm rounded-2xl transition-all flex items-center justify-center gap-2 border-2 active:scale-[0.99] ${
                    addedToCart
